```csharp
[ApiController]
[Route("api/html")]
public class HtmlController : ControllerBase
{
    private readonly ICMSService _cmsService;

    public HtmlController(ICMSService cmsService)
    {
        _cmsService = cmsService; 
    }

    [HttpPost("update")] // Endpoint for updating HTML content
    public async Task<IActionResult> UpdateHTML([FromBody] HtmlUpdateRequest request) // Data Transfer Object (DTO) to hold parameters
    {
        try
        {
            var isUpdated = await _cmsService.UpdateHTML(request.PageId, request.ElementId, request.Content); 

            if (!isUpdated) return StatusCode(500, "Failed to update HTML content");

            return Ok("Successfully updated HTML content"); 
        }
