```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <mysql/mysql.h>

typedef struct Record {
    int key;
} Record;

void* connect_to_database(void *arg) {
    MYSQL *conn = mysql_init(NULL);
    if (conn == NULL) {
        printf("Error %u: %s\n", mysql_errno(conn), mysql_error(conn));
        pthread_exit(NULL);
    }

    // Connect to the database
    if (mysql_real_connect(conn, "hostname", "username", "password", 
                           "database", 0, NULL, 0) == NULL) {
        printf("Error %u: %s\n", mysql_errno(conn), mysql_error(conn));
        mysql_close(conn);
        pthread_exit(NULL);
    }

    // Prepare the query
    const char *query = "SELECT unique_id FROM table";

    if (mysql_query(conn, query)) {
        printf("Error %u: %s\n", mysql_errno(conn), mysql_error(conn));
        mysql_close(conn);
        pthread_exit(NULL);
    }

    MYSQL_RES *result = mysql_store_result(conn);
    if (result == NULL) {
        printf("Error %u: %s\n", mysql_errno(conn), mysql_error(conn));
        mysql_close(conn);
        pthread_exit(NULL);
    }

    long *offset = malloc(sizeof(long) * mysql_num_rows(result));
    int *keys = malloc(sizeof(int) * mysql_num_rows(result));

    MYSQL_ROW row;
    unsigned long *lengths;
    int i = 0;

    // Fetch and store the rows in arrays
    while ((row = mysql_fetch_row(result)) != NULL) {
        lengths = mysql_fetch_lengths(result);

        offset[i] = lengths[0];
        keys[i] = atoi(row[0]);
        i++;
    }

    mysql_free_result(result);
    mysql_close(conn);

    Record *records = malloc(sizeof(Record) * i);
    for (int j = 0; j < i; j++) {
        records[j].key = keys[j];
    }

    free(keys);
    free(offset);

    pthread_exit((void *)records);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, connect_to_database, NULL)) {
        printf("Error creating thread\n");
        return 1;
    }

    Record *records = NULL;
    pthread_join(thread, (void **)&records);

    if (records == NULL) {
        printf("No records fetched from the database.\n");
    } else {
        // Use the records here...
    }

    free(records);
    return 0;
}
```

This is a simple example for an SQL server connection management function. It uses pthread library to handle concurrent operations and MySQL Connector/C API for database communication. Note that you'll need to replace `"hostname", "username", "password", "database"` with your own credentials, and the SELECT query should be modified accordingly according to your actual table schema. Also, this solution assumes that each record is a single 'int' identifier - if there are additional fields in the record structure, you can easily modify the Record structure definition and fetch rows accordingly.

Here is a Python code solution for the problem. This code uses the `hashlib`, `requests`, and `io` libraries to calculate SHA-256 hash of a file given its path. 

```python
import requests
import hashlib
import io
from urllib.parse import urlparse

def sha256sum(path_or_url: str, checksum=None):
    try:
        buffer_size = 1024 * 8

        # Check if the path is a URL or local file path
        parsed = urlparse(path_or_url)
        if all([parsed.scheme, parsed.netloc]):
            with requests.get(path_or_url, stream=True) as response:
                response.raise_for_status()  # Raise an exception for unsuccessful responses
                data = io.BytesIO(response.content)
        else:
            data = open(path_or_url, 'rb')

        hasher = hashlib.sha256()

        chunk = data.read(buffer_size)  # Read the file in chunks to handle large files
        while len(chunk) > 0:
            hasher.update(chunk)
            chunk = data.read(buffer_size)

        computed_hash = hasher.hexdigest()

        if checksum and computed_hash == checksum:
            return 'SUCCESS: Hash matched.'
        elif checksum:
            return 'ERROR: Hash mismatch!'
        else:
            return computed_hash

    except requests.exceptions.HTTPError as errh:
        return f'HTTP Error: {errh}'
    except requests.exceptions.ConnectionError as errc:
        return f'Error Connecting: {errc}'
    except requests.exceptions.Timeout as errt:
        return f'Timeout Error: {errt}'
    except requests.exceptions.RequestException as err:
        return f'Something went wrong: {err}'
```
This function reads the file in chunks and calculates its SHA-256 hash using `hashlib`. If a checksum is provided, it compares the computed hash with the given checksum and returns either 'SUCCESS: Hash matched.' or 'ERROR: Hash mismatch!' accordingly. It handles both local files and streaming files from URLs by checking whether the input path follows an URL scheme (e.g., "http://", "https://"). 

For error handling, it uses `requests` exceptions to handle HTTP errors, connection errors, timeouts, and other request-related exceptions. It also handles the case where a file cannot be accessed by returning a corresponding message.

Below is an implementation in JavaScript using Node.js, `aws-sdk`, and `winston` for logging. 

The example below does not include the code needed to extract metadata from files or chunking files due to complexity. It also assumes that you have properly set up your AWS S3 bucket and it's configured correctly with the necessary permissions. Please add these in accordance with your specific use case.

```javascript
const { S3 } = require('aws-sdk');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const urlParser = require('url');
const winston = require('winston');
const axios = require('axios').default;
const retry = require('async-retry');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.Console()]
});

const BUCKET_NAME = "your-bucket-name";
const MAXIMUM_FILE_SIZE = 50 * 1024 * 1024; // in bytes
const DEFAULT_RETRIES = 3;

async function uploadFileFromUrl(fileUrl, bucketName) {
    const s3 = new S3();

    try {
        let fileStream;
        if (urlParser.parse(fileUrl).protocol === "http:" || urlParser.parse(fileUrl).protocol === "https:") {
            logger.info('Downloading file...');
            const response = await axios({
                method: 'get',
                url: fileUrl,
                responseType: 'stream'
            });

            fileStream = response.data;
        } else {
            throw new Error(`Invalid URL: ${fileUrl}`);
        }

        const uniqueFileName = `${crypto.randomBytes(10).toString('hex')}.jpg`; // Use the proper extension here, not just .jpg
        logger.info(`File to be uploaded with name: ${uniqueFileName}`);

        let fileSize = fs.statSync(fileStream._path || '').size;
        if (fileSize > MAXIMUM_FILE_SIZE) {
            throw new Error('Split large files into chunks and handle sequential uploads');
        }

        const params = { Bucket: bucketName, Key: uniqueFileName, Body: fileStream };

        await retry(async (bail) => {
            try {
                logger.info('Uploading to S3...');
                let data = await s3.upload(params).promise();
                logger.info(`File uploaded successfully. URL is ${data.Location}`);
                return data;
            } catch (error) {
                throw error;
            }
        }, { retries: DEFAULT_RETRIES });

    } catch (error) {
        logger.error(`Failed to upload file from URL ${fileUrl}. Error: ${error}`);
        throw error;
    } finally {
        if (fileStream && fs.existsSync(fileStream._path || '')) fs.unlinkSync(fileStream._path || ''); // Clean up after ourselves
    }
}
```
