Here's an example using libcurl for networking and json-c for parsing JSON in C. This should give you a basic idea of how to structure your function:

```c
#include <stdio.h>
#include <string.h>
#include <json-c/json.h>
#include <curl/curl.h>

struct response_data {
    char *data;
};

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct response_data *response_data = (struct response_data *)userp;
    char *ptr = realloc(response_data->data, response_data->size + realsize + 1);

    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory.\n");
        return 0;
    }

    response_data->data = ptr;
    memcpy(&(response_data->data[response_data->size]), contents, realsize);
    response_data->size += realsize;
    response_data->data[response_data->size] = 0;

    return realsize;
}

int validateAccessToken(char *url) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl.\n");
        return -1;
    }

    struct response_data response_data;
    response_data.size = 0;
    response_data.data = malloc(1);  
    response_data.data[0] = '\0'; 

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&response_data);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform the request: %s\n", curl_easy_strerror(res));
        free(response_data.data);
        return -1;
    }

    json_object *json = json_tokener_parse(response_data.data);
    if (!json) {
        fprintf(stderr, "Failed to parse JSON.\n");
        free(response_data.data);
        return -1;
    }

    int isValid = 0;
    json_object *accessToken, *expiresIn, *tokenType;
    if (json_object_object_get_ex(json, "access_token", &accessToken) && accessToken &&
        json_object_object_get_ex(json, "expires_in", &expiresIn) && expiresIn &&
        json_object_object_get_ex(json, "token_type", &tokenType) && tokenType &&
        strcmp("Bearer", json_object_get_string(tokenType)) == 0) {
        isValid = 1;
    }

    json_object_put(json);
    free(response_data.data);
    curl_easy_cleanup(curl);

    return isValid;
}
```
This function performs a GET request to the specified URL, reads the response into a buffer, and parses it as JSON. It then checks if the required fields are present and have the correct values. The function returns 1 if the token is valid and 0 otherwise.

