Below is a simple implementation using `nlohmann/json` library for parsing JSON data.

```cpp
#include <iostream>
#include <fstream>
#include <mutex>
#include "json.hpp"

using json = nlohmann::json;

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> parseJson(const std::string& filename) {
    static std::mutex mtx; // Mutex for synchronization.

    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread-safety while accessing shared resources.

    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> settingsMap; 

    try {
        std::ifstream file(filename);

        if(!file) {
            throw std::runtime_error("Failed to open the file: " + filename);
        }

        json data = json::parse(file); // Parse JSON from a file.

        for (json::iterator it = data.begin(); it != data.end(); ++it) {
            if (it->is_number()) {
                if (it->is_number_integer()) 
                    settingsMap[it.key()] = it->get<int>(); // If it's an integer, add to map as int.
                else if(it->is_number_float())
                    settingsMap[it.key()] = it->get<double>(); // If float, add to map as double.
            } 
            else if (it->is_string()) {
                settingsMap[it.key()] = it->get<std::string>(); // If string, add to map as std::string.
            } 
            else if(it->is_boolean()) {
                settingsMap[it.key()] = it->get<bool>(); // If boolean, add to map as bool.
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return settingsMap; 
}
```
This solution is scalable and performs well for large JSON files because it reads the file line by line, avoiding loading the whole JSON data into memory at once. Also, using a `std::mutex` to ensure thread safety when concurrent accesses occur. However, you might want to adjust according to your requirements if you are dealing with very large or complex JSON structures and specific performance considerations.

