namespace RandomGenerator {
    class MT19937Generator {
        private:
            std::mt19937 gen;
            uint32_t seed;
            std::uniform_int_distribution<uint32_t> *dist = nullptr;
            std::mutex mtx;  // For thread safety

        public:
            MT19937Generator(uint32_t seed) : gen(seed), seed(seed){
                if (seed == 0) {
                    throw std::invalid_argument("Seed value cannot be zero.");
                }
            };

            ~MT19937Generator() = default;  // Trivial destructor

            void configureDistribution(uint32_t min, uint32_t max) {
                if (min > max || min == max){
                    throw std::invalid_argument("Invalid range.");
                }

                mtx.lock();  // Locking for thread safety
                dist = new std::uniform_int_distribution<uint32_t>(min, max);
                mtx.unlock();  // Unlock after operation
            };

            uint32_t getRandomNumber() {
                if (dist == nullptr) {
                    throw std::invalid_argument("Distribution has not been configured yet.");
                }

                mtx.lock();  // Locking for thread safety
                auto res = (*dist)(gen);
                mtx.unlock();  // Unlock after operation
                return res;
            };

            void integrateWithDatabase() {
                // TODO: Code to interact with the external database
            }
    };
}
