In the following code, I will keep it simple and generate values using the `UnityEngine.Random` class for simplicity. 

```csharp
using System;
using Random = UnityEngine.Random;

public abstract class Distribution { }

public class UniformDistribution : Distribution {}

public class GaussianDistribution : Distribution { }

public class ValueGenerator
{
    private float minValue;
    private float maxValue;
    private Distribution distribution = new UniformDistribution(); // Default to uniform distribution

    public ValueGenerator(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Min must be less than Max");

        this.minValue = min;
        this.maxValue = max;
    }

    // Method for returning a random float value within the specified range, both inclusively and exclusively
    public float GetRandomFloat(bool inclusive)
    {
        if (inclusive)
            return Random.Range(minValue, maxValue + 1);

        return Random.Range(minValue, maxValue);
    }

    // Method for returning a random integer value within the specified range, both inclusively and exclusively
    public int GetRandomInt(bool inclusive)
    {
        if (inclusive)
            return (int)GetRandomFloat(true);

        float f = Random.Range(minValue, maxValue + 1); // Generate float value
        return f > (float)Math.Ceiling(f) ? (int)Math.Floor(f) : (int)Math.Ceiling(f); // Convert to int
    }

    public override string ToString() 
    {
       return $"ValueGenerator: Min={minValue}, Max={maxValue}, Distribution={distribution.GetType().Name}";
    }

    // Integration with an external configuration system that can store and retrieve different types of distributions
    public void SetDistribution(Distribution distribution) 
    {
        this.distribution = distribution;
    }
}
```

