#include <stdio.h>
#include <stdlib.h>

void sort(int *array, int n) {
    // Implement a basic bubble sort to sort array in ascending order
    for (int i = 0; i < n - 1; i++){
        for (int j = i + 1; j < n; j++){
            if (array[i] > array[j]){
                int temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }
}

int main() {
    FILE *file = fopen("integers.txt", "r"); // Open file in read mode

    if (file == NULL) {
        printf("Failed to open the file.\n");
        return 1; // Return error code 1 if failed to open file
    }

    int array[1024]; // Assuming list won't have more than 1024 numbers. Adjust according to your needs.
    int i = 0;

    while (fscanf(file, "%d", &array[i]) == 1) {
        i++;
    }

    fclose(file); // Close the file after reading

    if(i > 0){
        sort(array, i); // Sort array before finding largest integer.
        printf("Largest number: %d\n", array[i-1]);
    } else {
        printf("File is empty or does not contain valid integers.\n");
    }

    return 0;
}
```
