Please note, this is an abstract representation of the code. You may have to adapt it according to your specific requirements:

```python
import requests
import json
from contextlib import closing
import logging

class Configuration:
    def __init__(self, path=None):
        self._settings = {}

        if path is not None:
            with open(path) as f:
                self.update_configs(json.load(f))

    @property
    def settings(self):
        return self._settings

    def update_configs(self, new_settings):
        self._settings.update(new_settings)

class ConfigLoader:
    def __init__(self, config_obj, api_url=None):
        self._api_url = api_url
        self._config_obj = config_obj

    def load_from_file(self, path):
        with open(path) as f:
            new_settings = json.load(f)

        logging.info('Loading configuration from local file completed')
        return self._config_obj.update_configs(new_settings)

    def load_from_api(self):
        if self._api_url is not None:
            with closing(requests.get(self._api_url)) as response:
                response.raise_for_status()

                new_settings = response.json()

            logging.info('Loading configuration from API completed')
            return self._config_obj.update_configs(new_settings)
        else:
            raise ValueError("API URL is not set")

    def load_all(self, file_path=None):
        if file_path:
            try:
                self.load_from_file(file_path)
            except Exception as e:
                logging.error('Failed to load configuration from local file', exc_info=e)

        try:
            self.load_from_api()
        except Exception as e:
            logging.error('Failed to load configuration from API', exc_info=e)
``` 
