    pthread_mutex_lock(&gMutex);
    if(cmdResult != 0) {
        gExitStatus = 1;
        logProgress("Error converting %s to %s", jpegFile, pdfFile);
    } else {
        logProgress("%s converted to %s successfully", jpegFile, pdfFile);
    }
    pthread_mutex_unlock(&gMutex);

    // Clean up metadata after conversion
    cleanupImageMetaData(metaData);
    free(args);

