}

int convertJpgToPdfAsync(const char *jpegFile, const char *pdfFile) {
    int numChunks = calculateNumberOfChunks(); // Replace with actual chunk calculation
    if (numChunks <= 0 || !validateNumericValue(numChunks)) {
        logProgress("Invalid number of chunks");
        return 1;
    }

    pthread_t * threads = malloc(numChunks * sizeof(pthread_t));

    // Split the file processing into smaller chunks and start conversion in separate threads
    for (int i = 0; i < numChunks; ++i) {
        ThreadArgs* args = malloc(sizeof(ThreadArgs));

        // Assign arguments to the chunk thread
        args->jpegFile = jpegFile;
        args->pdfFile = pdfFile;

        if (pthread_create(&threads[i], NULL, &chunkConversion, args) != 0) {
            logProgress("Thread creation failed");
            gExitStatus = 1; // exit status will be 1 in case of error
            break;
        }
    }

    // Wait for all threads to finish and collect results
    for (int i = 0; i < numChunks; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);

    return gExitStatus;  // returns 0 on success, 1 in case of error.
}
