#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>
#include <thread>
#include "json.hpp"
using json = nlohmann::json;

std::mutex mtx;  // mutex for thread-safe reading and writing

// Function to load settings from a JSON file
void loadConfig(const std::string& filename, std::unordered_map<std::string, std::variant<int, double, std::string, bool>>& config) {
    std::lock_guard<std::mutex> lock(mtx);
    std::ifstream i(filename);
    json j;
    i >> j;

    for (json::iterator it = j.begin(); it != j.end(); ++it) {
