using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using ThirdPartyLoggingLibrary;

public class UserPreferenceCacheLoader
{
    private readonly CustomLogger _logger = new CustomLogger(); // Assuming this is from the third-party logging library
    private readonly ICustomCachingMechanism _cachingMechanism; // Custom caching mechanism
    private readonly IDatabaseProvider _databaseProvider; // Database provider for fallback

    public UserPreferenceCacheLoader(ICustomCachingMechanism cachingMechanism, IDatabaseProvider databaseProvider)
    {
        _cachingMechanism = cachingMechanism;
        _databaseProvider = databaseProvider;
    }

    public async Task LoadAndDeserializePreferencesFromBinaryFile(string filePath)
    {
        if (_cachingMechanism.IsAvailable()) // Check if the cache is available and ready to use
        {
            try
            {
                if (!_cachingMechanism.HasCachedData("preferences")) // If there's no cached data yet
                {
                    await Task.Run(() => // Use Task.Run for better concurrency handling, potentially in a larger system you might want to use a thread pool
                    {
                        if (File.Exists(filePath)) // Check if the binary file exists
                        {
                            using (Stream stream = File.OpenRead(filePath))
                            {
                                BinaryFormatter formatter = new BinaryFormatter();
                                UserPreferences userPrefs = (UserPreferences)formatter.Deserialize(stream); // Deserialize the data

                                _cachingMechanism.AddToCache("preferences", userPrefs); // Cache the deserialized data
                            }
                        }
                        else
                        {
                            LoadAndUpdateDataFromDatabase(); // Fallback to database if binary file is not available or corrupted
                        }
                    });
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex);

                LoadAndUpdateDataFromDatabase(); // In case of any error, load from the database as a fallback
            }
        }
    }

    private void LoadAndUpdateDataFromDatabase()
    {
        try
        {
            var userPrefs = _databaseProvider.GetUserPreferences(); // Fetch data from the database

            if (userPrefs != null) 
                _cachingMechanism.AddToCache("preferences", userPrefs); // Cache the fetched data
        }
        catch (Exception ex)
        {
            _logger.LogError(ex);
        }
    }
}
