Here's a basic implementation based on your description. It uses an external data source (Map) to get class definitions, uses a cache for frequently used classes and validates byte array integrity before deserialization. 

```java
import java.io.*;
import java.util.*;
import java.lang.reflect.*;

public class DynamicNestedDeserializer {
    private final Map<String, Class<?>> classMap;
    private final LRUCache<Class<?>, Constructor<?>> constructorCache;

    public DynamicNestedDeserializer() {
        this.classMap = new HashMap<>();
        this.constructorCache = new LRUCache<>(100); // size can be adjusted according to your needs
    }

    public Object deserializeObjectFromBytes(byte[] data) throws ClassNotFoundException, IOException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data)) {
            try (ObjectInputStream in = new ObjectInputStream(bis)) {
                return in.readUnshared(); // for performance optimization, readUnshared method uses the stream's hand-off object if available
            }
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error occurred while deserializing: " + e.getMessage());
            throw e;
        }
    }

    public Object deserializeNestedObjects(byte[] data, String className) throws IOException, ClassNotFoundException {
        if (!classMap.containsKey(className)) {
            // retrieve class definition from external source and add to map
            Class<?> clazz = getClassDefinitionFromExternalSource(className); 
            classMap.put(className, clazz);
        }

        return deserializeNestedObjectsWithCache(data, className);
    }

    private Object deserializeNestedObjectsWithCache(byte[] data, String className) throws IOException, ClassNotFoundException {
        Class<?> clazz = classMap.get(className);

        Constructor<?> constructor = constructorCache.get(clazz);
        if (constructor == null) {
            constructor = clazz.getConstructor();
            constructorCache.put(clazz, constructor);
        }

        try {
            return constructor.newInstance();
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException e) {
            throw new IOException("Error occurred while instantiating object: " + e.getMessage());
        }
    }

    private Class<?> getClassDefinitionFromExternalSource(String className) throws ClassNotFoundException {
        // retrieve class definition from external source and add to map 
        return Class.forName(className); // replace with actual implementation of retrieving class definitions from your data source
    }

    private static class LRUCache<K, V> extends LinkedHashMap<K, V> {
        private int cacheSize;

        public LRUCache(int cacheSize) {
            super(16, 0.75f, true); // access order, initial capacity can be adjusted based on expected number of classes
            this.cacheSize = cacheSize;
        }

        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > cacheSize;
        }
    }
}
``` 

