```javascript
const { createLogger } = require('winston'); // replace with your actual logger service
const logger = createLogger({ level: 'info' });

class CanceledError extends Error {
  constructor() {
    super('Canceled');
    this.name = 'CanceledError';
  }
}

async function asyncReduce(array, initValues, callback) {
  const cancellationTokens = Array.from({ length: array.length }, () => false);

  let results;
  try {
    results = await Promise.all(initValues.map((value, index) => new Promise(async (resolve, reject) => {
      try {
        let currentValue = value;
        for (let i = 0; i < array.length; ++i) {
          if (cancellationTokens[i]) {
            throw new CanceledError();
          }

          logger.info(`Processing element at index ${i} with initial value ${currentValue}`);
          currentValue = await callback(currentValue, array[i]); // replace this line with actual processing
        }

        resolve(currentValue);
      } catch (error) {
        logger.error(`Error occurred while reducing element at index ${index}: ${error}`);
        reject(error);
      }
    })));
  } catch (error) {
    if (!(error instanceof CanceledError)) {
      throw error;
    }

    logger.info('Reduction was canceled');
  } finally {
    cancellationTokens.fill(true); // cleanup
  }

  return results;
}

// Testing
async function test() {
  const array = [1, 2, 3, 4, 5];
  const initValues = [0, 10];

  try {
    const results = await asyncReduce(array, initValues, (accumulator, value) => {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          // Simulate error for some values
          if (value === 3 || value === 5) {
            reject(new Error('Simulated error'));
          } else {
            resolve(accumulator + value);
          }
        }, 1000 * Math.random());
      });
    });

    console.log(results); // Expected output: [15, 25]
  } catch (error) {
    console.error('An error occurred during reduction:', error);
  }
}

test();
```
