        scanf("%d", &arr[i]);
    }

    printf("The largest number in the array is %d\n", find_largest(arr, size));

    create_and_delete_sem(0);

    return 0;
}

int find_largest(int arr[], int size) {
    int max = INT_MIN;

    for (int i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

void create_and_delete_sem(int initial_value) {
    sem_t *semaphore = sem_open("mySemaphore", O_CREAT, 0644, initial_value);

    // Check if the semaphore was created successfully
    if (SEM_FAILED == semaphore) {
        perror("Failed to create semaphore");
        return;
    }

    printf("Semaphore 'mySemaphore' created with initial value %d\n", initial_value);

    // Deleting the semaphore after use
    if (-1 == sem_close(semaphore)) {
        perror("Failed to close semaphore");
    } 
    else if (-1 == sem_unlink("mySemaphore")) {
        perror("Failed to unlink (delete) semaphore");
    }
}
