@Service
public class DynamicNestedDeserializer {
    private static final String CLASS_INFO_API = "https://api.example.com/classes";

    @Autowired
    RestTemplate restTemplate;

    @Autowired
    CacheManager cacheManager;

    ObjectMapper mapper = new ObjectMapper();

    // Get class definitions and constructors from API 
    @Retryable(value={IOException.class}, maxAttempts = 5, backoff = @Backoff(delay = 1000))
    public ClassInfo fetchClassInfo() {
        return restTemplate.getForObject(CLASS_INFO_API, ClassInfo.class);
    }

    // Caching fetched class info
    @Cacheable("classCache")
    public Map<String, Class> getCachedClasses(){
        return fetchClassInfo().getClasses();
    }

    // Deserialize byte array to object
    @Async
    public Object deserialize(byte[] data, String className) throws Exception {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data); 
             ObjectInput in = new ObjectInputStream(bis)) {
            Map<String, Class> classes = getCachedClasses();
            if(!classes.containsKey(className)){
                throw new ClassNotFoundException("Class not found: " + className);
            }
            Constructor constructor = classes.get(className).getConstructor();
            return constructor.newInstance();
        } catch (IOException | IllegalAccessException | InstantiationException ex) {
            // Handle exceptions here. Log and re-throw with custom exceptions.
            throw new IOException("Error while deserializing the byte array.", ex);
        } 
    }
}
