```CSharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Text;

public static string CalculateMD5Hash(string filePath)
{
    try
    {
        using (var md5 = MD5.Create())
        {
            const int bufferSize = 4096;
            var buffer = new byte[bufferSize];

            using (var stream = File.OpenRead(filePath))
            {
                int bytesRead;
                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    md5.TransformBlock(buffer, 0, bytesRead, buffer, 0);
                }

                // TransformFinalBlock is necessary for finishing the hash computation
                md5.TransformFinalBlock(buffer, 0, 0);
            }

            return BitConverter.ToString(md5.Hash).Replace("-", "").ToLower();
        }
    }
    catch (IOException ex)
    {
        Console.WriteLine($"I/O Exception: {ex.Message}");
    }
    catch (UnauthorizedAccessException ex)
    {
        Console.WriteLine($"Unauthorized Access Exception: {ex.Message}");
    }
    catch (NotSupportedException ex)
    {
        Console.WriteLine($"Not Supported Exception: {ex.Message}");
    }

    return null;
}
```

