use std::time::{Instant};
use std::process::Command;
use anyhow::Result;
use futures_util::compat::CompatExt;

fn send_bytes(input: Vec<u8>) -> Result<DataTableReader> {
    let start = Instant::now(); // Record the starting time.

    let input_str = String::from_utf8(input)?; // Convert the byte array to a string.

    let hook = SyncLazy::new(move || {
        early_error().install_ice_hook() // Install an ice hook using the `SyncLazy` module.
    });

    let output = Command::new("command") // Create command.
                     .arg(&input_str)
                     .output()?; // Execute command and catch any errors.

    let duration = start.elapsed(); // Measure time taken for conversion & execution of the command.

    match String::from_utf8(output.stdout)? { // Check if database operation was successful.
        Ok(result) => Ok(DataTableReader::new(&result)), 
        Err(_) => {
            let err = formatError("Database operation failed!"); // Create error message.
            early_error().report(err); // Report errors using the `early_error` function.
            return Err(anyhow::format_err(err));
        }
    };
}
