```javascript
const fs = require('fs');
const axios = require('axios');
const path = require('path');

function readFileSync(filePaths) {
    // If filePaths is not an array, convert it into one for uniform processing
    if (!Array.isArray(filePaths)) {
        filePaths = [filePaths];
    }

    return filePaths.map((filePath) => {
        try {
            const extName = path.extname(filePath);

            // Validate the file extension
            if (!['.txt', '.md', '.json'].includes(extName)) {
                throw new Error('Invalid file extension');
            }

            // Get metadata from external API
            const response = axios.get('/metadata', { params: { filePath: filePath } });

            return {
                content: fs.readFileSync(filePath, 'utf8'),
                metadata: response.data
            };
        } catch (err) {
            if (err instanceof Error && err.code === 'ENOENT') {
                console.error('File not found:', filePath);
            } else if (err.message === 'Request failed with status code 404') {
                console.error('Metadata for file not found on API:', filePath);
            } else {
                console.error(`Failed to read ${filePath}:`, err.message);
            }
            return null; // Or throw the error if needed
        } finally {
            // Close file handle here (if any)
        }
    });
}
```

