                logger.Error(errorMessage);
                throw new Exception(errorMessage);
            }

            // Add website to the server using an external API...

            // Start website on the server using an external API...

            return "Website started successfully";
        }
        catch (Exception ex)
        {
            logger.Error(ex, $"Failed to add and start website: {siteName}");
            throw;
        }
    }

    public async Task<string> CalculateFileMD5HashAsync(string filePathOrUrl, int chunkSize = 1024)
    {
        try
        {
            byte[] buffer = new byte[chunkSize];

            using (var cryptoServiceProvider = new MD5CryptoServiceProvider())
            {
                using (Stream stream = File.Exists(filePathOrUrl) ? 
                            (Stream)File.OpenRead(filePathOrUrl) : 
                            await DownloadAndResumeAsync(filePathOrUrl))
                {
                    int read;

                    while ((read = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                    {
                        cryptoServiceProvider.TransformBlock(buffer, 0, read, buffer, 0);
                    }

                    return BitConverter.ToString(cryptoServiceProvider.Hash).Replace("-", "").ToLower();
                }
            }
        }
        catch (Exception ex)
        {
            logger.Error(ex, $"Failed to calculate MD5 hash of file: {filePathOrUrl}");
            throw;
        }
    }

    private async Task<Stream> DownloadAndResumeAsync(string url)
    {
        var request = WebRequest.CreateHttp(url);

        // Set range header to get bytes from a specific point forward, for resuming downloads...

        using (var response = await request.GetResponseAsync())
        using (var responseStream = response.GetResponseStream())
        {
            var memoryStream = new MemoryStream();

            if(responseStream != null) 
                await responseStream.CopyToAsync(memoryStream);

            memoryStream.Position = 0;
            return memoryStream;
        }
    }
}
```
