```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int incoming;
    int outgoing;
} TrafficStats;

typedef struct {
    char UserId[10];
    char SessionId[20];
    TrafficStats stats;
} UserSession;

#define MAX_SESSIONS 50
UserSession sessions[MAX_SESSIONS];
int sessionCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void generateRandomTraffic(TrafficStats *stats) {
    stats->incoming = rand() % 1024 * 1024; // Random bytes within a MB range
    stats->outgoing = rand() % 1024 * 1024;
}

void addUserSession(char* userId, char* sessionId) {
    pthread_mutex_lock(&lock);

    if (sessionCount >= MAX_SESSIONS) {
        pthread_mutex_unlock(&lock);
        return;
    }

    UserSession *newSession = &sessions[sessionCount];
    strncpy(newSession->UserId, userId, sizeof(newSession->UserId) - 1);
    newSession->UserId[sizeof(newSession->UserId) - 1] = '\0';

    strncpy(newSession->SessionId, sessionId, sizeof(newSession->SessionId) - 1);
    newSession->SessionId[sizeof(newSession->SessionId) - 1] = '\0';

    generateRandomTraffic(&newSession->stats);

    sessionCount++;

    pthread_mutex_unlock(&lock);
}
```
This C code includes a UserSession and TrafficStats structure, along with an array to hold the sessions. The `addUserSession` function manages adding a new user session to the list, ensuring thread safety using a mutex lock. It also checks if the maximum number of sessions has been reached before adding. If so, it immediately releases the lock and returns without doing anything else.

