```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.IO;
using System.Diagnostics;
using Serilog; // You can use any logging library here, for example NLog or Log4Net

public class AesDecrypter {
     private readonly byte[] key;
     private readonly byte[] iv;
     private readonly PaddingMode paddingMode;
     private static readonly ILogger logger = new LoggerConfiguration().CreateLogger(); // Initialize the logger

     public AesDecrypter(byte[] key, byte[] iv, PaddingMode paddingMode) {
          if (key == null || key.Length != 16 && key.Length != 24 && key.Length != 32) {
               throw new CryptographicException("Key must be 16, 24 or 32 bytes long");
          }

          if (iv == null || iv.Length != 16) {
               throw new CryptographicException("IV must be 16 bytes long");
          }

          this.key = key;
          this.iv = iv;
          this.paddingMode = paddingMode;
     }

     public byte[] Decrypt(byte[] ciphertext) {
          try {
               Stopwatch stopwatch = new Stopwatch(); // Start the timer
               stopwatch.Start();

               using (Aes aesAlg = Aes.Create()) {
                    aesAlg.Key = key;
                    aesAlg.IV = iv;
                    aesAlg.Padding = paddingMode;

                    ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                    using (MemoryStream msDecrypt = new MemoryStream(ciphertext)) {
                         using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) {
                              using (BinaryReader br = new BinaryReader(csDecrypt)) {
                                   byte[] decryptedBytes = br.ReadBytes((int) msDecrypt.Length);
                                   stopwatch.Stop(); // Stop the timer

                                   logger.Information("Successfully decrypted ciphertext in {ElapsedMilliseconds}ms", stopwatch.ElapsedMilliseconds);
                                   return decryptedBytes;
                              }
                         }
                    }
               }
          } catch (Exception ex) {
               logger.Error(ex, "An error occurred during decryption");
               throw new CryptographicException("Decryption failed", ex);
          }
     }
}
``` 
