```java
import java.util.*;
import java.time.*;

public class DisjointPairs {
    private static class UnionFind{
        int[] parent;
        int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++){
                parent[i] = i;
                rank[i] = 1;
            }
        }

        public int find(int x) {
            if (parent[x] != x)
                parent[x] = find(parent[x]);

            return parent[x];
        }

        public void union(int x, int y){
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                if (rank[rootX] > rank[rootY])
                    parent[rootY] = rootX;
                else if (rank[rootX] < rank[rootY])
                    parent[rootX] = rootY;
                else{
                    parent[rootY] = rootX;
                    rank[rootX] += 1;
                }
            }
        }
    }

    public static int countDisjointPairs(int[] nums, boolean removeDuplicates) {
        // If duplicates are requested to be removed, convert the array into a HashSet and then back into an array.
        if (removeDuplicates){
            Set<Integer> set = new HashSet<>();

            for(int i : nums){
                set.add(i);
            }

            int[] uniqueNums = new int[set.size()];
            int index = 0;

            for(Integer val: set) {
                uniqueNums[index++] = val;
            }

            nums = uniqueNums;
        }

        UnionFind uf = new UnionFind(nums.length);
        Instant startTime = Instant.now();

        // Check pairs and union them if disjoint.
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] != nums[j]) {
                    uf.union(i, j);
                }
            }
        }

        Instant endTime = Instant.now();
        long duration = Duration.between(startTime, endTime).toMillis();

        System.out.println("Time to calculate: " + duration + " ms");

        // Count the number of disjoint pairs by checking the roots of all elements in the Union-Find data structure.
        int count = 0;

        for (int i = 0; i < nums.length; i++) {
            if (uf.parent[i] == i){
                count++;
            }
        }

        return count/2;  // Divide by 2 as each pair is counted twice.
    }
}
```
