function updateClinicStatus($clinic_id, $new_status, $last_modified_ip, $stakeholder_api_key) {
    // Connect to the database
    $pdo = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

    try {
        // Start transaction
        $pdo->beginTransaction();

        // Prepare update query using prepared statements
        $stmt = $pdo->prepare("UPDATE clinics SET status = :status, last_modified_ip = :last_modified_ip, 
                               last_modified_date = now() WHERE id = :clinic_id AND last_modified_date < DATE_SUB(now(), INTERVAL 1 MINUTE)");

        // Execute query with new values for status and IP address
        $stmt->execute(['status' => $new_status, 'last_modified_ip' => $last_modified_ip, 'clinic_id' => $clinic_id]);

        // Check if any rows were affected by the query. If none were, return an appropriate error message.
        $rowCount = $stmt->rowCount();
        if($rowCount === 0) {
            throw new Exception('Too many updates in the last minute');
        }

        // Commit transaction
        $pdo->commit();
    } catch (Exception $e) {
        // Rollback transaction on error
        $pdo->rollBack();

        // Log the error to a file named 'error_log.txt'
        file_put_contents('error_log.txt', date("Y-m-d H:i:s") . " - Error in updating clinic status for clinic ID {$clinic_id}: {$e->getMessage()}\n", FILE_APPEND);

        return 'An error occurred while trying to update the clinic status. Please try again later.';
