#include <sqlite3.h> // Example usage of SQLite for database connection

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct {
    sqlite3* db;
    char* server_name;
} DbConnection;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

DbConnection* create_connection(const char* server, const char* database) {
    sqlite3 *db;
    if (sqlite3_open(database, &db) != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return NULL;
    }

    DbConnection* conn = malloc(sizeof(*conn));
    if (conn == NULL) {
        fprintf(stderr, "Failed to allocate memory for connection\n");
        return NULL;
    }

    conn->db = db;
    conn->server_name = strdup(server);

    return conn;
}

void close_connection(DbConnection* conn) {
    if (conn != NULL) {
        sqlite3_close(conn->db);
        free(conn->server_name);
        free(conn);
    }
}

int read_records(const char* query, DbConnection** conns, int num_connections, Record*** records) {
    *records = malloc(num_connections * sizeof(Record*)); // Adjust as needed

    for (int i = 0; i < num_connections; ++i) {
        pthread_mutex_lock(&lock);

        if ((*records)[i] == NULL && conns[i]->db != NULL) {
            char *errmsg;

            sqlite3_exec(conns[i]->db, query, [](void*, int argc, char **argv, char **azColName){/* ... */}, 0, &errmsg); // Populate records here based on the schema of your tables.

            if (errmsg != NULL) {
                fprintf(stderr, "SQL error: %s\n", errmsg);
                sqlite3_free(errmsg);
                pthread_mutex_unlock(&lock);
                return 0; // Or handle other errors as needed
            }
        } else if (conns[i]->db == NULL) {
            fprintf(stderr, "Cannot read from database on server: %s\n", conns[i]->server_name);
        }

        pthread_mutex_unlock(&lock);
    }

    return 1; // Success
}
```

