    [Route("api/[controller]")]
    [ApiController]
    public class PageUpdateController : ControllerBase
    {
        private readonly IContentService _contentService;
        private readonly ICachingSystem _cachingSystem;

        // Constructor Injection
        public PageUpdateController(IContentService contentService, ICachingSystem cachingSystem) 
        {
            _contentService = contentService;
            _cachingSystem = cachingSystem;
        }

        [HttpPost("{sectionId}/{elementId}")]
        public async Task<IActionResult> UpdateElement(Guid sectionId, Guid elementId, string htmlContent) 
        {
            // Input validation
            if (sectionId == null || elementId == null || String.IsNullOrWhiteSpace(htmlContent)) 
                return BadRequest("Invalid input parameters");

            // Check user permissions
            if (!_contentService.UserHasPermissionToUpdate(elementId))
                return Unauthorized("User does not have permission to update the element");

            try 
            {
                // Acquire a lock on the section to prevent race conditions
                await _cachingSystem.AcquireLockAsync(sectionId);

                // Perform updates atomically using a transaction or other atomic operations mechanism provided by your data store
                if(!await _contentService.UpdateElementHtmlContentAtomicAsync(elementId, htmlContent)) 
                    return StatusCode((int)HttpStatusCode.InternalServerError, "Failed to update the element");

            }
            catch (Exception ex) 
            {
                // Handle all unhandled exceptions here
                return StatusCode((int)HttpStatusCode.InternalServerError, $"An error occurred: {ex.Message}");
            }
            finally 
            {
                // Release the lock so that other threads can acquire it and perform operations on this section
                await _cachingSystem.ReleaseLockAsync(sectionId);
            }

            return Ok("Page should be refreshed");
        }
    }
}
```

