Now create a Union-Find (disjoint set) data structure:
```cpp
class DisjointSet {
public:
    DisjointSet(int n) : parent(n), rank(n, 0) {
        for(int i = 0; i < n; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unionSets(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) {
            return;
        }
        if (rank[px] > rank[py]) {
            parent[py] = px;
        } else {
            parent[px] = py;
            if (rank[px] == rank[py]) {
                ++rank[py];
            }
        }
    }
private:
    std::vector<int> parent, rank;
};
```
