Below is an implementation of your problem in C for limiting string size and sorting a text file:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Function to limit string size
char *limitStringSize(const char* str, int limit) {
    if (strlen(str) > limit) {
        return NULL;
    } 

    // Allocate memory for new string with an extra space for the slash
    char* newStr = malloc(limit + 2);
    strcpy(newStr, str);
    strcat(newStr, "/");
    return newStr;
}

int compareFunc(const void *a, const void *b) { 
    // Comparing all lines lexicographically for sorting
    return strcmp(*(char **)a, *(char **)b);
}

// Function to extract sequence number from last line in a sorted file
int extractSequenceNumberFromFile(FILE* fp) {
    char buffer[1024];
    char** lines = NULL;
    int numLines = 0, i;

    // Reading the file line by line
    while (fgets(buffer, sizeof(buffer), fp)) { 
        lines = realloc(lines, sizeof(*lines) * (numLines + 1));

        if (!lines) {
            printf("Error allocating memory.\n");
            return -1;
        }

        lines[numLines] = malloc(strlen(buffer) + 1); 
        strcpy(lines[numLines], buffer);
        numLines++;
    }

    // Sorting the lines lexicographically
    qsort(lines, numLines, sizeof(*lines), compareFunc);

    char* lastLine = lines[numLines - 1];
    int seqNum;

    // Extracting sequence number from the last line
    if (sscanf(lastLine, "%*[^0-9]%d", &seqNum) != 1) {
        printf("Could not extract sequence number from file.\n"); 
        return -1;
    }

    for(i = 0; i < numLines; ++i) {
        free(lines[i]); // Freeing memory allocated for each line
    }
    free(lines); // Freeing the array that holds lines

    return seqNum;
}
```
