def extract_sequence_number(filename):
  try:
    with open(filename, 'r') as f:
      lines = f.readlines()
      if not lines:
        return None

      # sorting the lines lexicographically
      lines.sort()

      last_line = lines[-1]
      seq_num = int(''.join(filter(str.isdigit, last_line)))
      return seq_num
  except Exception as e:
    print("Error occurred while processing the file: ", str(e))
```
