    public async Task<byte[]> DecryptFileAsync(string ciphertext, PaddingMode padding)
    {
        byte[] keyBytes;
        byte[] ivBytes;

        try
        {
            (keyBytes, ivBytes) = await _dbService.GetKeyAndIV(); // hypothetical method to retrieve the keys from DB

            using(Aes aesAlgorithm = Aes.Create())
            {
                var ciphertextBytes = Convert.FromBase64String(ciphertext);

                if (aesAlgorithm == null) throw new CryptographicException("Could not create AES algorithm instance.");

                ICryptoTransform decryptor = aesAlgorithm.CreateDecryptor(keyBytes, ivBytes);

                using(MemoryStream msDecrypt = new MemoryStream(ciphertextBytes))
                {
                    using(CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        var plaintextBytes = new byte[ciphertextBytes.Length];

                        int bytesRead = await csDecrypt.ReadAsync(plaintextBytes, 0, plaintextBytes.Length);

                        if (bytesRead < plaintextBytes.Length)
