def process_file(filename):
    # Processes a single file and returns its summary statistics and metadata.
    try:
        with open(filename, 'r') as f:
            content = f.read()

        validate(filename, content) 

        # Fetching the log level and time range would require an external API call.
        response = analytics.get_metadata(content)

    except FileNotFoundError:
        print(f'File not found: {filename}')
        return None
    except json.JSONDecodeError:
        print(f'Invalid JSON in file: {filename}')
        return None
    except analytics.APIRequestFailedException as e:
        # You would need to define an exception class for failed API requests 
        print(f'Failed to get metadata from API for file: {filename}. Reason: {str(e)}')
        return None

    return response

def process_files(filenames):
    # Processes multiple files concurrently using a ThreadPoolExecutor.
    with futures.ThreadPoolExecutor() as executor:
        future_to_filename = {executor.submit(process_file, filename): filename for filename in filenames}

        results = {}
        for future in futures.as_completed(future_to_filename):
            filename = future_to_filename[future]

            try:
                data = future.result()
            except Exception as exc:
                print(f'Exception while processing file {filename}: {exc}')
            else:
                results[filename] = data

    return results

def process_directory(dirname):
    # Processes all log files in a directory.
    filenames = [os.path.join(dirname, f) for f in os.listdir(dirname) if f.endswith('.log') or f.endswith('.json') or f.endswith('.csv')]

    return process_files(filenames)
