                string content = await client.DownloadStringTaskAsync(url);

                // Check if caching is necessary and the cache size won't exceed limit 
                long newCacheSize = Interlocked.Add(ref currentCacheSize, content.Length);

                if (newCacheSize <= CacheSizeLimit) {
                    DateTime expirationTime = DateTime.UtcNow.AddSeconds(CacheDuration);

                    // Use TryAdd so as not to replace any valid data
                    cache.TryAdd(url, Tuple.Create(expirationTime, content));
                } else {
                    Interlocked.Add(ref currentCacheSize, -content.Length); 
