from flask import Flask, request
from authlib.integrations.flask_oauth2 import AuthorizationServer, ResourceProtector
from werkzeug.security import gen_salt
import time

app = Flask(__name__)
# Initialize OAuth2 server and resource protector
require_oauth = ResourceProtector()
server = AuthorizationServer(app)

tokens = {}  # Store generated tokens in memory, use a real DB for production
rate_limits = {}

@app.route('/generate_token', methods=['POST'])
def generate_token():
    client = authenticate_client()  # Implement your own client authentication logic
    if not client:
        return {"error": "authentication failed"}, 401
    token = gen_salt(50)  # Generate secure token of length 50
    tokens[token] = int(time.time())  # Store the time when token was generated
    return {'access_token': token}

@app.route('/resource', methods=['POST'])
def resource():
    token = request.headers.get('Authorization')
    if not token:
        return {"error": "no token provided"}, 401
    client_ip = request.remote_addr
    rate_limit = rate_limits.setdefault(client_ip, [])
    now = time.time()
    # Remove expired timestamps older than 60s
    while rate_limit and now - rate_limit[0] >= 60:  
        rate_limit.pop(0)
    if len(rate_limit) < 15:  # Allow max 15 requests per minute
        rate_limit.append(now)
        return {"message": "access granted"}
    else:
        return {"error": "too many requests, please wait"}, 429

@app.route('/revoke', methods=['POST'])
def revoke():
    token = request.json.get('token')
    if not token or token not in tokens:
        return {"error": "invalid token"}, 401
    del tokens[token]
    return {"message": "token revoked"}

# Implement your own client authentication here
def authenticate_client():
    # Return True for now
    return True
