<?php
require 'vendor/autoload.php'; // Include all Composer packages
use Predis\Client; // For Redis
use GuzzleHttp\Client as HttpClient; // For sending HTTP requests to ELK Stack 

$redis = new Client();
$httpClient = new HttpClient(['base_uri' => 'http://your-elkstack-service:port/']);

function updateClinicStatus(int $clinicId, string $newStatus, string $lastModifiedIp) {
    global $redis, $httpClient;

    $key = $lastModifiedIp . ':update_count';
    $limit = 5; // Limit to 5 updates per minute from the same IP address.

    try {
        // Increment update count for this IP and get it's new value.
        $updatesCount = (int) $redis->incr($key);

        if ($updatesCount === 1) {
            // Set expiry time to 60 seconds from now, allowing the bucket of 5 updates to be refreshed every minute.
            $redis->expire($key, 60);
        } elseif ($updatesCount > $limit) {
            throw new Exception('Too many requests'); // Too much requests in a short timeframe from this IP address.
        }

        // Start database transaction
        $dbTransaction = $this->getDBConnection()->begin_transaction(); 

        try {
            $stmt = $this->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE clinic_id = ?");
            $stmt->bind_param('ssi', $newStatus, $lastModifiedIp, $clinicId);

            // Execute the prepared statement.
            $executeResult = $stmt->execute();

            if($executeResult === false) {
                throw new Exception('Update failed');
            }
        } catch (Exception $e) {
            // If update fails, rollback transaction and rethrow error
            $dbTransaction->rollback();

            throw $e;
        }

        $stmt->close();

        // Commit the transaction.
        $dbTransaction->commit(); 

    } catch (Exception $e) {
        try {
            if($httpClient !== null){
                // Log errors to ELK Stack
                $httpClient->request('POST', 'your_endpoint', [
                    'json' => [
                        'error' => $e->getMessage(),
                        'trace' => $e->getTraceAsString()
                    ]
                ]); 
            }
        } catch(Exception $logError){
            // Ignore logging errors, they should not stop the main process
        }

        return "Failed to update clinic status: ".$e->getMessage();
    }

    return "Successfully updated clinic status";
}
?>
