public class XmlParser
{
    public static XmlNode Parse(string xml, string xpath)
    {
        var doc = new XmlDocument();
        doc.LoadXml(xml);

        var navigator = doc.CreateNavigator();
        var iterator = navigator.Select(xpath);

        XmlNode result = null;
        while (iterator.MoveNext())
        {
            if (result != null) throw new InvalidOperationException("Multiple elements found");

            result = (XmlNode)iterator.Current.UnderlyingObject;
        }

        if (result == null) throw new InvalidOperationException("No element found");

