```rust
use std::process::Command;
use std::fs::File;
use std::io::{self, Write};
use std::path::PathBuf;
use std::time::Instant;
use std::mem::size_of_val;
use sysinfo::SystemExt;
use sysinfo::ProcessExt;
use log::LevelFilter;
use env_logger;
use icehooks::SyncLazy;

/// Struct for logging hook
pub struct LoggingHook {
    pub source_file: String,
}

impl icehooks::Hook for LoggingHook {
    fn before(&self) -> bool {
        let mut log_file = File::create("log.txt").unwrap();
        write![&mut log_file, "Started compiling file: {}", &self.source_file].is_ok()
    }

    fn after(&self) -> bool {
        let start = Instant::now();
        let elapsed = start.elapsed().as_secs_f64();

        let mut log_file = File::create("log.txt").unwrap();
        write![&mut log_file, "Finished compiling file: {}. Time taken: {} seconds", &self.source_file, elapsed].is_ok()
    }
}

/// Struct for memory hook
pub struct MemoryHook;

impl icehooks::Hook for MemoryHook {
    fn before(&self) -> bool {
        let system = sysinfo::System::new();
        let mut log_file = File::create("log.txt").unwrap();
        write![&mut log_file, "Before compilation: RSS {}", system.process(pid())].is_ok()
    }

    fn after(&self) -> bool {
        let system = sysinfo::System::new();
        let mut log_file = File::create("log.txt").unwrap();
        write![&mut log_file, "After compilation: RSS {}", system.process(pid())].is_ok()
    }
}

/// Function to compile a rust source file using the Rust compiler
pub fn compile_source(src_path: PathBuf) -> io::Result<i32> {
    let mut hooks = SyncLazy::new();

    // Add logging hook
    hooks.add_hook(Box::new(LoggingHook { source_file: src_path }));
    // Add memory hook
    hooks.add_hook(Box::new(MemoryHook));

    let cmd = Command::new("rustc")
        .arg(&src_path)
        .spawn()?;

    // Run the hooks before the process starts
    hooks.run_before();

    let exit_code = icehooks::catch_with_exit_code(cmd);

    if let Ok(rss) = system.process(pid()).resident_set_size {
        if rss > MAX_RSS_ALLOWED {
            error![&mut log_file, "Compilation process exceeded maximum RSS: {}", rss];
            Process::kill(pid());
            Err(io::Error::new(io::ErrorKind::Other, "Compilation process exceeded maximum RSS"))
        } else {
            hooks.run_after();
            Ok(exit_code)
        }
    } else {
        Err(io::Error::new(io::ErrorKind::Other, format![&mut log_file, "Failed to get process RSS"]))
    }
}
```
