public class DynamicDeserializer {
    private ClassProvider classProvider; // assume this is an interface provided by you
    private ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>(); 

    public <T> T deserialize(byte[] data, Class<T> clazz) throws CustomException {
        if (cache.containsKey(clazz.getName())) {
            return (T) cache.get(clazz.getName());
        } else {
            try (ByteArrayInputStream bis = new ByteArrayInputStream(data); 
                 ObjectInput in = new ObjectInputStream(bis)) {
                T obj = (T) classProvider.getClassDefinition(clazz.getName()).newInstance(); // assuming the ClassProvider has a method to get the definition of a class from an external data source
                cache.putIfAbsent(clazz.getName(), obj); 
            } catch (IOException | InstantiationException | IllegalAccessException e) {
                throw new CustomException("Failed to deserialize", e); // custom exception with detailed error message
            } catch (ClassNotFoundException e) {
                throw new CustomException(e.getMessage(), e); // propagate the original exception
            } 
        }
    }

