import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.net.*;
import org.apache.commons.codec.digest.*;

public class FileUploader {
    private static final String BUCKET_URL = "https://your-bucket-url.com/";

    public boolean uploadFileToCloudStorage(String filePath, String bucketName, String directory) throws Exception{
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        String hex = "";

        try (InputStream is = Files.newInputStream(Paths.get(filePath))) {
            byte[] buffer = new byte[8192]; // Adjust chunk size as needed
            int bytesRead;

            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }

        byte[] hashBytes = md.digest();
        hex = new String(Hex.encodeHex(hashBytes));

        if (fileExistsInCloudStorage(hex)) {
            System.out.println("File already exists in cloud storage.");
            return false;
        }

        // Upload file to cloud storage, API integration code goes here
    }

    private boolean fileExistsInCloudStorage(String hash) throws Exception{
        URL url = new URL(BUCKET_URL + "/" + hash);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        if (connection.getResponseCode() == HttpURLConnection.HTTP_OK){
            System.out.println("File exists in cloud storage.");
            return true;
        } else {
            System.out.println("File does not exist in cloud storage.");
            return false;
        }
    }
}
```
This function reads a file in chunks, calculates the SHA-256 hash of the file contents and checks if that hash already exists in the specified cloud location (using the HTTP GET method). If the file doesn't exist, it uploads it to the bucket/directory. 

As a note, for large files, you might want to use libraries like Apache Commons IO or Google Guava which provide more efficient ways of copying streams without needing to load them fully into memory first. Also, this code does not handle all edge cases and exceptions that could occur during file uploading process, such as network issues, server errors etc. You should always include proper error handling in production level codes.

