        response = requests.put(url=services[service]['endpoint'], 
                                data=user, 
                                headers=services[service]['headers'])

        if response.status_code == 200:
            logging.info("Profile updated for user {} on service {}".format(user['email'], service))
        else:
            raise Exception('Update failed with status code {}: {}'.format(response.status_code, response.content))
    except requests.exceptions.RequestException as e:
        logging.error("Network error while updating user {}'s profile on service {}: {}".format(user['email'], service, str(e)))

def update_all_profiles(users):
    with ThreadPoolExecutor() as executor:
        for user in users:
            if validate_data(user):
                for service in services.keys():
                    # Submit the task to be executed concurrently
                    executor.submit(update_profile, service, user)

```

