Here's a basic implementation of your requirements in Java using CompletableFuture for asynchronous IO operations, java.nio.file package for listing files in directory, and Apache HttpClient to perform HTTP requests:

```java
import org.apache.http.HttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

public class LargeFileAnalyzer {
    private final String directoryPath;
    private final Pattern pattern = Pattern.compile("(?i)(error|warning)");
    private static final CloseableHttpClient httpClient = HttpClients.createDefault();

    public LargeFileAnalyzer(String directoryPath) {
        this.directoryPath = directoryPath;
    }

    public void analyzeFiles() throws IOException {
        Path dir = Paths.get(directoryPath);
        try (Stream<Path> paths = Files.walk(dir)) {
            List<CompletableFuture<Void>> futures = new ArrayList<>();

            paths.filter(path -> path.toString().endsWith(".txt")).forEach(filePath -> {
                CompletableFuture<Void> future = CompletableFuture.runAsync(() -> processFile(filePath))
                    .exceptionally(ex -> handleException(ex, filePath));
                futures.add(future);
            });

            // Wait for all tasks to complete
            CompletableFuture<Void> allDone = CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));
            allDone.join();
        }
    }

    private void processFile(Path filePath) {
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                Matcher matcher = pattern.matcher(line);
                if (matcher.find()) {
                    // Generate and upload report
                    HttpPost postRequest = new HttpPost("http://example.com/api");
                    StringEntity requestBody = new StringEntity(generateReport(filePath, line));
                    postRequest.setEntity(requestBody);
                    HttpResponse response = httpClient.execute(postRequest);

                    if (response.getStatusLine().getStatusCode() != 200) {
                        throw new IOException("Failed to upload report");
                    }
                }
            }
        } catch (IOException e) {
            handleException(e, filePath);
        }
    }

    private String generateReport(Path filePath, String line) {
        // Implement your logic here for generating reports
        return "File: " + filePath + ", Line: " + line;
    }

    private Void handleException(Throwable ex, Path filePath) {
        System.err.println("Error processing file " + filePath + ": " + ex.getMessage());
        return null;
    }
}
```
This code uses Apache HttpClient for HTTP requests and BufferedReader to read the files efficiently without loading them into memory, which should work well with large text files. Error handling is done by printing a message in case of an error and returning null, allowing the CompletableFuture chain to continue processing other files.

