public class CryptoXmlParser {
    private string url;
    private XmlDocument xmlDoc;
    private Dictionary<string, DateTime> cacheExpirations;
    private TimeSpan cacheDuration;

    public CryptoXmlParser(string url) {
        this.url = url;
        this.cacheExpirations = new Dictionary<string, DateTime>();
        this.xmlDoc = new XmlDocument();
        this.cacheDuration = TimeSpan.FromHours(1);  // Default cache duration is 1 hour
    }

    public async Task FetchAndParseAsync() {
        try {
            var request = (HttpWebRequest)WebRequest.Create(this.url);
            using (var response = await request.GetResponseAsync())
            using (var reader = new StreamReader(response.GetResponseStream())) {
                string content = await reader.ReadToEndAsync();
                if (IsCacheValid(content)) {
                    this.xmlDoc.LoadXml(this.cache[content]);
                } else {
                    this.xmlDoc.LoadXml(content);
                    UpdateCache(content);
                }
            }
        } catch (WebException ex) {
            Console.WriteLine("Error fetching XML: " + ex.Message);
        }
    }

    private bool IsCacheValid(string content) {
        if (!this.cacheExpirations.ContainsKey(content)) return false;
        var expiration = this.cacheExpirations[content];
        return DateTime.Now < expiration;
    }

    private void UpdateCache(string content) {
        this.cacheExpirations[content] = DateTime.Now + this.cacheDuration;
        // Add the content to cache here
    }

