public class GaussianDistributionGenerator : DistributionGeneratorBase, IDistributionGenerator
{
    private readonly float mean;
    private readonly float standardDeviation;

    public GaussianDistributionGenerator(float mean, float standardDeviation)
    {
        if (standardDeviation <= 0f) throw new ArgumentOutOfRangeException("Standard deviation must be greater than zero");

        this.mean = mean;
        this.standardDeviation = standardDeviation;
    }

    public float GenerateFloat()
    {
        float u1 = 1.0f - UnityEngine.Random.value; //uniform(0,1] random doubles
        float u2 = UnityEngine.Random.value; //uniform(0,1) random doubles
        float randStdNormal = Mathf.Sqrt(-2.0f * Mathf.Log(u1)) *
            Mathf.Sin(2.0f * Mathf.PI * u2); //random normal(0,1)

        return mean + standardDeviation * randStdNormal; 
    }

