```python
import json
import logging
from time import sleep
from requests import Session, exceptions

class APIResponseManager:
    def __init__(self):
        self._session = Session()

    @staticmethod
    def _parse_response(resp):
        try:
            return json.loads(resp)
        except ValueError as e:
            logging.error('Invalid JSON response')
            raise

    def make_request(self, url, service_specific_validation):
        retry = 0
        max_retries = 5
        backoff_secs = 1
        while True:
            try:
                resp = self._session.get(url)
                json_response = self._parse_response(resp.text)
                service_specific_validation(json_response)
                return json_response
            except exceptions.RequestException as e:
                logging.error('HTTP Request failed %s', str(e))
                if retry == max_retries:
                    raise  # give up after several attempts
                sleep(backoff_secs)
                backoff_secs *= 2  # exponential backoff
                retry += 1
            except ValueError as e:
                logging.error('JSON parsing error %s', str(e))
                raise

    def validate_service_response(self, url, service_specific_validation):
        json_resp = self.make_request(url, service_specific_validation)
        return self._unify_user_profile(json_resp)

    @staticmethod
    def _unify_user_profile(json_response):
        mandatory_fields = ['access_token', 'user_id']
        optional_fields = ['refresh_token', 'roles', 'status']

        unified_profile = {field: json_response.get(field, None) for field in mandatory_fields + optional_fields}

        return unified_profile
```
This is a basic class to manage responses from an API service and validate them. It supports parsing of JSON responses, validation with exponential backoff retries for transient errors, handling of HTTP exceptions, unifying user profile format. 

