To make it more manageable, I will provide an example with the use of Node.js (Javascript) along with Express.js framework to handle web requests concurrently using promises, MySQL and PostgreSQL drivers for data fetching from different databases, PDFKit for report creation and emailing via Nodemailer.

This is a very basic example:

```javascript
const express = require('express');
const app = express();
const mysql = require('mysql');
const { Client } = require('pg');
const pdfkit = require('pdfkit');
const nodemailer = require('nodemailer');
const fs = require('fs');
app.use(express.json());

let dbMysql, dbPg;
// Connect to databases
mysql.createConnection({
  host     : 'localhost',
  user     : 'me',
  password : 'secret',
  database : 'my_db'
}).connect((err, mysqlDb) => { if (err) throw err; dbMysql = mysqlDb; });

const clientPg = new Client({
  host: 'localhost',
  user: 'me',
  password: 'secret',
  database: 'my_db'
});
clientPg.connect();

app.post('/report', function (req, res) {
  // Fetch data from databases concurrently
  Promise.all([
    new Promise((resolve, reject) => dbMysql.query('SELECT * FROM table1', (err, rows) => err ? reject(err) : resolve(rows))),
    new Promise((resolve, reject) => clientPg.query('SELECT * FROM table2', (err, res) => err ? reject(err) : resolve(res.rows)))
  ]).then(([mysqlData, pgData]) => {
    const doc = new pdfkit();
    // Create PDF from data
    mysqlData.forEach(row => doc.text(JSON.stringify(row)));
    pgData.forEach(row => doc.text(JSON.stringify(row)));

    // Save PDF to disk
    doc.pipe(fs.createWriteStream('out.pdf'));
    doc.end();

    let transporter = nodemailer.createTransport({ /* options */ });
    // Send email with report
    transporter.sendMail({
      from: 'youremail@example.com', 
      to: "user@example.com", 
      subject: "Report", 
      text: "Please find attached your report",
      attachments: [{ filename: 'out.pdf', content: fs.createReadStream('out.pdf') }]
    });

    res.status(201).send("PDF created and sent successfully");
  })
  .catch((err) => {
    console.error(`Error occurred during processing data: ${err}`);
    res.status(500).send("Internal server error occurred, check logs for more info.");
  });
});

app.listen(3000);
```
This script will start a web server on port 3000 and listen to POST requests at '/report'. When it gets such a request, it fetches data from MySQL and PostgreSQL databases concurrently using promises. Then it creates a PDF report containing fetched data and sends it by email. All errors are handled gracefully - sending an error response if something goes wrong.

