// Thread function for each file conversion job
void* convertJob(void *arg) {
    Progress *progress = (Progress*) arg;
    ++progress->currentFileIndex; // update progress

    char inputFile[256];
    snprintf(inputFile, sizeof(inputFile), "%s/file%zu.jpg", inputDir, progress->currentFileIndex);

    char outputFile[256];
    snprintf(outputFile, sizeof(outputFile), "%s/output%zu.pdf", outputDir, progress->currentFileIndex);

    return convertJpegToPdf(inputFile, outputFile); // execute conversion
}

// Main function to start batch conversion
int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf) {
    DIR* dir = opendir(inputDir);
    if (dir == NULL) return -1; // directory does not exist or cannot be opened

    struct dirent *entry;
    int numFiles = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && endsWith(entry->d_name, ".jpg")) ++numFiles; // count number of JPEG files
    }
    closedir(dir);

    Progress progress = { .totalFiles = numFiles, .currentFileIndex = 0 }; 

    pthread_t threads[numFiles];
    for (int i = 0; i < numFiles; ++i) { // create a thread for each file conversion job
        if(pthread_create(&threads[i], NULL, convertJob, &progress)) return -2; // failed to create thread
    }

    int errorCode = 0;
    for (int i = 0; i < numFiles; ++i) { // join all threads and retrieve possible errors
        void *retVal;
        pthread_join(threads[i], &retVal); 

        if (*((int*) retVal) != 0 && errorCode == 0) errorCode = *((int*) retVal);
    }

    return errorCode; // return the first error code encountered or 0 if all conversions were successful
}
