    public async Task<string> CalculateFileMd5Async(string filePath)
    {
        using var md5 = MD5.Create();
        const int bufferSize = 4096; // 4KB is a good starting point for reading files

        byte[] hashBytes;

        try
        {
            using var stream = File.OpenRead(filePath);

            if (stream.Length <= bufferSize)
            {
                hashBytes = await md5.ComputeHashAsync(stream);
            }
            else
            {
                int bytesRead;
                byte[] buffer = new byte[bufferSize];

                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    md5.TransformBlock(buffer, 0, bytesRead, null, 0);
                }

                // TransformFinalBlock can be used for the final block of data in case the length of the file is not a multiple of the bufferSize
                md5.TransformFinalBlock(buffer, 0, bytesRead);
            }
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Failed to calculate MD5 hash for file: {filePath}", filePath);
            return null;
        }

        var hex = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

        return hex;
    }

    public async Task<string> CalculateFileMd5FromUrlAsync(Uri fileUrl, string destinationPath)
    {
        using var httpClient = new HttpClient();
        using var response = await httpClient.GetAsync(fileUrl, HttpCompletionOption.ResponseHeadersRead);

        using var streamToReadFrom = await response.Content.ReadAsStreamAsync();

        // If the file is large, consider using a Stream implementation which supports seeking, like FileStream
        using (var streamToWriteTo = new FileStream(destinationPath, FileMode.Create)) 
            await streamToReadFrom.CopyToAsync(streamToWriteTo);

        return await CalculateFileMd5Async(destinationPath);
    }
}
