import asyncio
from typing import Type
import aiohttp
import logging

class FileMetadataExtractor:
    def __init__(self, storage_service_client):
        self.cache = {}
        self.storage_service_client = storage_service_client

    async def extract_metadata(self, file_path: str, metadata_class: Type[Metadata]) -> Metadata:
        if not isinstance(file_path, str):
            raise ValueError("Invalid file path.")

        try:
            # Checking cache first
            if file_path in self.cache:
                return self.cache[file_path]

            # Retrieving from external storage service
            metadata = await self._retrieve_metadata(file_path, metadata_class)

            # Validating the format before extraction
            if not self._validate_format(metadata):
                raise RuntimeError("Invalid file format.")

            # Caching for frequent access
            self.cache[file_path] = metadata
            return metadata
        except (TypeError, ValueError) as e:
            logging.error(f"An error occurred while extracting metadata: {e}")
            raise RuntimeError("Failed to extract metadata.") from e
        except Exception as e:
            logging.exception(f"Unexpected error while extracting metadata: {e}")
            raise RuntimeError("Unexpected error occurred during metadata extraction.") from e

    async def _retrieve_metadata(self, file_path: str, metadata_class: Type[Metadata]) -> Metadata:
        try:
            return await self.storage_service_client.get_file_metadata(file_path, metadata_class)
        except Exception as e:
            logging.exception(f"Error occurred while retrieving file metadata from storage service: {e}")
            raise RuntimeError("Failed to retrieve metadata.") from e

