import java.util.*;

public class TrafficSimulationManager {
    private Map<String, Intersection> intersections;

    public TrafficSimulationManager(Map<String, Intersection> intersections) {
        this.intersections = intersections;
    }

    public void simulateTrafficVolume(String intersectionId, int range, String distribution) {
        if (!this.intersections.containsKey(intersectionId)) {
            throw new IllegalArgumentException("Intersection not found!");
        }
        Intersection intersection = this.intersections.get(intersectionId);
        intersection.setTrafficVolume(generateRandomValueBasedOnDistribution(range, distribution));
    }

    public void simulateAverageSpeed(String intersectionId, int range, String distribution) {
        if (!this.intersections.containsKey(intersectionId)) {
            throw new IllegalArgumentException("Intersection not found!");
        }
        Intersection intersection = this.intersections.get(intersectionId);
        intersection.setAverageSpeed(generateRandomValueBasedOnDistribution(range, distribution));
    }

    public void simulateAccidentFrequency(String intersectionId, int range, String distribution) {
        if (!this.intersections.containsKey(intersectionId)) {
            throw new IllegalArgumentException("Intersection not found!");
        }
        Intersection intersection = this.intersections.get(intersectionId);
        intersection.setAccidentFrequency(generateRandomValueBasedOnDistribution(range, distribution));
    }

    public void setAndSwitchTrafficScenario(String scenario) {
        for (Intersection intersection : intersections.values()) {
            intersection.setCurrentScenario(scenario);
        }
    }

    private int generateRandomValueBasedOnDistribution(int range, String distribution) {
        Random random = new Random();
        if ("uniform".equalsIgnoreCase(distribution)) {
            return random.nextInt(range);
        } 
        // Add other distributions here like "normal", "exponential"...
        else {
            throw new IllegalArgumentException("Invalid distribution type!");
        }
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Intersection intersection : intersections.values()) {
            sb.append(intersection.toString()).append("\n");
        }
        return sb.toString();
    }
}
