    public async Task UpdateWeatherData(string elementID, string url) 
    {
        var simulatedTemp = SimulateTemperature(-40, 50);
        var simulatedHumidity = SimulateHumidity(0, 100);
        var simulatedWindSpeed = SimulateWindSpeed(0, 200);
        var simulatedPrecipitation = SimulatePrecipitation(0, 1000);

        string weatherData = $"Element: {elementID}, " +
                             $"Temperature: {simulatedTemp}°C, " +
                             $"Humidity: {simulatedHumidity}%," + 
                             $"Wind Speed: {simulatedWindSpeed}km/h, " +
                             $"Precipitation: {simulatedPrecipitation}mm";

        var json = JsonConvert.SerializeObject(weatherData);
        var content = new StringContent(json, Encoding.UTF8, "application/json");

        try 
        {
            HttpResponseMessage response = await client.PostAsync(url, content);
            response.EnsureSuccessStatusCode();
        }
        catch (HttpRequestException e) 
        {
            Console.WriteLine("\nException Caught!");	
            Console.WriteLine("Message :{0} ",e.Message);
        }
    }

    private double SimulateTemperature(double min, double max) => new Random().NextDouble() * (max - min) + min;

