<?php
class PasswordGenerator {
    private $length;
    private $charSet;
    private $algorithm;

    function __construct($length, $charSet = null, $algo) {
        $this->setLength($length);
        $this->setCharSet($charSet);
        $this->setAlgorithm($algo);
    }

    public function setLength($length) {
        if ($length >= 8 && $length <= 64) {
            $this->length = $length;
        } else {
            throw new Exception("Invalid length. Length should be between 8 and 64 characters.");
        }
    }

    public function setCharSet($charSet = null) {
        if ($charSet === null) {
            $this->charSet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        } else {
            if (strlen($charSet) < 8 || strlen($charSet) > 64) {
                throw new Exception("Invalid character set. Length should be between 8 and 64 characters.");
            }
            $this->charSet = $charSet;
        }
    }

    public function setAlgorithm($algo) {
        $validAlgo = [PASSWORD_DEFAULT, PASSWORD_BCRYPT]; // list all valid algorithms here

        if (in_array($algo, $validAlgo)) {
            $this->algorithm = $algo;
        } else {
            throw new Exception("Invalid algorithm.");
        }
    }

    public function generateSecurePassword() {
        $password = '';

        for ($i = 0; $i < $this->length; $i++) {
            $index = random_int(0, strlen($this->charSet) - 1);
            $password .= $this->charSet[$index];
        }

        $hashedPassword = $this->hashPassword($password);

        return [
            'salt' => $password, // using the generated password as salt here for simplicity
            'hashed_password' => $hashedPassword
        ];
    }

    public function hashPassword($password) {
        $options = ['cost' => 12]; // default cost, you can adjust it based on your requirements.

        return password_hash($password, $this->algorithm, $options);
    }

    public function verifyPassword($givenPwd, $hashedPwd) {
        if (password_verify($givenPwd, $hashedPwd)) {
            return true;
        } else {
            return false;
        }
    }
}
?>
