// Function to read TIFF image and extract information about bits per sample and samples per pixel 
ImageInfo parse_tiff_image(const char *filename) {
   ImageInfo img;
   TIFF* tif = TIFFOpen(filename, "r"); // Open the file for reading
   if (tif) {
       uint16 bps, spp; 
       TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps);  // Get bits per sample
       TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &spp);  // Get samples per pixel

       img.bits_per_sample = bps;
       img.samples_per_pixel = spp;
   } else {
       logger->error("Unable to open TIFF image file.");
   }

   return img;
}
