```rust
use std::sync::Arc;
use reqwest::Url;
use hyper::client::HttpConnector;
use tokio::time::Duration;
use std::collections::HashMap;

pub struct HttpClientConfig {
    disable_certificate_validation: bool,
    retries: usize,
    retry_interval: Duration,
    timeout: Duration,
    custom_headers: HashMap<String, String>,
}

#[derive(Debug)]
pub enum HttpClientError {
    InvalidUrl(reqwest::Error),
    ClientCreation(reqwest::Error),
    // other specific error types go here
}

impl From<reqwest::Error> for HttpClientError {
    fn from(error: reqwest::Error) -> Self {
        match error.status() {
            Some(_) => Self::ClientCreation(error),
            _ => Self::InvalidUrl(error),
        }
    }
}

pub async fn create_http_client(url: &str, config: HttpClientConfig) -> Result<reqwest::RequestBuilder, HttpClientError> {
    let url = Url::parse(url).map_err(HttpClientError::InvalidUrl)?;

    let connector = if config.disable_certificate_validation {
        // Create an HTTP client with certificate validation disabled
        HttpsConnector::new(HttpsConnector::default().danger_accept_invalid_certs(true))
            .expect("failed to create https connector")
    } else {
        HttpsConnector::new(HttpsConnector::default())
            .expect("failed to create https connector")
    };

    let client = reqwest::Client::builder()
        // Use a custom HTTP connector with/without certificate validation.
        .connector(Arc::new(connector))
        // Set the number of retries for failed requests.
        .timeout(Duration::from_secs(config.retries as u64 * config.retry_interval.as_secs()))
        .build()?;

    let mut request = client.get(url.clone());

    // Add custom headers to the request, if any are specified.
    for (key, value) in &config.custom_headers {
        request = request.header(&**key, &**value);
    }

    Ok(request)
}
```
This function will create a configurable HTTP client with the desired settings and returns a `RequestBuilder` for a given URL. It also handles errors by converting them into custom error types. This helps to distinguish between different types of failures, such as invalid URLs and failed requests to the server. 

