```cpp
// Function to copy 'n' bytes from list of buffered data chunks into a new buffer
std::unique_ptr<uint8_t[]> copyBytes(const std::vector<std::unique_ptr<uint8_t[]>> &chunkList, size_t n) {
    auto buffer = std::make_unique<uint8_t[]>(n); // New buffer for copied bytes

    size_t index = 0; // Index into the new buffer
    for (const auto& chunk : chunkList) {
        if (index + sizeof(chunk.get()) >= n) break; // Stop copying if we've reached 'n' bytes or a null-terminator

        std::memcpy(&buffer[index], chunk.get(), sizeof(chunk.get())); // Copy current chunk into the new buffer
        index += sizeof(chunk.get()); // Move to next position in the new buffer
    }

    return buffer; // Return the copied bytes
}
```

