import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;

public class ExecCommand {
    // Define constants
    private static final String FILENAME = "logFile.txt";
    private static final int BUFFER_SIZE = 1024;

    public static void main(String[] args) {
        try {
            // Delete the log file if it exists
            Files.deleteIfExists(Paths.get(FILENAME));

            // Define command to execute, working directory and environment variables
            String command = "ls -l";
            String workingDirectory = "/Users/username/Desktop";
            String[] envp = {""};

            Process process = Runtime.getRuntime().exec(command, envp, new File(workingDirectory));

            // Read output and error streams of the executed command 
            BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;

            while ((line = outputReader.readLine()) != null) {
                logMessage("INFO", "Command Output: %s", line);
            }

            while ((line = errorReader.readLine()) != null) {
                logMessage("ERROR", "Command Error: %s", line);
            }

        } catch (Exception e) {
            System.out.println(e);
        }
    }

    // Function to log messages
    private static void logMessage(String tag, String format, Object... args) throws IOException {
        byte[] buffer = new byte[BUFFER_SIZE];
        int length;
        FileOutputStream outStream = null;

        try{
            outStream = new FileOutputStream(FILENAME, true); // 'true' for append mode 

            String message = String.format(format, args);
            snprintf(buffer, "%s: %s%n", tag, message);

            outStream.write(buffer, 0, length);
        } finally {
            if (outStream != null) {
                try {
                    outStream.close();
                } catch (IOException e) {
                    System.out.println("Error while closing file stream: " + e);
                }
            }
        }
    }

    // Simulates snprintf function from C language using java.lang.String format method 
    private static int snprintf(byte[] buffer, String format, Object... args) {
        return String.format(format, args).getBytes().length;
    }
}
```
