                var requestContent = new StringContent(JsonConvert.SerializeObject(new { site }), System.Text.Encoding.UTF8, "application/json");
                switch (operation)
                {
                    case "add":
                        await client.PostAsync($"{config.ApiUrl}/sites", requestContent);
                        break;
                    case "remove":
                        await client.DeleteAsync($"{config.ApiUrl}/sites/{site}");
                        break;
                    // Similar operations for 'start', 'stop', and 'restart'...
                }
            }
        }
    }

