    IPAddress sourceIP;
    IPAddress destinationIP;
    size_t payloadLength;
};

std::mutex mtx; 

int createAndConfigureNetworkPduList(NetworkPDUConfig_T **pduList, size_t *listSize, int maxStructures) {
    std::lock_guard<std::mutex> lock(mtx); 

    if (maxStructures <= 0 || maxStructures > 5000 || pduList == nullptr || listSize == nullptr) {
        // Log error: Invalid input parameters.
        return -1;
    }

    std::random_device rd;  
    std::mt19937 gen(rd()); 
    std::uniform_int_distribution<> dis(0, maxStructures);

    NetworkPDUConfig_T* tempList = new (std::nothrow) NetworkPDUConfig_T[maxStructures];
    if (!tempList) {
        // Log error: Memory allocation failure.
        return -1;
    }

    for(int i = 0; i < maxStructures; ++i){
        tempList[i].packetID = dis(gen);

        std::string sourceIPStr, destIPStr; 
        // Randomly generate the IP addresses.
        // Fill in the actual implementation details here...
        if (!tempList[i].sourceIP.fromString(sourceIPStr) || !tempList[i].destinationIP.fromString(destIPStr)) {
            delete[] tempList; 
            return -1;
        }

        // Randomly generate the payload length.
        std::uniform_int_distribution<> disPayload(0, 65535);
        tempList[i].payloadLength = disPayload(gen);
    }

    *pduList = tempList;
    *listSize = maxStructures;

    std::sort(tempList, tempList + maxStructures, [](const NetworkPDUConfig_T& a, const NetworkPDUConfig_T& b) {
        return a.payloadLength < b.payloadLength;
    });

    // Log information: Configurations created and sorted successfully.

    return 0;
}
