  };

  private Map<String, Constructor> constructorCache = new LinkedHashMap<String, Constructor>(MAX_CACHE_SIZE + 1, .75F, true) {
    public boolean removeEldestEntry(Map.Entry eldest) {
      return size() > MAX_CACHE_SIZE; 
    }
  };

  // Assuming you have method to get class definition from REST API
  private Class fetchClassDefinition(String className) throws Exception {
    if (cache.containsKey(className)) return cache.get(className);

    byte[] data = restApi.getClassDefinition(className);

    Class clazz = defineClass(className, data, 0, data.length);
    cache.put(className, clazz);

    Constructor constructor = clazz.getConstructor();
    constructorCache.put(className, constructor);

    return clazz;
  }

  public synchronized Object deserializeObject(byte[] data) throws Exception {
    try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
         ObjectInputStream in = new ObjectInputStream(bais)) {
      String className = in.readUTF();
      Class clazz = fetchClassDefinition(className);

      return constructorCache.get(className).newInstance();
    } catch (Exception e) {
      // Add custom error handling here, rethrowing as necessary
      throw e; 
    } finally {
      // Release resources to avoid memory leaks
    }
  }
}
```
