```C#
using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

public class PageUpdateService : IPageUpdateService {
    private readonly IElementRepository _elementRepo;
    private readonly IUserPermissionsService _userPermissionsSvc;
    private readonly ILogger<PageUpdateService> _logger;

    public PageUpdateService(IElementRepository elementRepo, 
                             IUserPermissionsService userPermissionsSvc, 
                             ILogger<PageUpdateService> logger) {
        _elementRepo = elementRepo;
        _userPermissionsSvc = userPermissionsSvc;
        _logger = logger;
    }

    public async Task<IActionResult> UpdateElementAsync(int sectionId, int elementId, string htmlContent, Guid? versionId) {
        if (sectionId < 0 || elementId < 0) 
            return new BadRequestObjectResult("Invalid IDs.");

        try {
            var hasPermission = await _userPermissionsSvc.UserHasWriteAccessAsync(elementId);

            if (!hasPermission)
                return new UnauthorizedResult();

            // If a versionId is specified, load the element at that specific version, else load the latest version
            var currentElement = (versionId != null && versionId.Value != Guid.Empty) ? 
                                  await _elementRepo.GetVersionAsync(sectionId, elementId, versionId.Value) : 
                                  await _elementRepo.GetLatestAsync(sectionId, elementId);

            if (currentElement == null)
                return new NotFoundObjectResult("Could not find specified element.");

            var updatedElement = currentElement.UpdateHTMLContentAndIncrementVersion(htmlContent);

            await _elementRepo.SaveChangesAsync();

            _logger.LogInformation($"Successfully updated HTML content for Element ID: {updatedElement.Id}");

            return new OkObjectResult("Page should be refreshed.");
        } catch (Exception ex) when (ex is ServiceFailureException || ex is ConflictDetectedException) {
            _logger.LogError($"Failed to update HTML content for Element ID: {elementId}. Reason: {ex.Message}");

            return new StatusCodeResult(500);
        } catch (Exception ex) {
            _logger.LogCritical($"A critical error occurred while trying to update an element: {ex}");

            return new StatusCodeResult(500);
        }
    }
}
```
