    private static readonly ILogger _logger = new LoggerFactory().CreateLogger<Program>();
    private static Dictionary<string, string> cache = new Dictionary<string, string>();

    public static void Main(string[] args)
    {
        Parser.Default.ParseArguments<Options>(args).WithParsed<Options>(o =>
        {
            ManageWebsiteLifecycle(o.ConfigFilePath, o.Sites, o.Operations);
        });
    }

    public static void ManageWebsiteLifecycle(string configPath, List<string> siteNames, List<string> operations)
    {
        // Validate inputs and parse configuration file
        if (!File.Exists(configPath))
        {
            _logger.LogError("Configuration file does not exist.");
            return;
        }

        JObject config = JObject.Parse(File.ReadAllText(configPath));

        // Validate and cache site names
        foreach (var site in siteNames)
        {
            if (!cache.ContainsKey(site))
            {
                var siteConfig = config[site];

                if (siteConfig == null || !Directory.Exists((string)siteConfig["path"]))
                {
                    _logger.LogError("Site configuration is not valid or directory does not exist.");
                    continue;
                }

                cache.Add(site, siteConfig.ToString());
            }
        }

        // Perform operations concurrently using Task Parallel Library (TPL)
        Parallel.ForEach(operations, operation =>
        {
            foreach (var site in siteNames)
            {
                var sitePath = JObject.Parse(cache[site])["path"];

                if (!File.Exists(Path.Combine((string)sitePath, "web.config")))
                {
                    _logger.LogError("Site does not have a web.config file.");
                    continue;
                }

                // Perform operation based on the type (add, remove, etc.)
            }
        });
    }
}

