typedef struct Record {
    int id;
    long offset_values;
    int keys;
} Record;

MYSQL *conn;
pthread_mutex_t lock;

void readFile(const char* filename) {
    FILE *file = fopen(filename, "r");

    if (file == NULL){
        printf("Error opening the file.\n");
        exit(EXIT_FAILURE);
    }

    char line[256]; 
    while (fgets(line, sizeof line, file) != NULL) {
        Record *record = malloc(sizeof(Record)); // Allocate memory dynamically for each record.
        if (sscanf(line, "%d %ld %d", &record->id, &record->offset_values, &record->keys) != 3) {
            printf("Failed to parse line: %s\n", line);
            free(record);
            continue;
        }

        pthread_mutex_lock(&lock); // Lock the thread for safe operation.

        char query[256];
        sprintf(query, "INSERT INTO tableName VALUES(%d, %ld, %d)", record->id, record->offset_values, record->keys); 

        if (mysql_query(conn, query)) { // Check SQL connection.
            fprintf(stderr, "%s\n", mysql_error(conn));
            exit(EXIT_FAILURE);
        }

        pthread_mutex_unlock(&lock); // Unlock the thread after operation.
        free(record);  // Free memory after use.
    }

    fclose(file);
}

int main(){
