    const char* user = "root";
    const char* password = "password";
    const char* database = "database";

    conn = mysql_init(NULL); // Initialize MySQL connection.

    if (!mysql_real_connect(conn, server, user, password, database, 0, NULL, 0)){
        fprintf(stderr, "%s\n", mysql_error(conn)); // Check SQL connection errors.
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&lock, NULL); // Initialize the thread lock.

    readFile("yourfilepath"); // Read from file.

    mysql_close(conn); // Close connection when done.
}
