using System;
using System.Security.Cryptography;
using System.IO;

public static byte[] DecryptAES(byte[] cipherText, byte[] Key, byte[] IV)
{
    // Check key and IV lengths
    if (Key == null || Key.Length != 16 && Key.Length != 24 && Key.Length != 32)
        throw new ArgumentException(String.Format("Invalid Key length: {0} bytes", Key.Length));

    if (IV == null || IV.Length < 16)
        throw new ArgumentException(String.Format("Invalid IV length: {0} bytes", IV.Length));

    // Create AesCryptoServiceProvider
    using (Aes aesAlg = new AesCryptoServiceProvider())
    {
        aesAlg.Key = Key;
        aesAlg.IV = IV;

        // Create a decrytor to perform the stream transform.
        ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

        // Create the streams used for decryption.
        using (MemoryStream msDecrypt = new MemoryStream(cipherText))
        {
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                using (BinaryReader br = new BinaryReader(csDecrypt))
                {
                    return br.ReadBytes((int)msDecrypt.Length);
                }
            }
        }
    }
}
``` 
