char *SUPPORTED_CIPHER_MODES[] = {ECB_MODE, EDE_MODE, EDE3_MODE, CFB_MODE}; 

struct CryptoHandle {
    EVP_CIPHER_CTX *ctx;
};

EVP_CIPHER* getCipher(const char *mode) {
    // Null encryption for testing purposes
    if (strcmp(mode, NULL_CIPHER) == 0) return EVP_get_cipherbyname("NULL");

    int i = 0;
    while (i < sizeof(SUPPORTED_CIPHER_MODES)/sizeof(char*)) {
        if (strcmp(mode, SUPPORTED_CIPHER_MODES[i]) == 0) {
            EVP_CIPHER *cipher = EVP_get_cipherbyname(mode);

            // Verify cipher is available
            if (cipher == NULL) { 
                // handle error: cipher not found
                return NULL; 
            }

            return cipher;
        }
        ++i;
    }

    // handle error: unsupported mode
    return NULL;
}

struct CryptoHandle* createCryptoHandle(const char *mode) {
    EVP_CIPHER *cipher = getCipher(mode);

    if (cipher == NULL) { 
        // handle error: cipher not found or mode unsupported
        return NULL;
    }

    struct CryptoHandle* handle = malloc(sizeof(struct CryptoHandle));
    handle->ctx = EVP_CIPHER_CTX_new();

    if (handle->ctx == NULL) { 
        // handle error: out of memory
        return NULL;
    }

    if (!EVP_EncryptInit_ex(handle->ctx, cipher, NULL, NULL, NULL)) { 
        // handle error: initialization failed
        EVP_CIPHER_CTX_free(handle->ctx);
        return NULL;
    }

    return handle;
}

int encryptData(struct CryptoHandle *cryptoHandle, unsigned char *plaintext, int plaintextLen, 
                unsigned char **ciphertext) {

    if (EVP_EncryptUpdate(cryptoHandle->ctx, *ciphertext, &len, plaintext, plaintextLen)) { 
        // handle error: encryption failed
        return -1;
    }

    int finalLen;
    EVP_EncryptFinal_ex(cryptoHandle->ctx, (*ciphertext) + len, &finalLen);

    return len+finalLen;
}

void destroyCryptoHandle(struct CryptoHandle *cryptoHandle) {
    if (cryptoHandle != NULL && cryptoHandle->ctx != NULL) {
        EVP_CIPHER_CTX_free(cryptoHandle->ctx);
        free(cryptoHandle);
    }
}
```

In this code, `createCryptoHandle` function is used to create a new cryptographic handle for encrypting data. The returned `struct CryptoHandle*` pointer should be stored and reused for all subsequent operations using the same cipher mode. It's important to always call `destroyCryptoHandle` after you are done with the handle, in order to free resources and avoid memory leaks.

