#include <openssl/des.h>

void des_ecb_encrypt(const unsigned char *plaintext, 
                     int plaintext_len, 
                     const unsigned char *key, 
                     unsigned char *ciphertext) {
    DES_cblock key_schedule;
    DES_key_sched((DES_cblock*)key, &key_schedule);

    for (int i = 0; i < plaintext_len / sizeof(DES_cblock); ++i) {
        DES_ecb_encrypt((const_DES_cblock*)(plaintext + i * sizeof(DES_cblock)), 
                        ciphertext, 
                        &key_schedule, 
