```c
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#define MAX_BUNDLE_SIZE 1024

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Simple structure to represent a resource item
typedef struct {
    char key[64];
    void* value;
} ResourceItem;

// Function to load the resource bundle from file and return its size
int getResourceBundleSize(const char* filename, ResourceItem** bundle) {
    int count = 0;

    // lock before accessing shared data
    pthread_mutex_lock(&lock);

    FILE *file = fopen(filename, "r");  // Open file in read mode

    if (file == NULL) {
        printf("Failed to open file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    *bundle = malloc(sizeof(ResourceItem) * MAX_BUNDLE_SIZE); // Allocate memory for the bundle

    if (*bundle == NULL) {
        printf("Failed to allocate memory: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    while (!feof(file)) {  // Read file line by line
        if (fscanf(file, "%63s=%*s", (*bundle)[count].key) == 1) {
            count++;

            if (count >= MAX_BUNDLE_SIZE) {
                printf("Bundle size exceeds maximum allowed\n");
                break;
            }
        }
    }

    fclose(file); // Close the file after reading

    pthread_mutex_unlock(&lock);  // unlock before returning

    return count;  // Return the number of items in the bundle
}
```
