```javascript
const express = require('express');
let router = express.Router();

// dummy data
let users = [{id: 1, name: 'John Doe', email: 'john@example.com', address: 'New York'}];

router.put('/users/:userId', async (req, res) => {
    const userId = req.params.userId;
    const updatedData = req.body;

    // Find the existing user data
    let userIndex = users.findIndex(user => user.id == userId);
    if (userIndex === -1) return res.status(404).send('User not found');

    try {
        // Merge new and existing data efficiently with Object.assign()
        let updatedUser = Object.assign({}, users[userIndex], updatedData);

        // Update the user in our dummy database
        users[userIndex] = updatedUser;

        res.status(200).json({'message': 'Profile updated successfully', updatedUser});
    } catch (err) {
        console.log(err);
        return res.status(500).send('An error occurred');
    }
});

router.patch('/users/:userId', async (req, res) => {
    const userId = req.params.userId;

    // Find the existing user data
    let userIndex = users.findIndex(user => user.id == userId);
    if (userIndex === -1) return res.status(404).send('User not found');

    try {
        // Mark the user as deleted in our dummy database
        users[userIndex].deleted = true;

        // Return all active profiles after deletion
        let activeUsers = users.filter(user => !user.deleted);

        res.status(200).json({'message': 'Profile deleted successfully', activeUsers});
    } catch (err) {
        console.log(err);
        return res.status(500).send('An error occurred');
    }
});

module.exports = router;
```

This example implements two endpoints: one for PUT requests to update user data, and another for PATCH requests to delete a user profile. It uses the `findIndex` method to find users by ID in an array of dummy users. For updating, it merges the updated fields with existing ones using `Object.assign()`, ensuring that no unnecessary data is sent over network. For deletion, it simply marks the user as deleted and returns all active profiles after deletion. It does not include any form of validation or error handling, which should be added according to your project requirements. 

