use select::document::Document;
use select::predicate::Attr;
use select::node::Node;
use css_select_trait::Selector;
use early_error::early_error;

fn dbCommandExecutor(input: Vec<u8>, root: Option<&Node>, selector: &str, testFunc: Option<Fn(&str) -> Result<(), String>>) -> Result<DataTableReader, String> {
    let start = Instant::now();

    match root {
        None => return Err("Input root is not a valid DOM node".to_string()),
        Some(root_node) => {}
    }

    // Convert byte array into string.
    let input_str = String::from_utf8(input).map_err(|e| format![early_error("{:?}", e)])?;

    // Parse CSS selector.
    let css_parser = CssParser::new();
    let parsed_selector = css_parser.consume(Selector::parse, selector).map_err(|e| format![early_error("{:?}", e)])?;

    // Find elements matching the CSS selector.
    let elements = root_node.query(&parsed_selector);

    if testFunc.is_some() {
        for element in elements {
            match testFunc.unwrap()(element.inner_html()) {
                Err(e) => return Err(format![early_error("{:?}", e)]),
                _ => {}
            }
        }
    }

    // Install an ice hook to ensure proper cleanup after the database operation.
    let mut hook = SyncHook::new();
    hook.register(move || {
        let end = start.elapsed().as_secs();
        println![early_error("Time taken: {} sec", end)];
    });

    // Send byte array data to a database server and get result.
    let result = match send_to_db(input_str) {
        Err(e) => return Err(format![early_error("{:?}", e)]),
        Ok(result) => result,
    };

    // Call cleanup function to release resources.
    hook.cleanup();

    Ok(result)
}
