    @Cacheable("evolution")
    @GetMapping("/{id}")
    public Mono<String> getPokemon(@PathVariable String id) {
        return classProvider.getById(id)
                .zipWith(pokemonApi.getEvolutions().collectList())
                .map(tuple -> {
                    Pokemon pokemon = tuple.getT1();
                    Map<String, EvolutionStage> evolutionMap = tuple.getT2().stream()
                            .collect(Collectors.toMap(EvolutionStage::getId, Function.identity()));

                    return new ResponseDTO(pokemon.getName(), pokemon.getType(), 
                                            pokemon.getWeaknesses(), 
                                            evolutionMap.getOrDefault(pokemon.getCurrentEvolutionId(), null),
                                            evolutionMap.getOrDefault(pokemon.getNextEvolutionId(), null));
                })
                .map(dto -> {
                    try {
                        return objectMapper.writeValueAsString(dto);
                    } catch (JsonProcessingException e) {
                        throw new RuntimeException("Error serializing response", e);
                    }
                });
    }
}
