```php
<?php
class RateLimiter {
    private $tokens;
    private $maxTokens;
    private $lastRefillTimestamp;
    private $refillRatePerSecond;

    public function __construct($maxTokens, $refillRate) {
        $this->maxTokens = $maxTokens;
        $this->tokens = $maxTokens;
        $this->lastRefillTimestamp = time();
        $this->refillRatePerSecond = $refillRate / 60; // convert from tokens per minute to per second
    }

    public function consume($numTokens = 1) {
        $this->refill();
        if ($this->tokens < $numTokens) {
            throw new Exception("Rate limit exceeded");
        } else {
            $this->tokens -= $numTokens;
            return true;
        }
    }

    private function refill() {
        $timeElapsed = time() - $this->lastRefillTimestamp;
        $newTokens = $timeElapsed * $this->refillRatePerSecond;

        if ($newTokens > 0) {
            $this->tokens = min($this->maxTokens, $this->tokens + $newTokens);
            $this->lastRefillTimestamp = time();
        }
    }
}

$rateLimiter = new RateLimiter(5, 5); // Maximum of 5 tokens per minute

