The following is a high-level implementation of the problem statement using C. Note that handling race conditions when updating metrics across multiple threads is not demonstrated here, as it requires additional libraries such as `pthreads` and specific platform details. Also note that error logging mechanism and validation of input parameters were intentionally simplified for brevity.

```c
#include <time.h>
#include <float.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int transaction_id;
    double amount;
    time_t timestamp;
    char* category;
} Transaction;

typedef struct {
    int category_id;
    double total_amount;
    double max_weighted_sum;
} Metrics;

Metrics filter_transactions(Transaction *transactions, size_t n, time_t base_timestamp) {
    Metrics maxCategory = {0};
    int count[1024] = {0};  // Assuming category_id can be from 0 to 1023. Adjust the array size accordingly.

    for (size_t i = 0; i < n; ++i) {
        time_t ageInSeconds = base_timestamp - transactions[i].timestamp;

        if(ageInSeconds > 300){  // Filter based on transaction age
            continue;
        }

        double weight = 1 / (double)ageInSeconds;  // Calculate the weight.

        if(weight > (1/600)){  // Check for the weight limit.
            weight = (1/600);
        }

        int category_id = transactions[i].category_id;

        count[category_id]++;
        if (count[category_id] > 100){  // Check frequency limit per second.
            continue;
        }

        Metrics *metrics = &maxCategory;  // Assuming metrics is the array of Metrics structs.

        pthread_mutex_lock(&(metrics[category_id].mutex));  // Lock for thread safety.

        metrics[category_id].total_amount += transactions[i].amount * weight;
        if (metrics[category_id].max_weighted_sum < transactions[i].amount * weight) {
            metrics[category_id].max_weighted_sum = transactions[i].amount * weight;
            // Update the transaction that contributed to max weighted sum.
            metrics[category_id].transaction_id = transactions[i].transaction_id;
            metrics[category_id].timestamp = transactions[i].timestamp;
        }

        pthread_mutex_unlock(&(metrics[category_id].mutex));  // Unlock for thread safety.
    }

    return maxCategory;  // Return the category with maximum weighted sum.
}
```

