```php
<?php
class PasswordGenerator {
    private $supportedAlgorithms = [PASSWORD_DEFAULT, PASSWORD_BCRYPT, PASSWORD_ARGON2ID];

    public function generateSecurePassword(int $length = 16, string $characterSet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ', int $algorithm = PASSWORD_DEFAULT) {
        if ($length < 8 || $length > 64) {
            throw new Exception('Length must be between 8 and 64 characters');
        }

        if (!$this->isAlgorithmSupported($algorithm)) {
            throw new Exception('Unsupported algorithm');
        }

        $password = $this->generateRandomString($length, $characterSet);
        $salt = $this->generateRandomString(16); // you can use your own salt generation method here.
        return [
            'hash' => password_hash($password . $salt, $algorithm),
            'salt' => $salt,
            'password' => $password,
        ];
    }

    private function generateRandomString(int $length, string $characterSet) {
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomCharacter = $characterSet[mt_rand(0, strlen($characterSet) - 1)];
            $randomString .= $randomCharacter;
        }

        return $randomString;
    }

    private function isAlgorithmSupported(int $algorithm) {
        return in_array($algorithm, $this->supportedAlgorithms);
    }
}
?>
```
