```python
import os
from flask import Flask
from dotenv import load_dotenv
from werkzeug.exceptions import HTTPException
import requests
from requests.exceptions import Timeout
from functools import wraps
import logging

# Load environment variables from .env file
load_dotenv()

app = Flask(__name__)

def log_errors(logger):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            try:
                return f(*args, **kwargs)
            except HTTPException as http_error:
                logger.exception('HTTP error occurred')
                return {'message': str(http_error)}, getattr(http_error, 'code', 500), {'Content-Type': 'application/json'}
            except Exception as e:
                logger.exception('An unhandled exception occurred')
                return {
                    'message': 'A server error occurred' if not app.debug else str(e)
                }, 500, {'Content-Type': 'application/json'}
        return decorated_function
    return decorator

@app.route('/')
@log_errors(logger=logging.getLogger(__name__))
def home():
    auth = os.getenv('AUTH_API')
    headers = {'Authorization': f'Bearer {auth}'}

    try:
        response = requests.get("https://api.example.com/data", headers=headers, timeout=5)

        if response.status_code == 429:  # Too Many Requests
            return {'message': 'Rate limit exceeded'}, 429, {'Content-Type': 'application/json'}

    except Timeout as e:
        return {'message': str(e)}, 504, {'Content-Type': 'application/json'}

    if response.status_code != 200:
        return {'message': 'API request failed'}, response.status_code, {'Content-Type': 'application/json'}

    data = response.json()
    # Process data as needed...

    return {
        'data': data, 
        'message': 'Data fetched successfully'
    }, 200, {'Content-Type': 'application/json'}

if __name__ == "__main__":
    app.run(debug=True)
```
