Below are the functions in C that perform the encryption, decryption, cleanup and logging operations using OpenSSL library:

```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <string.h>

void handleErrors(void)
{
    ERR_print_errors_fp(stderr);
    abort();
}

EVP_CIPHER_CTX *initEncryptAES256GCM(const char* password, const unsigned char* salt, int32_t keyLen, int32_t ivLen) {
    EVP_CIPHER_CTX *ctx;

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) handleErrors();

    /* Generate the encryption and authentication keys using PBKDF2 */
    unsigned char key[keyLen];
    if(!EVP_PBE_scrypt(password, strlen(password), salt, ivLen, 1<<14, 8, 1, keyLen, key)) {
        handleErrors();
    }

    /* Set up cipher context */
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL)) handleErrors();

    /* Set the IV length to 96 bits as required by GCM. Note that for a 96 bit IV you should pass a buffer of size 12 bytes */
    if(1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, ivLen, NULL)) handleErrors();

    /* Now initialize the key and IV with the encryption and authentication keys */
    if(1 != EVP_EncryptInit_ex(ctx, NULL, NULL, key, NULL)) handleErrors();

    return ctx;
}

void cleanupCipherContext(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
```
