// Function to calculate SHA-256 hash of a file
std::string calculate_file_sha256(const std::string& filePath, unsigned int chunkSize = 4096) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filePath, std::ios::binary);

    if(!file) {
        throw std::runtime_error("Could not open the file!");
    }

    char* buffer = new char[chunkSize];

    while (!file.eof()) {
        file.read(buffer, chunkSize);
        std::streamsize bytesRead = file.gcount();

        if (bytesRead > 0) 
            SHA256_Update(&sha256, buffer, bytesRead);
    }

    delete [] buffer;

    file.close();

    SHA256_Final(hash, &sha256);
    std::stringstream ss;
    for(int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }

    return ss.str();
}

// Function to upload and monitor the file progress
void uploadAndMonitorFile(const std::string& bucketName, const std::string& filePath, 
                          const std::map<std::string, std::string>& metadata = {}){
    // Check if file exists and is accessible
    std::ifstream f(filePath);
    if(!f.good()){
        throw std::runtime_error("File doesn't exist or inaccessible!");
    } 

    asio::thread_pool pool(4); // Use thread pools for parallel uploading

    try{
        asio::post(pool, [&](){
            // Calculate SHA-256 hash of the file
            std::string sha256 = calculate_file_sha256(filePath);

