1. Disjoint Set Union-Find:

```cpp
#include <vector>
class DisjointSet {
    std::vector<int> parent;
public:
    DisjointSet(int n) : parent(n, -1){}

    int find(int v) {
        if (parent[v] == -1) return v;  // v is a root
        return parent[v] = find(parent[v]);  // path compression
    }

    void unite(int x, int y) {
        int x_root = find(x);
        int y_root = find(y);

        if (x_root != y_root) parent[x_root] = y_root;  // make y the parent of x
    }
};
```
