We can use a library like nlohmann/json to parse the JSON file and deserialize it into our `std::unordered_map`. We will create a class that reads from the config file on construction, and throws an exception if there are any issues reading or parsing the file.
```cpp
#include <fstream>
#include "json.hpp"
class ConfigLoader {
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> config;
public:
    ConfigLoader(const std::string& filePath) {
        std::ifstream i(filePath);
        nlohmann::json j;

        try {
            i >> j;

            for (nlohmann::json::iterator it = j.begin(); it != j.end(); ++it){
                config[it.key()] = it.value().get<std::variant<int, double, std::string, bool>>();
            }
        } catch(const std::exception& e) {
            throw std::runtime_error("Failed to read or parse JSON configuration file: " + filePath);
        }
    }

    const std::unordered_map<std::string, std::variant<int, double, std::string, bool>>& getConfig() const {
        return config;
    }
};
