```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <zip.h>

typedef struct {
    char *path;
    zip_t *bundle;
} bundle_info_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
bundle_info_t **bundles;
int num_bundles = 0;

void load_resource(char *path) {
    int err = 0;

    pthread_mutex_lock(&lock);

    // check if the bundle already exists
    for (int i=0; i<num_bundles; ++i) {
        if (strcmp(bundles[i]->path, path) == 0) {
            printf("Bundle is already loaded.\n");
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    bundle_info_t *bi = malloc(sizeof(*bi));
    bi->path = strdup(path);
    bi->bundle = zip_open(path, 0, &err);
    if (bi->bundle == NULL) {
        printf("Failed to open bundle: %s\n", path);
    } else {
        ++num_bundles;
        bundles = realloc(bundles, sizeof(*bundles)*num_bundles);
        bundles[num_bundles-1] = bi;
    }

    pthread_mutex_unlock(&lock);
}

void *load_resource_async(void *arg) {
    load_resource((char *)arg);
    return NULL;
}

int main() {
    const char *path = "bundle.zip";  // replace with your bundle path

    pthread_t thread;
    if (pthread_create(&thread, NULL, &load_resource_async, (void *)path) != 0) {
        printf("Failed to create thread.\n");
        return -1;
    }

    sleep(2);  // allow some time for the thread to load the bundle

    pthread_mutex_lock(&lock);
    if (num_bundles > 0) {
        printf("Bundle: %s\n", bundles[0]->path);
    } else {
        printf("No bundles loaded.\n");
    }
    pthread_mutex_unlock(&lock);

    if (pthread_join(thread, NULL) != 0) {
        printf("Failed to join thread.\n");
        return -1;
    }

    // cleanup
    for (int i=0; i<num_bundles; ++i) {
        free(bundles[i]->path);
        zip_discard(bundles[i]->bundle);
        free(bundles[i]);
    }
    free(bundles);

    return 0;
}
```
