Here is a simple Python script that uses threading to process multiple log files concurrently and store the data in an SQLite database. For simplicity, we assume each log file contains only one line of JSON data which represents sensor data:

```python
import json
import sqlite3
from threading import Thread

class DataProcessor(Thread):
    def __init__(self, filename):
        super().__init__()
        self.filename = filename

    def run(self):
        with open(self.filename) as f:
            for line in f:
                data = json.loads(line)
                if not self._filter_anomalies(data):  # Filter out anomalies
                    continue
                self._store_in_db(data)   # Store cleaned data into SQLite database

    def _filter_anomalies(self, data):
        """Filter out anomalous sensor readings. For simplicity, we assume any reading > 100 is an anomaly."""
        return all(value <= 100 for value in data.values())

    @staticmethod
    def _store_in_db(data):
        conn = sqlite3.connect('sensor_data.db')
        cursor = conn.cursor()
        # For simplicity, let's assume each log file contains only sensor readings from one device and time point
        cursor.execute('''CREATE TABLE IF NOT EXISTS data 
                          (device TEXT, timestamp INTEGER, reading REAL)''')
        for key, value in data.items():
            cursor.execute("INSERT INTO data VALUES (?, ?, ?)", (key, None, value))
        conn.commit()
        conn.close()

# Create a DataProcessor thread for each log file and start it
threads = [DataProcessor(filename) for filename in ['log1.json', 'log2.json']]
for t in threads:
    t.start()
```

