```java
import java.io.*;
import java.util.Properties;

public class Deserializer {
    private static final String CONFIG_FILE = "config.properties";
    private static final Properties props;

    // load config properties during startup
    static {
        try(InputStream is = new FileInputStream(CONFIG_FILE)) {
            props = new Properties();
            props.load(is);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration", e);
        }
    }

    public Object deserializeObject(byte[] byteArray) {
        if (!props.containsKey("classname")) {
            throw new RuntimeException("Configuration file is missing classname property");
        }

        String className = props.getProperty("classname");

        try (ByteArrayInputStream bis = new ByteArrayInputStream(byteArray); 
             ObjectInput in = new ObjectInputStreamWithLoader(bis, Thread.currentThread().getContextClassLoader())) {
            return Class.forName(className).cast(in.readObject());
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object", e);
        } 
    }
}
```
