using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using ThirdPartyLoggingLibrary;

public class CustomDataLoader<T> where T : ICacheable // assuming your custom data structure implements this interface
{
    private readonly string _filePath;
    private readonly IDatabase _database;
    private readonly ILogger _logger = LoggerFactory.GetLogger();

    public CustomDataLoader(string filePath, IDatabase database) 
    {
        _filePath = filePath;
        _database = database;
    }

    // This method will throw a FileNotFoundException if the binary file does not exist
    public T Load()
    {
        var formatter = new BinaryFormatter();

        try 
        {
            using (var stream = new FileStream(_filePath, FileMode.Open))
            {
                return (T)formatter.Deserialize(stream);
            }
        }
        catch (FileNotFoundException e) 
        {
            _logger.Error("Binary file not found", e);

            // Retrieve from database instead
            var data = _database.GetData();

            if (data != null)
                return data;

            throw new Exception("File not found and no fallback data available.");
        } 
        catch (Exception e) 
        {
            // Handle other exceptions here, possibly logging the error for further investigation
            _logger.Error(e);
        }

        return default(T);
    }
}
