Now, we'll create a service class that uses Retrofit and Guava Cache:
```java
import retrofit2.Call;
import retrofit2.Response;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

public class WeatherService {
    private final LoadingCache<String, Call<WeatherData>> cache;
    private int requestCount = 0;
    private int hitCount = 0;
    private int missCount = 0;

    public WeatherService() {
        this.cache = CacheBuilder.newBuilder().maximumSize(100).expireAfterWrite(3, TimeUnit.HOURS)
                .build(new CacheLoader<String, Call<WeatherData>>() {
                    @Override
                    public Call<WeatherData> load(String location) throws Exception {
                        return WeatherApiClient.getInstance().getService().getWeather(location);
                    }
                });
    }

    public Response<WeatherData> getWeatherData(String location) throws ExecutionException, InterruptedException {
        Call<WeatherData> call = cache.get(location);
        ++requestCount;
        if (call != null && call.execute().isSuccessful()) {
            ++hitCount;
            return call.execute();
        } else {
            ++missCount;
            // Handle fallback here...
            return Response.success(new WeatherData());
        }
    }

    public void printStats() {
        System.out.println("Total API requests: " + requestCount);
        System.out.println("Cache hits: " + hitCount);
        System.out.println("Cache misses: " + missCount);
    }
}
```
