Here is an example of how you could implement such a system using Node.js with Kafka as the real-time data source:

```javascript
const kafka = require('kafka-node');
const crypto = require('crypto');

// Load configuration from environment variables or another secure location
const encryptionKey = process.env.ENCRYPTION_KEY;
const algorithm = 'aes-256-cbc';
const inputEncoding = 'utf8';
const outputEncoding = 'hex';

class EncryptionStream {
  constructor(kafkaClient, kafkaTopic, pauseEnabled) {
    this.producer = new kafka.Producer(kafkaClient);
    this.topic = kafkaTopic;
    this.pauseEnabled = pauseEnabled || false;
    this.messagesProcessed = 0;
  }

  processData(data) {
    if (this.pauseEnabled) return;

    const cipher = crypto.createCipher(algorithm, encryptionKey);
    let encryptedData = cipher.update(data, inputEncoding, outputEncoding);
    encryptedData += cipher.final(outputEncoding);

    // Add encrypted data to Kafka topic for processing
    const payloads = [{
      topic: this.topic,
      messages: JSON.stringify(encryptedData),
      partition: 0 // Partition can be changed based on the use case 
    }];

    this.producer.send(payloads, (err, data) => {
      if (err) console.log('Error sending message', err);

      this.messagesProcessed++;
    });
  }

  pause() {
    this.pauseEnabled = true;
  }

  resume() {
    this.pauseEnabled = false;
  }
}
```
This code creates a class `EncryptionStream` which encapsulates the functionality for data encryption and sending to Kafka. The system also allows for pausing and resuming of incoming data streams using methods defined in the class. 

