Here is a simplified version of such a function in C language. Note that this function assumes that the FSA structure has been defined elsewhere, with a 'next' pointer member which points to the next state in the list. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h> // for thread safety

// Assume this is your FSA structure
typedef struct {
    int state;
    struct State* next;
} State;

// function to generate the new list of states
State* generate_state_list(int *states, int num_states, State *fsa, int last_state) {
    if (states == NULL || fsa == NULL || num_states <= 0 || last_state < 0){
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    // allocate memory for the new state list 
    State *new_list = (State*)malloc(num_states*sizeof(State));

    if (new_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // generate the new list of states
    for (int i = 0; i < num_states; ++i){
        new_list[i].state = states[i];
        if(i == num_states - 1) {
            new_list[i].next = NULL;
        } else {
            new_list[i].next = &new_list[i+1];
        }
    }

    // Update the 'next' pointer of the last state in the original list
    State *last_state_ptr = fsa;
    for (int i = 0; i < last_state && last_state_ptr != NULL; ++i) {
        last_state_ptr = last_state_ptr->next;
    }

    if(last_state_ptr == NULL){
        fprintf(stderr, "Last state index out of bounds\n");
        free(new_list); // Free the allocated memory in case of error
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // initialize a mutex for thread safety
    pthread_mutex_lock(&lock); // Lock to ensure atomicity of the operation

    last_state_ptr->next = new_list;

    pthread_mutex_unlock(&lock); // Unlock

    return new_list;
}
```
