#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>

EVP_CIPHER *get_cipher(const char *mode) {
    EVP_CIPHER *cipher = NULL;

    // Dynamic selection of ciphers based on user input
    if (strcasecmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcasecmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcasecmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcasecmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    } else if (strcasecmp(mode, "NULL") == 0) {
        cipher = EVP_enc_null();
    } else {
        // Error handling for invalid cipher mode inputs
        fprintf(stderr, "Invalid cipher mode: %s\n", mode);
    }

    return cipher;
}
```

