```java
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.model.*;
import org.apache.commons.codec.digest.DigestUtils;
import java.io.File;
import java.util.HashMap;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileUploaderService {
    private HashMap<String, String> cache = new HashMap<>();
    // Using AmazonS3 as an example of a cloud storage service 
    private AmazonS3 s3Client; 
    ExecutorService executorService = Executors.newFixedThreadPool(10);

    public FileUploaderService() {
        this.s3Client = new S3ClientProvider().get(); // replace with actual client provider
    }

    void fileUploaderService(String filePath, String bucketName, String directoryPath) throws Exception {
        Callable<String> callableTask = () -> uploadFileToS3(filePath, bucketName, directoryPath);
        executorService.submit(callableTask).get();
    }

    private String uploadFileToS3(String filePath, String bucketName, String keyName) throws Exception {
        File file = new File(filePath);
        long startTime = System.currentTimeMillis();
        PutObjectRequest request = new PutObjectRequest(bucketName, keyName, file);
        ObjectMetadata metadata = new ObjectMetadata();
        metadata.setContentType("unknown");
        request.setMetadata(metadata);

        // check cache before uploading
        String hashKey = bucketName + "-" + directoryPath;
        if (cache.containsKey(hashKey) && cache.get(hashKey).equals(DigestUtils.sha256Hex(file))) {
            System.out.println("File already exists, skipping upload");
            return "skipped";
        }

        // if not in cache or changed, upload it 
        s3Client.putObject(request);

        long endTime = System.currentTimeMillis();
        cache.put(hashKey, DigestUtils.sha256Hex(file)); // add to cache after successful upload
        System.out.println("Successfully uploaded '" + keyName + "' in " + (endTime - startTime) / 1000d + " secs");
        return "success";
    }
}
```
