```python
import asyncio
from abc import ABC, abstractmethod
from typing import Type

class Metadata(ABC):
    @abstractmethod
    def parse_metadata(self, data: bytes) -> None:
        pass

class FileMetadataExtractor:
    def __init__(self, storage_client):
        self.storage_client = storage_client

    async def extract_metadata(self, file_path: str, metadata_class: Type[Metadata]) -> Metadata:
        try:
            data = await self.storage_client.get_file_data(file_path)
            metadata = metadata_class()
            metadata.parse_metadata(data)
            return metadata
        except TypeError as e:
            print("Type Error occurred while extracting metadata", str(e))
        except ValueError as e:
            print("Value error occured while extracting metadata", str(e))
        except Exception as e:
            print("Unexpected error occurred", str(e))
```

