```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class HashUtility
{
    private SemaphoreSlim semaphore = new SemaphoreSlim(10); // Limits to 10 simultaneous hashes

    public string GetMD5Hash(string input)
    {
        if (input == null) throw new ArgumentNullException("Input cannot be null");

        semaphore.Wait();

        try
        {
            using (var md5 = MD5.Create())
            {
                byte[] data = md5.ComputeHash(Encoding.UTF8.GetBytes(input));

                StringBuilder sb = new StringBuilder();

                for (int i = 0; i < data.Length; i++)
                    sb.Append(data[i].ToString("x2"));

                return sb.ToString();
            }
        }
        finally
        {
            semaphore.Release();
        }
    }

    public bool ValidateHashAgainstSalt(string input, string salt, string hashedInputWithSalt)
    {
        if (input == null || salt == null || hashedInputWithSalt == null) throw new ArgumentNullException("No inputs can be null");

        var hash = GetMD5Hash(salt + input);

        return hash.Equals(hashedInputWithSalt);
    }
}
```

This class uses the MD5 hashing algorithm from `System.Security.Cryptography` to get an MD5 hash of a string. It also includes a semaphore (from `System.Threading`) that restricts the number of simultaneous hashes to 10, limiting resource usage. This is a common practice to prevent system hangs in case of extreme usage patterns.
The class is thread-safe because each method acquires and releases the semaphore before and after performing its operation.

Included error handling includes checking for null inputs, which would cause a NullReferenceException if not handled. Additionally, it uses `ArgumentNullException` to provide meaningful errors when null values are passed in as input parameters.

