#include <boost/asio.hpp>
#include <iostream>
#include <thread>
#include <memory>

using namespace boost::asio;
using ip::tcp;
using std::string;
using std::cout;
using std::endl;

class HTTPClient {
private:
    io_context iocontext_;
    tcp::socket socket_{iocontext_};
    streambuf request_, response_;
public:
    void connect(const string& server, const string& path) {
        // resolve server address and port
        tcp::resolver resolver{iocontext_};
        boost::asio::connect(socket_, resolver.resolve(server, "http"));

        std::ostream request_stream(&request_);
        request_stream << "GET " << path << " HTTP/1.0\r\n";
        request_stream << "Host: " << server << "\r\n";
        request_stream << "Accept: */*\r\n";
        request_stream << "Connection: close\r\n\r\n";

        // Send the request.
        write(socket_, request_);
    }

    string readResponse() {
        boost::system::error_code error;
        while (read(socket_, response_, transfer_all(), error)) 
            ;

        if (error != error::eof)
           throw system::system_error(error);

        std::string data = buffer_cast<const char*>(response_.data());
        return data;
    }
};

int main() {
    try {
        HTTPClient client;
        client.connect("example.com", "/index.html");
        cout << "Response: \n" << client.readResponse() << endl;
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}
```
