```php
<?php
require_once 'vendor/autoload.php'; // Autoload files using Composer
use League\OAuth2\Client\Provider;

class OauthAuthenticator {
    private $providers = [];

    public function __construct() {
        $this->providers['google'] = new Provider\Google([
            'clientId'     => '{google-client-id}',
            'clientSecret' => '{google-client-secret}',
            'redirectUri'  => 'https://example.com/callback-url',
        ]);

        $this->providers['facebook'] = new Provider\Facebook([
            'clientId'     => '{facebook-client-id}',
            'clientSecret' => '{facebook-client-secret}',
            'redirectUri'  => 'https://example.com/callback-url',
        ]);

        $this->providers['github'] = new Provider\Github([
            'clientId'     => '{github-client-id}',
            'clientSecret' => '{github-client-secret}',
            'redirectUri'  => 'https://example.com/callback-url',
        ]);
    }

    public function authenticate($providerName) {
        $provider = $this->providers[$providerName];

        // If we don't have an authorization code then get one
        if (!isset($_GET['code'])) {
            // Fetch the authorization URL from the provider and redirect user to it.
            $authUrl = $provider->getAuthorizationUrl();
            $_SESSION['oauth2state'] = $provider->getState();
            header('Location: '.$authUrl);
            exit;
        } elseif (empty($_GET['state']) || (isset($_SESSION['oauth2state']) && $_GET['state'] !== $_SESSION['oauth2state'])) {
            unset($_SESSION['oauth2state']);
            exit('Invalid state');
        } else {
            try {
                // Try to get an access token using the authorization code grant.
                $token = $provider->getAccessToken('authorization_code', [
                    'code' => $_GET['code']
                ]);

                // Store the token securely in a session.
                $_SESSION['access_token'] = $token;
            } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
                exit($e->getMessage());
            }
        }
    }
}
