        /* Set http PUT here */ 
        curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "PUT");

        /* pass our list of custom made headers */ 
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        /* Perform the request, res will get the return code */ 
