using System.Collections.Generic;
using System.Threading;

public sealed class ConfigurationManager<T> where T : class, new()
{
    private static readonly Lazy<ConfigurationManager<T>> lazy = new(() => new ConfigurationManager<T>());

    public static ConfigurationManager<T> Instance => lazy.Value;

    private ReaderWriterLockSlim _locker = new();
    private T currentSettings;

    private ConfigurationManager() { }

    public void Load(string filePath)
    {
        try
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException($"Configuration file not found: '{filePath}'");

            T newSettings;
            var serializer = new XmlSerializer(typeof(T));
            using (var streamReader = new StreamReader(filePath))
            {
                newSettings = (T)serializer.Deserialize(streamReader);
            }

            _locker.EnterWriteLock();
            try
            {
                ValidateAndApplySettings(newSettings);
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to apply settings: '{ex.Message}'");
            }
            finally
            {
                _locker.ExitWriteLock();
            }
        }
        catch (Exception ex)
        {
            Logger.Error($"Failed to load configuration file: '{ex.Message}'");
        }
    }

    private void ValidateAndApplySettings(T newSettings)
    {
        // Implement your own validation logic here

        _locker.EnterWriteLock();
        try
        {
            currentSettings = newSettings;
        }
        finally
        {
            _locker.ExitWriteLock();
        }

        // Raise an event or call a method to inform other components that the settings have changed
    }
}
