    token = strtok_r(NULL, " ", &saveptr1);
    entry->client_ip = strdup(token);

    // ... parse other fields ...

    return entry;
}

void freeEntry(LogEntry* entry) {
    // Free all allocated memory
    free(entry->timestamp);
    free(entry->client_ip);
    // ... etc ...
    free(entry);
}

