#include <dlfcn.h>
#include <stdlib.h>

typedef void (*pluginFunction)(void *);

int main() {
    void* handle = dlopen("./path_to_your_plugin/myPlugin.so", RTLD_LAZY);

    if (!handle) {
        fprintf(stderr, "dlopen failed: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }

    pluginFunction func = (pluginFunction)dlsym(handle, "myPluginFunc");

    if (!func) {
        fprintf(stderr, "dlsym failed: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }

    void* data = NULL; // your data

    (*func)(data); 

    if (dlclose(handle)) {
        fprintf(stderr, "dlclose failed: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }

    return EXIT_SUCCESS;
}
```
In the above code, `./path_to_your_plugin/myPlugin.so` is a shared library (dynamic library) which has "myPluginFunc" exported function. 

