public class NetworkCompressionService
{
    private const string LogFile = "logfile.txt"; // replace with your log file path

    public async Task<DataTableReader> CompressAndTransmitAsync(byte[] data)
    {
        var sw = new Stopwatch();
        sw.Start();

        byte[] compressedData;
        using (var memoryStream = new MemoryStream())
        {
            using (var gzipStream = new GZipStream(memoryStream, CompressionLevel.Optimal))
            {
                await gzipStream.WriteAsync(data, 0, data.Length);
            }

            compressedData = memoryStream.ToArray();
        }

        // Simulate network transmission with TcpClient (replace it with your actual network code)
        using (var tcpClient = new TcpClient())
        {
            await tcpClient.ConnectAsync("your_server", 12345); // replace "your_server" and port as per your server details

            using (var networkStream = tcpClient.GetStream())
            {
                await networkStream.WriteAsync(compressedData, 0, compressedData.Length);
            }
        }

        double compressionRatio = (double)data.Length / compressedData.Length;
        sw.Stop();
        File.AppendAllText(LogFile, $"Compression ratio: {compressionRatio}, Transmission time: {sw.ElapsedMilliseconds} ms");

        // Execute your query here and return DataTableReader object instead of dummy null
        DataTable dt = new DataTable();
        DataRow dr1;
        for (int i = 0; i < 5; i++) { 
            sw.Restart();
            // Simulate query execution
            await Task.Delay(200); 
            sw.Stop();

            File.AppendAllText(LogFile, $"Query execution time: {sw.ElapsedMilliseconds} ms");
        }

        return dt.CreateDataReader();
    }
}
