import java.util.*;

public class PokemonService {
    private Map<String, List<String>> weaknessCache = new HashMap<>(); // Caching mechanism
    public String getWeaknesses(Pokemon pokemon) {
        try {
            // Using a library function to retrieve Pokemon type from an external API
            String[] types = PokemonApi.getTypes(pokemon); 
            List<String> weaknesses = new ArrayList<>();

            for (String type : types) {
                if (!weaknessCache.containsKey(type)) {
                    // Making a request to an external API to retrieve weaknesses based on the Pokemon's type
                    String[] resWeaknesses = PokemonApi.getWeaknessesByType(type); 

                    List<String> listOfWeaknesses = Arrays.asList(resWeaknesses);
                    weaknessCache.put(type, listOfWeaknesses); // Caching mechanism
                    weaknesses.addAll(listOfWeaknesses);
                } else {
                    List<String> cachedWeaknesses = weaknessCache.get(type);
                    weaknesses.addAll(cachedWeaknesses);
                }
            }

            return String.join(", ", weaknesses); // Returning the combined weakesses
        } catch (Exception e) {
            // Logging errors to a centralized logging system and providing meaningful error messages
            LoggerApi.logError("An error occurred while retrieving Pokemon's weaknesses: " + e.getMessage());

            return "An error occurred while retrieving Pokemon's weaknesses";
        } 
    }
}
