```java
import com.amazonaws.services.kms.AWSKMS;
import com.amazonaws.services.kms.AWSKMSClientBuilder;
import com.amazonaws.services.kms.model.SignRequest;
import com.amazonaws.services.kms.model.SignResult;
import io.jsonwebtoken.*;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.util.Date;

public class JwtGenerator {
    private static final String KEY_ID = "your-key-id"; // replace with your key ID

    public String generateJWT(String subject, long ttlMillis) {
        AWSKMS client = AWSKMSClientBuilder.defaultClient();
        SignRequest signReq = new SignRequest().withKeyId(KEY_ID).withMessageType("RAW").withSigningAlgorithm("RSASSA_PKCS1_V1_5_SHA_256").withMessage(toByteArray(subject));
        SignResult signResp = client.sign(signReq);
        Key signingKey = new SecretKeySpec(signResp.getSignature().array(), "HmacSHA256"); //replace HS256 with appropriate algorithm according to your key type

        if (ttlMillis >= 0) {
            long nowMillis = System.currentTimeMillis();
            Date now = new Date(nowMillis);

            JwtBuilder builder = Jwts.builder()
                    .setId("jti") // replace with your jti
                    .setIssuedAt(now)
                    .setSubject(subject)
                    .signWith(SignatureAlgorithm.HS256, signingKey);

            if (ttlMillis > 0) {
                builder.setExpiration(new Date(nowMillis + ttlMillis));
            }

            return builder.compact();
        } else {
            throw new IllegalArgumentException("The TTL must be greater than or equal to zero.");
        }
    }

    private byte[] toByteArray(String s) {
        // convert string to byte array
    }
}
``` 
This code generates a JWT using the KMS. It signs the token with the key retrieved from KMS, and then builds the JWT with the signed key. This is just an example and will need to be expanded significantly for production use. Also note that AWS SDK dependencies are required in your project for it work properly.

