    json_t* metadata; 
    get_metadata(job->file_name, &metadata); // Get metadata about the image

    ImageInfo *imageInfo;
    ExceptionInfo exception;
    Image *image;

    MagickCoreGenesis("convert", MagickTrue);
    imageInfo = AcquireImageInfo();
    GetExceptionInfo(&exception);

    strcpy(imageInfo->filename, job->file_name); // Set input file name
    image = ReadIMage(imageInfo, &exception);
    if (exception.severity != UndefinedException) 
        CatchException(&exception);

    strcat(job->output_dir, "/output.pdf");
    strcpy(imageInfo->filename, job->output_dir); // Set output file name
    WriteImage(imageInfo, image);

    DestroyImage(image);
    DestroyExceptionInfo(&exception);
    DestroyImageInfo(imageInfo);
    MagickCoreTerminus();
}

