    pthread_t thread; 
    if (pthread_create(&thread, NULL, jpeg_to_pdf, &job)) {
        printf("Error creating thread\n");
        return -1;
    }
    if(pthread_join(thread, NULL)) {
        printf("Error joining thread\n");
        return -2;
    }

    printf("JPEG to PDF conversion successful\n");
    return 0;
