Please note that this is a simple implementation and may not cover all edge cases:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to compare two doubles for qsort()
int cmp(const void *a, const void *b) {
    double fa = *((double*) a);
    double fb = *((double*) b);
    return (fa > fb) - (fa < fb);
}

// Function to find the largest value in an array of doubles
double find_largest(double* arr, int n){
    if(n == 0) {
        printf("The file was empty.\n");
        return 0;
    }

    qsort(arr, n, sizeof(double), cmp); // sort the array
    return arr[n - 1]; // return largest value
}

int main() {
    FILE *file = fopen("values.txt", "r"); // open file for reading

    if (file == NULL) {
        printf("Failed to open the file.\n");
        return -1;
    }

    double* arr = malloc(sizeof(double)); // allocate memory for array
    int size = 0;
    while (!feof(file)) { 
        if (fscanf(file, "%lf", &arr[size]) == 1) {
            size++;
            double *tmp = realloc(arr, sizeof(double) * (size + 1)); // increase array size
            if(tmp != NULL){
                arr = tmp;
            } else{
                printf("Out of memory.\n");
                free(arr);
                return -2;
            }
        } else {
            fscanf(file, "%*[^\n]"); // skip invalid value
        }
    }

    double largest = find_largest(arr, size);
    printf("The largest value is: %.2lf\n", largest);

    free(arr); // free memory
    fclose(file); // close file
    return 0;
}
```
This code assumes that the values in the file are separated by whitespace, and each line contains exactly one double-precision floating point number. If these assumptions don't hold, you may need to adjust this code accordingly. Also, it doesn't handle errors that occur while opening or reading from the file.

