```python
from flask import Flask, request, jsonify
import boto3 # Boto3 is AWS SDK used to access S3 (Simple Storage Service) which supports high durability.
from botocore.exceptions import NoCredentialsError

app = Flask(__name__)
s3 = boto3.client('s3')
bucket_name = 'your-unique-bucket-name' # This should be a globally unique name for your S3 bucket.

class FileStorage:
    def upload(self, file):
        try:
            s3.upload_fileobj(file, bucket_name, file.filename)
            return True
        except FileNotFoundError:
            print("The file was not found")
            return False
        except NoCredentialsError:
            print("Credentials not available")
            return False

    def download(self, filename):
        try:
            s3.download_file(bucket_name, filename, filename)
            return True
        except FileNotFoundError:
            print("The file was not found")
            return False
        except NoCredentialsError:
            print("Credentials not available")
            return False

    def delete(self, filename):
        try:
            s3.delete_object(Bucket=bucket_name, Key=filename)
            return True
        except FileNotFoundError:
            print("The file was not found")
            return False
        except NoCredentialsError:
            print("Credentials not available")
            return False

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'message': 'No file part in the request'}), 400

    file = request.files['file']

    if FileStorage().upload(file):
        return jsonify({'message': 'File uploaded successfully'}), 201
    else:
        return jsonify({'message': 'Failed to upload the file'}), 500

@app.route('/download/<filename>', methods=['GET'])
def download_file(filename):
    if FileStorage().download(filename):
        return jsonify({'message': 'File downloaded successfully'}), 200
    else:
        return jsonify({'message': 'Failed to download the file'}), 500

@app.route('/delete/<filename>', methods=['DELETE'])
def delete_file(filename):
    if FileStorage().delete(filename):
        return jsonify({'message': 'File deleted successfully'}), 200
    else:
        return jsonify({'message': 'Failed to delete the file'}), 500

if __name__ == "__main__":
    app.run(debug=True)
```
