#include <libgen.h>
#include <unistd.h>
#include <limits.h>
#include <stdio.h>
#include <errno.h>
#include <stdlib.h>

static char current_dir[PATH_MAX] = "";
char error_buffer[256];

const char *getFullPath(char* path, int maxSize, bool isAbsolute) {
    // Validate file path length
    if (strlen(path) > maxSize) {
        snprintf(error_buffer, sizeof(error_buffer), "The path exceeds the maximum size limit.");
        return NULL;
    }

    char *realPath = realpath(path, NULL);
    if (!realPath) {
        snprintf(error_buffer, sizeof(error_buffer), "Invalid file path: %s", strerror(errno));
        return NULL;
    }

    // If not absolute append the current directory
    if (isAbsolute == false && strncmp(realPath, current_dir, strlen(current_dir)) != 0) {
        size_t newSize = strlen(current_dir) + strlen(path) + 2;  // for '/' and '\0'
        char *fullPath = malloc(newSize);

        if (fullPath == NULL) {
            snprintf(error_buffer, sizeof(error_buffer), "Failed to allocate memory: %s", strerror(errno));
            free(realPath);
            return NULL;
        }

        strncpy(fullPath, current_dir, newSize);
        strcat(fullPath, "/");
        strcat(fullPath, path);

        free(realPath);
        return fullPath;
    } else {
        return realPath;
    }
}
```

