This problem involves a broad range of complexities which cannot be solved using only JavaScript due to security restrictions in browsers, Node.js or other client-side environments. For secure execution of shell commands, it is generally recommended to use server-side languages like Python or Ruby and expose an API that your JavaScript code can interact with.

Nevertheless, a simple proof-of-concept could look something like this:

```javascript
const { spawn } = require('child_process');
let activeProcesses = 0;
let maxConcurrentProcesses = 10; // Set by the user or system configurations

function executeCommand(cmd, args, options) {
    return new Promise((resolve, reject) => {
        if (activeProcesses >= maxConcurrentProcesses) {
            reject('Too many concurrent processes');
            return;
        }
        ++activeProcesses;

        const child = spawn(cmd, args, options);
        let stdoutData = '';
        let stderrData = '';

        // Log standard output and error to console and log files.
        child.stdout.on('data', (data) => {
            stdoutData += data;
            // TODO: Add code here to send stdoutData to an external logging service or a file.
            console.log(`${cmd} output: ${data}`);
        });

        child.stderr.on('data', (data) => {
            stderrData += data;
            // TODO: Add code here to send stderrData to an external logging service or a file.
            console.error(`${cmd} error: ${data}`);
        });

        child.on('close', (code) => {
            --activeProcesses;
            if (code === 0) {
                resolve({ stdoutData, stderrData });
            } else {
                reject(new Error(`${cmd} failed with error code ${code}. StdErr: ${stderrData}`));
            }
        });

        child.on('error', (err) => {
            --activeProcesses;
            reject(new Error(`Error spawning ${cmd}: ${err.message}. StdErr: ${stderrData}`));
        });
    });
}
```

This code is a simple implementation and does not cover all constraints like command chaining, logging to external services or error message obfuscation. Also, please note that it's essential to use this function carefully as improper usage can lead to severe security vulnerabilities. Always sanitize user inputs or commands when using `spawn` or similar functions for executing shell commands.

