Here's an example of how you might design your `TransactionReducer` class in JavaScript. This sample uses `axios` for HTTP requests, `p-limit` to control concurrency, and `bottleneck` for rate limiting. Please note that the code below is a simplified version. Error handling and more sophisticated features are not included here, and they would need to be added in a production environment:

```js
const axios = require('axios');
const Bottleneck = require('bottleneck');
const PQueue = require('p-queue');
const limiter = new Bottleneck({maxConcurrent: 100});

class TransactionReducer {
    constructor(apiUrl) {
        this.apiUrl = apiUrl;
        this.queue = new PQueue({concurrency: 5, intervalCap: 20, interval: 100});
    }

    async fetchTransactionDetails(id) {
        let retryCount = 0;
        while (retryCount < 3) {
            try {
                const response = await axios.get(`${this.apiUrl}/${id}`);
                return response.data;
            } catch (error) {
                if (error.response && error.response.status >= 500 && retryCount < 3) {
                    const delay = Math.pow(2, retryCount) * 1000; // exponential backoff
                    console.log(`Retrying in ${delay}ms...`);
                    await new Promise(resolve => setTimeout(resolve, delay));
                } else {
                    throw error;
                }
            }
        }
    }

    async processTransactions(ids) {
        const details = await Promise.all(ids.map((id) => this.queue.add(() => this.fetchTransactionDetails(id))));
        return details;
    }
}
```

