public class DynamicWeatherMiddleware
{
    private readonly string _locationDetails;

    public DynamicWeatherMiddleware(string locationDetails)
    {
        _locationDetails = locationDetails ?? throw new ArgumentNullException(nameof(locationDetails));
    }

    // This method simulates temperature within the provided range and specific distribution.
    public double SimulateTemperature(double min, double max, Func<double, double> distribution)
    {
        var randomNumber = new Random().NextDouble();
        var temperature = min + (max - min) * distribution(randomNumber);

        return temperature;
    }

    // This method simulates humidity within the provided range and specific distribution.
    public double SimulateHumidity(double min, double max, Func<double, double> distribution)
    {
        var randomNumber = new Random().NextDouble();
        var humidity = min + (max - min) * distribution(randomNumber);

        return humidity;
    }

    // This method simulates wind speed within the provided range and specific distribution.
    public double SimulateWindSpeed(double min, double max, Func<double, double> distribution)
    {
        var randomNumber = new Random().NextDouble();
        var windSpeed = min + (max - min) * distribution(randomNumber);

        return windSpeed;
    }

    // This method simulates precipitation levels within the provided range and specific distribution.
    public double SimulatePrecipitationLevels(double min, double max, Func<double, double> distribution)
    {
        var randomNumber = new Random().NextDouble();
        var precipitationLevels = min + (max - min) * distribution(randomNumber);

        return precipitationLevels;
    }

    // This method fetches real-time data from a specific API.
    public async Task<string> FetchDataFromAPIAsync(string apiUrl, Dictionary<string, string> headers = null)
    {
        using (var httpClient = new HttpClient())
        {
            if (headers != null)
            {
                foreach (var header in headers)
                    httpClient.DefaultRequestHeaders.Add(header.Key, header.Value);
            }

            var response = await httpClient.GetAsync(apiUrl);

            return await response.Content.ReadAsStringAsync();
        }
    }
}
