    public Mono<String> generateAndProcessJWT(AuthRequest authRequest) {
        return Flux.just(authRequest)
                .filter(request -> validateUserRolePermissions(request))
                .flatMap(this::retrievePrivateKeyFromKMS)
                .map(privateKey -> createAndSignJWT(privateKey, authRequest))
                .doOnNext(jwtToken -> logAuditInfo("Generated JWT", jwtToken))
                .flatMap(this::processPaymentAsync)
                .onErrorResume(e -> handleErrorsAndExceptions(e));
    }

