    private Mono<PaymentResponse> processPaymentAsync(String jwtToken) {
        return Mono.just(jwtToken).flatMapMany(token ->{
            // dynamically decide payment method based on system load and availability
            if (/*stripe is available*/){
                return stripeService.processStripePaymentAsync(token);
            } else if (/*paypal is available*/) {
                return paypalService.processPayPalPaymentAsync(token);
            } /*... handle other payment methods */
