import com.amazonaws.services.s3.AmazonS3;
import com.azure.storage.blob.BlobClient;
import com.google.cloud.storage.Storage;
import java.io.File;
import java.util.HashMap;
import org.apache.commons.codec.digest.DigestUtils;
import org.apache.commons.io.IOUtils;

public class FileUploaderService {
    private static final String S3 = "S3";
    private static final String AZURE = "Azure Blob Storage";
    private static final String GCS = "Google Cloud Storage";

    private AmazonS3 s3Client;
    private BlobClient azureBlobClient;
    private Storage gcsStorage;
    private HashMap<String, String> fileHashCache = new HashMap<>(); // Simplified caching mechanism

    public void uploadFile(String filePath, String bucketName, String directoryPath, String targetCloudService) {
        File file = new File(filePath);

        // Check file metadata and cache the hash for later use
        if (!isValidMetadata(file)) return;
        String hash = calculateSHA256Hash(file);

        // Upload to cloud storage service based on configuration setting
        try {
            switch (targetCloudService) {
                case S3:
                    s3Client.putObject(bucketName, directoryPath + file.getName(), file);
                    break;
                case AZURE:
                    azureBlobClient.uploadFromFile(filePath);
                    break;
                case GCS:
                    gcsStorage.create(BlobInfo.newBuilder(bucketName, directoryPath + file.getName()).build(), IOUtils.toByteArray(file));
                    break;
            }
        } catch (Exception e) {
            // Handle errors from each cloud storage service
            System.out.println("Error occurred while uploading to " + targetCloudService);
        }

        // Cache the hash for later use
        fileHashCache.put(filePath, hash);
    }

    private boolean isValidMetadata(File file) {
        // Perform validation check here
        return true;
    }

    private String calculateSHA256Hash(File file) {
        try {
            return DigestUtils.sha256Hex(file);
        } catch (Exception e) {
            System.out.println("Error occurred while calculating SHA-256 hash");
        }
        return null;
    }
}
```

