from ratelimiter import RateLimiter
from tenacity import retry, stop_after_attempt, wait_exponential
from influxdb import InfluxDBClient
import threading

# KMS access function is omitted for brevity.
class Client:
    def __init__(self):
        self.api_urls = os.environ['API_URLS'].split(',')
        self.client_id = os.environ['CLIENT_ID']
        self.client_secret = os.environ['CLIENT_SECRET']
        self.kms_access_function = kms_access_function
        self.influxdb_client = InfluxDBClient(host='localhost', port=8086)
        self.rate_limiter = RateLimiter(max_calls=10, period=1)

    def authenticate(self):
        client = BackendApplicationClient(client_id=self.client_id)
        oauth = OAuth2Session(client=client)
        token = self.kms_access_function()  # Get the OAuth2 token from KMS
        return oauth, token['token']

    @retry(stop=stop_after_attempt(3), wait=wait_exponential())
    def send_request(self, api_url):
        oauth, token = self.authenticate()
        with self.rate_limiter:
            response = oauth.get(api_url, headers={'Authorization': 'Bearer {}'.format(token)})
            if not response.ok:
                raise Exception('Request failed')
        return response.json()

    def process_responses(self):
        threads = [threading.Thread(target=self.send_request, args=(url,)) for url in self.api_urls]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()
