    JSScript *script;
} ThreadData;

static void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%s: %s", __FILE__, __FUNCTION__);
    vsnprintf(&buffer[strlen(buffer)], sizeof(buffer) - strlen(buffer) - 1, format, args);
    va_end(args);

    // Log the message to the error log using suitable logging library
}

static void *js_thread_func(void *arg) {
    ThreadData *data = (ThreadData *) arg;

    JSAutoRequest ar(data->cx);
    js::RunScript(data->cx, data->script);
    if (!JS_IsExceptionPending(data->cx)) {
        // Handle script execution success
    } else {
        log_message("Failed to execute JavaScript file");
        JS_ClearPendingException(data->cx);
    }

    return NULL;
}

void run_js_file(const char *filename) {
    JSRuntime *rt = JS_NewRuntime(8L * 1024 * 1024);
    if (!rt) {
        log_message("Failed to create JavaScript runtime");
        return;
    }

    JSContext *cx = JS_NewContext(rt, 8192);
    if (!cx) {
        log_message("Failed to create JavaScript context");
        return;
    }

    ThreadData data = { cx, NULL };
    js::InitSelfHostedCode(cx);

    const char *srcbuf;
    size_t srclen;
    if (!JS_ReadFileFromPath(filename, &srclen, &srcbuf)) {
        log_message("Failed to load JavaScript file");
        return;
    }

    data.script = JS::CompileForSelfHostedCode(cx, (unsigned char *) srcbuf, srclen);
    if (!data.script) {
        log_message("Failed to compile JavaScript file");
        return;
    }

    pthread_t threadId;
    if (pthread_create(&threadId, NULL, js_thread_func, &data)) {
        log_message("Failed to create a new thread for JavaScript execution");
    } else {
        pthread_detach(threadId); // No need to join the thread here
    }
}
