    private readonly RijndaelManaged _rijndael = new RijndaelManaged();
    private StorageClient _storageClient;

    public void DecryptAndUpload(byte[] ciphertext, string bucketName, byte[] key, byte[] IV)
    {
        if (key == null || key.Length <= 0)
            throw new ArgumentNullException("Key cannot be empty");

        if (IV == null || IV.Length <= 0)
            throw new ArgumentNullException("IV cannot be empty");

        _rijndael.Key = key;
        _rijndael.IV = IV;

        using (ICryptoTransform decryptor = _rijndael.CreateDecryptor(_rijdxael.Key, _rijndael.IV))
        {
            byte[] originalBytes = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);

