            // Store in PostgreSQL Database
            using (var connection = new NpgsqlConnection("connectionString"))
            using (var command = new NpgsqlCommand("INSERT INTO Files VALUES (@file)", connection))
            {
                command.Parameters.AddWithValue("@file", originalBytes);

