import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.text.SimpleDateFormat;
import java.util.Arrays;
import java.util.Properties;

public class Main {
    private static final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    private static Properties config;

    public static void main(String[] args) throws IOException {
        // Load config file
        loadConfig();

        String filename = config.getProperty("filename", "logfile.txt");
        Files.deleteIfExists(Paths.get(filename));

        String dir = config.getProperty("dir", System.getProperty("user.dir"));
        String[] commands = {"ls -l", "pwd"};

        for (String command : commands) {
            try {
                Process process = Runtime.getRuntime().exec(command, null, new File(dir));

                BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String s;
                while ((s = stdInput.readLine()) != null) {
                    logMessage("INFO", s);
                }

                while ((s = stdError.readLine()) != null) {
                    logMessage("ERROR", s);
                }
            } catch (IOException e) {
                // Handle and log the error
                logMessage("ERROR", "Failed to execute command: " + Arrays.toString(e.getStackTrace()));
            }
        }
    }

    private static void loadConfig() throws IOException {
        config = new Properties();

        try (InputStream inputStream = Files.newInputStream(Paths.get("config.properties"))) {
            config.load(inputStream);
        } catch (IOException e) {
            logMessage("ERROR", "Failed to load configuration: " + Arrays.toString(e.getStackTrace()));
        }
    }

    private static void logMessage(String severity, String message) {
        // If the severity level is lower than the configured one, don't log it
        if (severity.equals("ERROR") && config.containsKey("logLevel") && config.getProperty("logLevel").equals("INFO")) return;

        try(FileWriter fw = new FileWriter("logfile.txt", true);
            BufferedWriter bw = new BufferedWriter(fw);
            PrintWriter out = new PrintWriter(bw)) {
                String timestamp = sdf.format(new java.util.Date());
                out.printf("%s [%s] %s\n", timestamp, severity, message);
        } catch (IOException e) {
            System.out.println("Failed to write to logfile: " + Arrays.toString(e.getStackTrace()));
        } 
    }
}
```
