public class ClassDeserializer {
    private static final Logger LOGGER = LoggerFactory.getLogger(ClassDeserializer.class);
    private static final Map<String, Pair<Class<?>, ReentrantLock>> CLASS_CACHE = new HashMap<>();
    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static synchronized <T> T deserialize(byte[] data, Class<T> clazz) {
        try {
            return MAPPER.readValue(data, clazz);
        } catch (IOException e) {
            LOGGER.error("Error deserializing byte array to class", e);
            throw new RuntimeException("Failed to deserialize byte array to class", e);
        }
    }
}
