import java.awt.*;
import java.awt.image.*;
import javax.imageio.*;
import java.io.*;

public class ImageCompressionService {

    public BufferedImage compress(BufferedImage source, float quality) throws IOException{
        if (quality <= 0 || quality > 1){
            throw new IllegalArgumentException("Quality should be in the range from 0 to 1");
        }

        // Convert back to original type after write
        var originalType = source.getType();
        BufferedImage target = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = target.createGraphics();
        g.setComposite(AlphaComposite.Src);
        g.drawImage(source, null, 0, 0);

        // Write to output stream
        var os = new ByteArrayOutputStream();
        ImageIO.write(target, "jpg", os);

        // Calculate the maximum quality based on file size and desired compression level
        int maxQuality = 100;
        byte[] bytes = os.toByteArray();

        while (bytes.length > targetSize && maxQuality > 0) {
            os = new ByteArrayOutputStream();
            ImageIO.write(target, "jpg", os);
            bytes = os.toByteArray();

            // Reduce quality
            g.dispose();
            maxQuality -= 1;
        }

        return target;
    }
}
```

The above code compresses a given image by decreasing its quality until it fits within the desired size. Note that the ImageIO#write method doesn't actually provide control over the file size, so this solution provides an approximation based on compressing at each iteration of lower quality levels and measuring the output size. 

