```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor
import logging
import asyncio
import aiofiles

class DataProcessor:
    def __init__(self, storage_path, num_workers):
        self.storage_path = storage_path
        self.num_workers = num_workers
        self.logger = logging.getLogger(__name__)

    async def process_file(self, file_path):
        md5 = hashlib.md5()
        with open(file_path,'rb') as f: 
            for chunk in iter(lambda: f.read(4096),b""): 
                md5.update(chunk) 
        return md5.hexdigest()

    async def process_files(self, file_paths):
        with ThreadPoolExecutor(max_workers=self.num_workers) as executor:
            loop = asyncio.get_event_loop()
            tasks = [loop.run_in_executor(executor, self.process_file, file_path) for file_path in file_paths]
            for response in await asyncio.gather(*tasks):
                pass # Process the result here

    def get_all_files(self, dirName):
        listOfFile = os.listdir(dirName)
        allFiles = list()
        for entry in listOfFile:
            fullPath = os.path.join(self, dirName, entry)
            if os.path.isdir(fullPath):
                allFiles = allFiles + self.get_all_files(fullPath)
            else:
                allFiles.append(fullPath)
        return allFiles

    async def run(self):
        file_paths = self.get_all_files(self.storage_path)
        await self.process_files(file_paths)
```

