using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly string _connectionString;

    public FileHasher(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<DataTableReader> ExecuteQueryAndReturnResultAsync(byte[] queryBytes)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            var command = new SqlCommand(System.Text.Encoding.Default.GetString(queryBytes), connection);

            return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
        }
    }
}
