#include <stdlib.h>
#include <string.h>

// Appends slash if the string length is within limit
char* appendSlash(const char *str, int sizeLimit) {
    if (sizeLimit <= 0 || str == NULL) return NULL;

    int len = strlen(str);
    if (len > sizeLimit) return NULL;

    // Allocate memory for the new string and copy the original string into it
    char* result = malloc((len + 2) * sizeof(char));
    if (result == NULL) return NULL;

    strcpy(result, str); 
    // Append a slash to the end of the string
    result[len] = '/';
    result[len + 1] = '\0'; // Null-terminate the string

    return result;
}
