```python
import os
import threading
import queue
from configparser import ConfigParser

# Read configuration file and get data files
config = ConfigParser()
config.read('configuration.ini')
file_paths = config['Files']['paths'].split(',')

# Queue to hold sorted lines of each file
queue = queue.Queue()

def sort_and_extract(file_path):
    try: 
        with open(file_path, 'r+') as f:
            # Acquire a lock before processing the file
            fcntl.flock(f, fcntl.LOCK_EX)

            lines = f.readlines()
            lines.sort()
            sequence_number = int(lines[-1].split(' ')[0])

            # Add sorted lines and sequence number to queue
            queue.put((sequence_number, lines))
    except IOError: 
        print("Failed to open/read file " + file_path)
    finally:
        fcntl.flock(f, fcntl.LOCK_UN)

# Use a thread for each data file
threads = []
for file_path in file_paths: 
    t = threading.Thread(target=sort_and_extract, args=(file_path,))
    threads += [t]
    t.start()

# Wait for all threads to finish
for t in threads: 
    t.join()

# Aggregate results into a single output file
with open('output.txt', 'w') as outfile: 
    while not queue.empty(): 
        sequence_number, lines = queue.get()
        for line in lines: 
            outfile.write(line)
```

