```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "zlib.h"
#include "apr_pools.h"

typedef struct ResourceBundle {
    char* data;
    size_t size;
    apr_pool_t* pool;
} ResourceBundle;

static apr_pool_t *memPool = NULL;
static pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

ResourceBundle loadBundleFromZip(const char *zipFile) {
    gzFile inFileZ = gzopen(zipFile, "rb");
    if (inFileZ == NULL) {
        fprintf(stderr, "Error: Failed to open zip file %s\n", zipFile);
        exit(1);
    }

    char buffer[8192];
    int len = 0;
    apr_pool_t *pool = NULL;
    apr_pool_create(&pool, NULL);
    ResourceBundle bundle = {.data = NULL, .size = 0, .pool = pool};

    if (pthread_rwlock_wrlock(&lock) != 0) {
        fprintf(stderr, "Error: Failed to acquire write lock\n");
        exit(1);
    }

    while ((len = gzread(inFileZ, buffer, sizeof(buffer))) > 0) {
        if (bundle.data == NULL) {
            bundle.size = len;
            bundle.data = apr_palloc(pool, bundle.size);
            memcpy(bundle.data, buffer, len);
        } else {
            bundle.size += len;
            bundle.data = apr_prealloc(pool, bundle.data, bundle.size);
            memcpy(bundle.data + (bundle.size - len), buffer, len);
        }
    }

    gzclose(inFileZ);
    pthread_rwlock_unlock(&lock);

    return bundle;
}

int main() {
    // Initialize memory pool
    apr_pool_create(&memPool, NULL);

    // Load a resource bundle from a zip file
    ResourceBundle bundle = loadBundleFromZip("mybundle.zip");

    // Use the loaded bundle...

    return 0;
}
```
