using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using Microsoft.Extensions.Configuration;
using Serilog;

public class WebsiteManager
{
    private readonly IConfiguration _config;

    public WebsiteManager(IConfiguration config)
    {
        _config = config ?? throw new ArgumentNullException(nameof(config));

        Log.Logger = new LoggerConfiguration()
            .WriteTo.File(_config["Logging:FilePath"])
            .CreateLogger();
    }

    public void AddAndStartSite(string directoryPath, string siteName)
    {
        if (string.IsNullOrEmpty(directoryPath)) throw new ArgumentException("Invalid Directory Path");

        var webConfig = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfig))
        {
            Log.Error("Web config does not exist at path: {@path}", directoryPath);
            return;
        }

        // Check for existing running site with same name and prevent duplicate startup
        var allProcesses = Process.GetProcesses();
        foreach (var process in allProcesses)
        {
            if (process.ProcessName == siteName && !process.HasExited)
            {
                Log.Information("Site {@site} is already running", siteName);
                return;
            }
        }

        var startInfo = new ProcessStartInfo()
        {
            FileName = "iisexpress",
            Arguments = $"/path:\"{directoryPath}\" /port:8080",
            UseShellExecute = true,
            Verb = "runas"
        };

        try
        {
            using var process = new Process() { StartInfo = startInfo };
            process.Start();

            Log.Information("Site {@site} started with Id: {@id}, Name: {@name}", siteName, process.Id, process.ProcessName);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Failed to start website");
            throw;
        }
    }
}
