class KubernetesDeployment
{
    protected $cluster;

    public function __construct()
    {
        $this->cluster = KubernetesCluster::fromKubeConfig();
    }

    public function deploy($name, $image)
    {
        // Create a new pod using the provided image.
        $pod = $this->cluster->pod()->setName($name)->setImage($image);

        // Save it into Kubernetes.
        $pod->create();

        return $pod;
    }
}
