using System;
using System.Xml.XPath;
using MongoDB.Driver; // Assuming MongoDB as NoSQL database
using System.Net;
using System.Threading.Tasks;
using System.Linq;

public class DeviceDataProcessor {
    private IMongoCollection<Device> _deviceCollection;

    public DeviceDataProcessor(IMongoDatabase database) {
        _deviceCollection = database.GetCollection<Device>("devices");
    }

    public async Task ProcessSensorDataAsync(string xmlPath) {
        try {
            XPathDocument doc = new XPathDocument(xmlPath);
            XPathNavigator navigator = doc.CreateNavigator();

            // Extract and store most recent sensor reading for each device
            foreach (XPathNavigator node in navigator.Select("/devices/device")) {
                var deviceId = node.GetAttribute("id", "");
                var deviceReading = node.Evaluate("max(./readings/reading)").ToString();

                // Handle potential discrepancies in XML structure across devices
                if (string.IsNullOrEmpty(deviceId) || string.IsNullOrEmpty(deviceReading)) {
                    Console.WriteLine($"Invalid device or reading: {node}");
                    continue;
                }

                // Store the results to NoSQL database
                var filter = Builders<Device>.Filter.Eq("id", deviceId);
                var update = Builders<Device>.Update.Push("readings", deviceReading);

                await _deviceCollection.UpdateOneAsync(filter, update);
            }
        } catch (WebException ex) {
            Console.WriteLine($"Network error: {ex}");
            throw;
        } catch (XPathException ex) {
            Console.WriteLine($"XML parsing error: {ex}");
            throw;
        }
    }

    // Handle device metadata updates
    public async Task UpdateDeviceMetadataAsync(string id, Device updatedMetadata) {
        var filter = Builders<Device>.Filter.Eq("id", id);
        var update = Builders<Device>.Update
            .Set("metadata", updatedMetadata);

        await _deviceCollection.UpdateOneAsync(filter, update);
    }
}
