    def __init__(self, encryption_key):
        self.encryption_key = encryption_key

    async def fetch_weather(self, urls):
        async with aiohttp.ClientSession() as session:
            tasks = []
            for url in urls:
                task = asyncio.ensure_future(self._fetch(session, url))
                tasks.append(task)

            original_data = await asyncio.gather(*tasks)

        return original_data

    async def _fetch(self, session, url):
        try:
            async with session.get(url) as resp:
                data = await resp.read()

                if self._is_cached(url):
                    return self._load_from_cache(url)

                else:
                    self._store_in_cache(url, data)
            return data

        except (aiohttp.ClientError, aiohttp.http_exceptions.HttpProcessingError) as e:
            logging.error('Exception occured', exc_info=True)

    def decrypt_config(self, file):
        cipher = AES.new(self.encryption_key, AES.MODE_ECB)

        with open(file, 'rb') as f:
            encrypted_data = f.read()

        return cipher.decrypt(encrypted_data)

    def validate_config(self, config, schema):
