    public boolean validateFile(String filePath, long sizeInBytes, String contentType) throws Exception {
        try (InputStream inputStream = new BufferedInputStream(new FileInputStream(filePath))) {
            MessageDigest md = MessageDigest.getInstance("SHA-256");

            byte[] buffer = new byte[8192];
            int count;
            while ((count = inputStream.read(buffer)) > 0) {
                md.update(buffer, 0, count);
            }

            String sha256Hash = bytesToHex(md.digest());

            // Check if the file already exists in any of cloud storage services
            for (Provider provider: Provider.values()) {
                switch (provider) {
                    case AMAZON_S3: 
                        // If file is found on S3, return false
                        break;
                    case AZURE: 
                        // If file is found on Azure Blob Storage, return false
                        break;
                    case GOOGLE:
                        // If file is found on Google Cloud Storage, return false
                        break;
                }
            }

            // File doesn't exist in any cloud storage service. Validate its metadata
            if (new File(filePath).length() != sizeInBytes) {
                LOGGER.severe("File size is not valid");
                return false;
            }

            // Check content type
            // You may use Apache Tika or other libraries to guess content type by file extension
            if (!contentType.equals(guessContentType(filePath))) {
                LOGGER.severe("File content type is not valid");
                return false;
            }

            // Add the validated metadata and hash to cache for later use
            cache.put(sha256Hash, new Object[]{sizeInBytes, contentType});
            return true;
        } catch (Exception e) {
            LOGGER.severe("Error during file validation: " + e.getMessage());
            throw e;
        }
    }

