        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }
    }

    curl_easy_cleanup(curl);
    /* Clean up other resources */

    pthread_mutex_destroy(&lock); // Destroy mutex lock after operations are complete

    return 0;
}
