// Global mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; 

int safeStringCopy(const char *src, char *dest, size_t destSize) {
    pthread_mutex_lock(&mutex); // Lock the mutex for thread-safe operations

    if (strlen(src) >= destSize) {
        logError("Source string length is larger than destination buffer size. Truncation will occur.");

        strncpy(dest, src, destSize - 1); // Copy up to destSize - 1 characters from src to dest
        dest[destSize - 1] = '\0'; // Append a null terminator

        pthread_mutex_unlock(&mutex); // Unlock the mutex after operations are done
        return (int)strlen(dest); // Return the number of characters copied including the null terminator
    } else {
        strcpy(dest, src); // Copy the entire source string into dest if it fits within destSize

        pthread_mutex_unlock(&mutex); // Unlock the mutex after operations are done
        return (int)strlen(src); // Return the length of the copied string
    }
}
