```python
import pandas as pd
import boto3
from botocore.exceptions import NoCredentialsError
import threading
import logging

# Create an S3 client
s3 = boto3.client('s3')
bucket_name = 'my-bucket'  # replace with your bucket name

lock = threading.Lock()
logging.basicConfig(filename="logfile", level=logging.ERROR)

def read_data(csv_file):
    try:
        df = pd.read_csv(csv_file)
        return df['temperature']  # replace 'temperature' with your actual column name in csv file
    except Exception as e:
        logging.error("Error reading CSV file {}: {}".format(csv_file, str(e)))
        return None

def calculate_rolling_avg(data, window):
    try:
        return data.rolling(window=window).mean()
    except Exception as e:
        logging.error("Error calculating rolling average: {}".format(str(e)))
        return None

def upload_to_s3(filename, bucket_name, key):
    try:
        s3.upload_file(filename, bucket_name, key)
    except FileNotFoundError:
        logging.error("The file was not found")
        return False
    except NoCredentialsError:
        logging.error("Credentials not available")
        return False
    except Exception as e:
        logging.error("Something else went wrong: {}".format(str(e)))
        return False
    return True

def handle_upload(csv_file, window):
    data = read_data(csv_file)
    if data is not None:
        rolling_avg = calculate_rolling_avg(data, window)

        if rolling_avg is not None:
            lock.acquire()  # thread-safe uploading to prevent race conditions

            try:
                temp_file = "temp.csv"
                rolling_avg.to_csv(temp_file, index=False)
                if upload_to_s3(temp_file, bucket_name, 'output/' + csv_file):
                    print("Upload Successful")
            finally:
                lock.release()  # release the lock once done
```

In this implementation, you can handle concurrent uploads by using a threading Lock which ensures that only one thread can access a resource at any given time. If any errors occur during file reading or data processing, they are logged and handled gracefully without causing the program to crash. 

Please replace `'my-bucket'` with your actual bucket name in S3. The error logs will be written into a text file named "logfile". The rolling average is stored temporarily in a local CSV file before uploading it to S3, and after the calculation it gets deleted.

