Below is a Node.js program that accomplishes all of these tasks using built-in modules like fs and path:
```javascript
const fs = require('fs');
const path = require('path');
const promisify = require('util').promisify;

// Use promises for fs functions
const readdir = promisify(fs.readdir);
const stat = promisify(fs.stat);
const readFile = promisify(fs.readFile);

async function processDirectory(directoryPath) {
  const filesAndDirectories = await readdir(directoryPath);

  // Filter out hidden files/directories and files larger than 1MB
  const nonHiddenFiles = filesAndDirectories.filter((fileOrDir) =>
    !fileOrDir.startsWith('.') && stat(path.join(directoryPath, fileOrDir)).then((stats) => stats.size <= 1048576));

  // Array to store promises for each file content read
  const filePromises = [];

  nonHiddenFiles.forEach((fileName) => {
    const filePath = path.join(directoryPath, fileName);

    const promise = stat(filePath).then(() => readFile(filePath, 'utf8'))
      .catch((err) => console.warn('Error reading file:', err))
      .then((data) => ({ filename: fileName, content: data }));

    // Push promise to array for later Promise.all use 
    filePromises.push(promise);
  });

  return Promise.all(filePromises);
}
```
This function first reads the directory with `readdir`, filtering out files starting with a dot and those larger than 1MB in size. For each remaining (non-hidden, non-large) file, it attempts to read its content. If this fails, it logs a warning message but still resolves for other files. The function finally returns a promise that waits until all file contents are read and returned as an array of objects, where each object contains the filename and content of a file. This way, you can use this function to process large directories without running into memory issues or performance problems due to very large files.

