} ConfigSettings;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
json_t *cache = NULL;  // cache for configuration settings

void loadConfig(CURL *curl, const char* url, long timeout) {
    CURLcode res;

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);
    // more options as per your requirement ...

    res = curl_easy_perform(curl);  // perform the request

    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to load configuration: %s\n", curl_easy_strerror(res));
    } else {
        pthread_mutex_lock(&lock);  // lock for thread safety

        json_error_t error;
        cache = json_loadb(data, strlen(data), 0, &error);  // store the data in cache after parsing
        if(!cache) {
            fprintf(stderr, "Failed to parse configuration: %s\n", error.text);
        }

        pthread_mutex_unlock(&lock);  // unlock once done
    }

    curl_easy_reset(curl);  // reset the curl handle for next requests
}

// this function will be called from another module or thread
void *loadConfigAsync(void *config) {
    CURL *curl = curl_easy_init();
    if (curl) {
        ConfigSettings *settings = config;

        // validate settings and handle potential errors ...

        loadConfig(curl, settings->base_url, settings->timeout);  // perform request
        curl_easy_cleanup(curl);  // cleanup curl handle
    } else {
        fprintf(stderr, "Failed to initialize CURL\n");
    }
}
