Here's an example of how you might write such a function in Rust, using a library named `rustc_errors` for error reporting and management:

```rust
use std::process::{Command, Stdio};
use std::time::Instant;
use std::sync::Arc;
use rustc_errors::ErrorReport;
use sync_lazy::SyncLazy;

pub fn compile(source_file: &str) -> Result<(), ErrorReport> {
    let start = Instant::now();

    // Check if the source file exists.
    std::fs::File::open(&source_file).map_err(|e| ErrorReport::new(format_error, e))?;

    // Spawn a new process to compile the source file.
    let mut command = Command::new("rustc")
        .arg(source_file)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    // Start the compilation.
    let process = match command.spawn() {
        Ok(process) => process,
        Err(e) => return Err(ErrorReport::new(format_error, e)),
    };

    let stdout = match process.stdout {
        Some(mut stdout) => {
            let stdout = String::from_utf8(stdout.read_to_end().map_err(|e| ErrorReport::new(format_error, e))?).unwrap();
            println::<&str>(&stdout);
            stdout
        },
        None => "".into(),
    };

    // Wait for the process to finish.
    let status = match process.wait() {
        Ok(status) => status,
        Err(e) => return Err(ErrorReport::new(format_error, e)),
    };

    println::<&str>(&format_report(source_file, start));

    // If the process exited successfully, return Ok. Otherwise, return an error code.
    if status.success() {
        Ok(())
    } else {
        Err(ErrorReport::new(compile_error, (stdout, source_file)))
    }
}
```
