```python
import json
from collections import defaultdict
from abc import ABC, abstractmethod
import concurrent.futures

class JsonObject(ABC):
    factory_registry = defaultdict(lambda: None)

    @abstractmethod
    def parse_json(self, json_str: str):
        pass

    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    def add_factory(cls, id, factory):
        cls.factory_registry[id] = factory

    @classmethod
    def remove_factory(cls, id):
        if id in cls.factory_registry:
            del cls.factory_registry[id]

    @classmethod
    def create_instance(cls, json_str: str, id: str) -> 'JsonObject':
        factory = cls.factory_registry[id]
        if not factory:
            raise Exception('No factory function registered for this ID')
        return factory(json_str)

class NestedJsonObject(JsonObject):
    def __init__(self, json_obj=None):
        self._data = {}
        if json_obj is not None:
            self.parse_json(json_obj)

    def parse_json(self, json_str: str):
        try:
            # Here you can do validation and parsing of JSON
            self._data = json.loads(json_str)
        except Exception as e:
            raise ValueError('Invalid JSON data') from e

    def to_json(self) -> str:
        return json.dumps(self._data)

# Now, you can add factories for different IDs and create instances of the class with those IDs
NestedJsonObject.add_factory('nested', NestedJsonObject)
