#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <stdarg.h>

/* External API for logging system */
typedef enum LogLevel {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;
void logMessage(const char *message, LogLevel level);

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
#define BUFFER_SIZE 256
char buffer[BUFFER_SIZE];

/* Custom log condition function */
void logCondition(int condition, const char *format, ...) {
    va_list args;
    int len;

    if(!condition){
        return;
    }

    pthread_mutex_lock(&mutex); // Lock for thread safety

    /* Format the string */
    va_start(args, format);
    len = vsnprintf(buffer, BUFFER_SIZE, format, args);
    va_end(args);

    if (len >= BUFFER_SIZE) {
        logMessage("logCondition: buffer overflow", LOG_ERROR);
    } else {
        /* Log the message */
        try {
            logMessage(buffer, LOG_DEBUG); // Assuming debug level for condition logging
        } catch (...) {
            logMessage("logCondition: error while logging", LOG_ERROR);
        }
    }

    pthread_mutex_unlock(&mutex); // Unlock for thread safety
}
```
This implementation uses a mutex to ensure thread-safety, avoiding race conditions that could occur during concurrent calls. The function formats the input string with `vsnprintf` and checks if it fits within the buffer size limit. If any errors or overflow happens, appropriate error messages are logged using the external logging system's API. 

