```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using Microsoft.Extensions.Logging;

public class SecureMessageProcessor
{
    private readonly ConcurrentDictionary<string, string> _decryptedCache = new ConcurrentDictionary<string, string>();
    private readonly ILogger<SecureMessageProcessor> _logger; // Assumes you have a logger injected into this class

    public SecureMessageProcessor(ILogger<SecureMessageProcessor> logger)
    {
        _logger = logger;
    }

    public string DecryptMessage(string encodedMessage, byte[] key, byte[] iv)
    {
        if (encodedMessage == null || key == null || iv == null)
            throw new ArgumentNullException();

        try
        {
            string cacheKey = $"{Convert.ToBase64String(key)}_{Convert.ToBase64String(iv)}";

            // Check if the message is already in cache
            if (_decryptedCache.TryGetValue(cacheKey, out var decryptedMessage))
                return decryptedMessage;

            // Your actual decryption implementation here using Triple DES encryption
            byte[] cipherBytes = Convert.FromBase64String(encodedMessage);

            using (TripleDES tripleDes = TripleDES.Create())
            {
                ICryptoTransform transform = tripleDes.CreateDecryptor(key, iv);
                byte[] decryptedBytes = transform.TransformFinalBlock(cipherBytes, 0, cipherBytes.Length);

                decryptedMessage = System.Text.Encoding.UTF8.GetString(decryptedBytes);
            }

            _decryptedCache[cacheKey] = decryptedMessage; // Store the decrypted message in cache

            return decryptedMessage;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while decrypting a message.");
            throw;
        }
    }

    public byte[] EncryptMessage(string message, byte[] key, byte[] iv)
    {
        // Your actual encryption implementation here using Triple DES encryption
        byte[] encryptedBytes;

        using (TripleDES tripleDes = TripleDES.Create())
        {
            ICryptoTransform transform = tripleDes.CreateEncryptor(key, iv);
            byte[] messageBytes = System.Text.Encoding.UTF8.GetBytes(message);

            encryptedBytes = transform.TransformFinalBlock(messageBytes, 0, messageBytes.Length);
        }

        return encryptedBytes;
    }
}
```
