import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.*;

@Service
public class EvolutionDataFetcher {
    private static final String POKEMON_API = "http://pokeapi.co/api/v2/pokemon";
    private static final String EVOLUTION_CHAIN_API = "http://pokeapi.co/api/v2/evolution-chain";

    @Autowired
    RestTemplate restTemplate;

    // The cache for storing Pokemon and Evolution Chain data
    private net.sf.ehcache.CacheManager cacheManager = CacheManagerBuilder.newCacheManagerBuilder().build();
    private Cache<String, Object> pokemonCache = cacheManager.getCache("pokemon", String.class, Object.class);
    private Cache<String, Object> evolutionChainCache = cacheManager.getCache("evolution-chain", String.class, Object.class);

    // Function to fetch a single Pokemon's data
    public synchronized Pokemon getPokemonData(String pokemonName) {
        Pokemon cachedPokemon = pokemonCache.get(pokemonName);
        if (cachedPokemon != null) {
            return cachedPokemon;
        } else {
            ResponseEntity<Pokemon> response =  restTemplate.exchange(POKEMON_API + "/" + pokemonName, HttpMethod.GET, null, new ParameterizedTypeReference<>(){});

            if (response.getStatusCodeValue() != 200) {
                throw new RuntimeException("Error while fetching Pokemon data: " + response.getStatusCode());
            }

            pokemonCache.put(pokemonName, response.getBody());
            return response.getBody();
        }
    }

    // Function to fetch a single Evolution Chain's data
    public synchronized EvolutionChain getEvolutionData(String evolutionId) {
        EvolutionChain cachedEvolution = evolutionChainCache.get(evolutionId);
        if (cachedEvolution != null) {
            return cachedEvolution;
        } else {
            ResponseEntity<EvolutionChain> response =  restTemplate.exchange(EVOLUTION_CHAIN_API + "/" + evolutionId, HttpMethod.GET, null, new ParameterizedTypeReference<>(){});

            if (response.getStatusCodeValue() != 200) {
                throw new RuntimeException("Error while fetching Evolution Chain data: " + response.getStatusCode());
            }

            evolutionChainCache.put(evolutionId, response.getBody());
            return response.getBody();
        }
    }

}
```
