import java.sql.*;

public class UpdateClinicStatusFetcher {
    private static final int RATE_LIMIT = 5; // requests per minute 
    private ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    public void fetchAndUpdateClinicStatus(int clinic_id, String new_status, String last_modified_ip, Map<String, String> environment_variables) throws Exception {
        // Check if request should be allowed based on rate limiting logic
        Bucket bucket = buckets.computeIfAbsent(last_modified_ip, k -> new Bucket());
        boolean isAllowed = bucket.tryConsume();
        if (!isAllowed) {
            throw new Exception("Request limit exceeded for this IP");
        }

        // Verify clinic details via external API call
        ClassProvider provider = new ClassProvider();
        String verifiedClinicDetails = provider.verifyClinic(clinic_id);

        if (verifiedClinicDetails == null) {
            throw new Exception("Invalid or missing clinic details");
        }

        // Update clinic status in database
        String url = environment_variables.getOrDefault("DB_URL", "jdbc:mysql://localhost:3306/testdb");
        Connection conn = DriverManager.getConnection(url, "username", "password");
        PreparedStatement stmt = conn.prepareStatement("UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=? WHERE id=?");

        stmt.setString(1, new_status);
        stmt.setString(2, last_modified_ip);
        stmt.setTimestamp(3, Timestamp.from(Instant.now()));
        stmt.setInt(4, clinic_id);

        int rowsUpdated = stmt.executeUpdate();
        if (rowsUpdated == 0) {
            throw new Exception("No clinics updated");
        }
    }
}
