Bucket class implementation:

```java
import java.util.concurrent.atomic.AtomicInteger;

public class Bucket {
    private final int capacity;
    private final long timePeriodMillis; // in milliseconds 

    private AtomicInteger tokens;
    private volatile long lastUpdateTimeStamp;

    public Bucket() {
        this.capacity = RATE_LIMIT;
        this.timePeriodMillis = 60 * 1000; // one minute in milliseconds 

        this.tokens = new AtomicInteger(capacity);
        this.lastUpdateTimeStamp = System.currentTimeMillis();
    }

    public boolean tryConsume() {
        synchronized (this) {
            refillTokens();
            if (tokens.get() > 0) {
                tokens.decrementAndGet();
                return true;
            } else {
                return false;
            }
        }
    }

    private void refillTokens() {
        long now = System.currentTimeMillis();

        if (now > lastUpdateTimeStamp) {
            long elapsedTime = now - lastUpdateTimeStamp; 
            int tokensToAdd = (int)(elapsedTime / timePeriodMillis);

            tokens.updateAndGet(currentTokens -> Math.min(capacity, currentTokens + tokensToAdd));
            lastUpdateTimeStamp += tokensToAdd * timePeriodMillis;
        }
    }
}
```

