import axios from 'axios';
import { DateTime } from 'luxon'

const API_KEY = "Your API Key";  // Get your key from OpenWeatherMap.org
const BASE_URL = 'http://api.openweathermap.org/data/2.5/';
let cache = {};

async function getCurrentWeather(city) {
    let url = `${BASE_URL}weather?q=${city}&appid=${API_KEY}`;
    if (cache[url]) return cache[url];  // Return cached data if available

    for (let attempt=0; attempt<3; attempt++) {  // Retry up to 3 times
        try {
            let response = await axios.get(url);
            console.log(`Fetched weather data for ${city} at ${DateTime.local()}`);

            cache[url] = response;  // Cache the data
            return response;
        } catch (error) {
            console.warn(`Failed to fetch weather data for ${city}. Retrying...`, error);
        }
    }
    throw new Error(`Failed to fetch weather data for ${city} after 3 attempts.`);
}

export async function getWeatherDataForCities(cities) {
    let data = {};
    for (let city of cities) {
        data[city] = await getCurrentWeather(city);
    }
    return data;
}
