public class IoTDeviceDataParser
{
    private readonly IMongoDatabase _mongoDb;
    public IoTDeviceDataParser(string mongoConnectionString, string dbName)
    {
        var client = new MongoClient(mongoConnectionString);
        _mongoDb = client.GetDatabase(dbName);
    }

    public void ParseXmlAndSaveToMongoDB(XPathNavigator xmlData)
    {
        try
        {
            var xpathIterator = xmlData.Select("/Devices/Device");

            while (xpathIterator.MoveNext())
            {
                var deviceNode = xpathIterator.Current;

                var deviceId = deviceNode.GetAttribute("id", "");
                if(string.IsNullOrEmpty(deviceId))
                    throw new ApplicationException("Invalid XML data - missing id attribute in Device node.");

                var sensorReading = deviceNode.GetAttribute("sensor-reading", "");

                // Save to MongoDB
                var collection = _mongoDb.GetCollection<BsonDocument>("deviceData");
                var document = new BsonDocument { 
                    {"DeviceId", deviceId},
                    {"SensorReading", sensorReading}
                };
                collection.InsertOne(document);
            }
        }
        catch (MongoConnectionException ex)
        {
            // Retry logic here, or fallback to some other storage mechanism
            throw new ApplicationException("Failed to connect to MongoDB.", ex);
        }
        catch (XPathException ex)
        {
            throw new ApplicationException("Failed to parse XML data.", ex);
        }
    }
}
```

