import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.model.PutObjectRequest;

public class S3Service implements CloudStorageService {
    private AmazonS3 s3Client;

    public S3Service(AmazonS3 s3Client) {
        this.s3Client = s3Client;
    }

    @Override
    public boolean uploadFile(String filePath, String bucketName, String directoryPath, Map<String, String> optionalConfig) {
        try {
            File file = new File(filePath);
            PutObjectRequest request = new PutObjectRequest(bucketName, directoryPath + "/" + file.getName(), file);
            this.s3Client.putObject(request);
            return true;
        } catch (Exception e) {
            System.out.println("Failed to upload file: " + e.getMessage());
            return false;
        }
    }

    @Override
    public void validateMetadata(String filePath) {
        try {
            Path path = Paths.get(filePath);
            BasicFileAttributes attr = Files.readAttributes(path, BasicFileAttributes.class);
            System.out.println("Size: " + attr.size() + ", Created Time: " + attr.creationTime());
        } catch (IOException e) {
            System.err.println("Validation failed due to error: " + e);
        }
    }
}
