```php
<?php
class Record {
    public $id;
    public $offset_avg;
    public $key_avg;
}

function calculateAverage($data) {
    $sum = array_sum($data);
    $count = count($data);

    if ($count == 0) {
        throw new Exception('Cannot divide by zero');
    }

    return $sum / $count;
}

function readFileAndCalculateAverages($filePath) {
    // Open the file in read-only mode
    $handle = fopen($filePath, 'r') or die('Error opening file');

    $records = [];

    while (($line = fgets($handle)) !== false) {
        $recordData = explode(',', $line);

        // You should add some error handling here to ensure your line has the correct format

        $id = $recordData[0];
        $offsets = array_map('intval', explode(':', $recordData[1]));
        $keys = array_map('floatval', explode(':', $recordData[2]));

        $record = new Record();
        $record->id = $id;
        $record->offset_avg = calculateAverage($offsets);
        $record->key_avg = calculateAverage($keys);

        $records[] = $record;
    }

    fclose($handle);

    return $records;
}

function secureHashPassword($password, $rounds = 10) {
    $hash = password_hash($password, PASSWORD_BCRYPT, ['cost' => $rounds]);

    if ($hash === false) {
        throw new Exception('hashing failed');
    }

    return $hash;
}
```

