// Function to calculate SHA256 hash of a file
std::string calculate_file_sha256(const std::string& filename) {
    unsigned char c[SHA256_DIGEST_LENGTH];
    SHA256_CTX mdContext;
    SHA256_Init(&mdContext);

    std::ifstream ifs(filename, std::ios::binary);

    char buf[4096];
    while (ifs.good()) {
        ifs.read(buf, sizeof(buf));
        SHA256_Update(&mdContext, buf, ifs.gcount());
    }

    unsigned int mdLength = SHA256_DIGEST_LENGTH;
    unsigned char* md = new unsigned char[mdLength];
    SHA256_Final(md, &mdContext);

    std::stringstream ss;
    for(unsigned int i = 0; i < mdLength; i++) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int) md[i];
    }

    delete[] md;
    return ss.str();
}

// Example of a possible implementation for uploadAndDecryptFile function, without handling the thread safety and error management:
std::string uploadAndDecryptFile(const std::string& filename, const std::string& bucketName, 
                                AWSCredentials credentials = {}) {
    if(!std::filesystem::exists(filename) || !std::filesystem::is_regular_file(filename)) {
        throw std::runtime_error("File does not exist or is not a regular file");
    }

    // Calculate SHA256 hash of the file in another thread, to prevent blocking.
    auto shaFuture = std::async(std::launch::async, calculate_file_sha256, filename);

    if (credentials.service == "aws") {
        Aws::S3::S3Client s3Client; // Initialize S3 client using AWS SDK
        Aws::S3::Model::PutObjectRequest request;
        request.WithBucket(bucketName).WithKey("my-file");

        auto outcome = s3Client.PutObject(request);

        if(!outcome.IsSuccess()) {
            throw std::runtime_error(outcome.GetError().GetMessage());
        }
    } else if (credentials.service == "gcs") {
        google::cloud::StatusOr<google::cloud::storage::Client> client = 
                        google::cloud::storage::Client::CreateDefaultClient();

        auto metadata = client->UploadFile(filename, bucketName);
    } else {
        throw std::runtime_error("Unsupported cloud storage service");
    }

    return shaFuture.get(); // Wait for the SHA256 calculation to finish and return result.
}
