#include <stdarg.h>
#include <string.h>
#include "mylib.h"

char* append_slash(const char *str, size_t limit) {
    if (strlen(str) <= limit) {
        int len = strlen(str);
        char *new_str = malloc((len + 2)*sizeof(char));
        if (new_str != NULL) {
            strcpy(new_str, str);
            new_str[len] = '/';
            new_str[len+1] = '\0';
        }
        return new_str;
    }
    else {
        return NULL;
    }
}

void log_message(int condition_met, const char *format, ...) {
    if (condition_met == 0) {  // assuming 0 is for FALSE
        va_list argp;
        FILE *fp = fopen("/path/to/log", "a");  // open log file in append mode
        if(fp != NULL) {
            va_start(argp, format);
            vfprintf(fp, format, argp);
            va_end(argp);
            fclose(fp);
        }
    }
}
