using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Net.Http;
using System.Net.FtpClient;
using Microsoft.Extensions.Caching.Memory;

public interface IFileHasher {
    string Hash(string path, CancellationToken token);
}

public class MD5FileHasher : IFileHasher {
    public string Hash(string path, CancellationToken token) {
        using var hasher = IncrementalHash.CreateHash(HashAlgorithmName.MD5);
        const int bufferSize = 4096; // Read in chunks of 4KB
        byte[] buffer = new byte[bufferSize];

        using FileStream fs = File.OpenRead(path);
        Span<byte> bufferSpan = buffer;

        while (fs.Read(buffer) > 0 && !token.IsCancellationRequested) {
            hasher.AppendData(bufferSpan);
        }

        return Convert.ToHexString(hasher.GetHashAndReset());
    }
}

public class FTPFileHandler : IDisposable {
    private readonly FtpClient _client;

    public FTPFileHandler(string server, string username, string password) {
        _client = new FtpClient(server, username, password);
    }

    public Stream OpenRead(string path) {
        return _client.OpenRead(path);
    }

    // Implement IDisposable pattern to clean up resources.
}

public class FileHashService {
    private readonly IFileHasher _hasher;
    private readonly MemoryCache _cache;
    private readonly HttpClient _httpClient;

    public FileHashService(IFileHasher hasher, HttpClient httpClient) {
        _hasher = hasher ?? throw new ArgumentNullException(nameof(hasher));
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));

        // Configure cache options.
    }

    public async Task<bool> VerifyHash(string hash) {
        if (_cache.TryGetValue(hash, out bool isVerified)) {
            return isVerified;
        }

        var response = await _httpClient.PostAsync("api/verify", new StringContent(hash));
        isVerified = response.IsSuccessStatusCode; // Assuming HTTP 200 means verified.

        if (isVerified) {
            // Store hash in cache for 1 hour.
            _cache.Set(hash, isVerified, new MemoryCacheEntryOptions().SetAbsoluteExpiration(TimeSpan.FromHours(1)));
        }

        return isVerified;
    }
}
```
