Create a file called 'modularity.js':
```javascript
const fs = require('fs').promises;

class Modularity {
  constructor() {
    this.modules = {};
  }

  async loadModule(fileName) {
    try {
      const moduleCode = await fs.readFile(fileName, 'utf-8');

      let exports = {};
      // We use a Function constructor to create a new scope for each module
      const mod = new Function('exports', 'require', 'module', moduleCode);
      mod.call(exports, exports, require, { exports });

      this.modules[fileName] = exports;
    } catch (err) {
      console.error(`Failed to load module ${fileName}. Error: ${err}`);
    }
  }

  async loadModules(moduleNames) {
    for (let fileName of moduleNames) {
      await this.loadModule(fileName);
    }
  }

  getLoadedModules() {
    return this.modules;
  }
}

module.exports = Modularity;
```
This solution assumes that each JavaScript file in the moduleNames list exports a function called `execute` which is invoked after the module has loaded successfully.

Create another file, 'executor.js':
```javascript
const Modularity = require('./modularity');

async function executeModules(moduleNames) {
  const modHandler = new Modularity();

  await modHandler.loadModules(moduleNames);

  const modules = modHandler.getLoadedModules();

  for (let moduleName in modules) {
    try {
      if (!modules[moduleName].execute) {
        throw new Error('Module does not export an execute function');
      }

      await modules[moduleName].execute();
    } catch (err) {
      console.error(`Failed to execute module ${moduleName}. Error: ${err}`);
    }
  }
}

executeModules(['./path/to/your/modules']);
```
This code will load and execute each JavaScript file in the `moduleNames` array. It uses a try-catch block to handle any errors that might occur during module loading or execution. If a loaded module doesn't export an 'execute' function, it logs an error message.

