public:
  // Function to calculate SHA-256 hash of file
  static std::string calculate_file_sha256(const std::string& filename) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filename, std::ios::binary);
    constexpr size_t bufferSize = 32768;
    char* buffer = new char[bufferSize];

    while (file.good()) {
      file.read(buffer, bufferSize);
      SHA256_Update(&sha256, buffer, file.gcount());
    }

    delete[] buffer;
    unsigned int hashLength = SHA256_DIGEST_LENGTH;
    char* outputBuffer = new char[hashLength*2 + 1];
    SHA256_Final(reinterpret_cast<unsigned char*>(outputBuffer), &sha256);

    std::string output = toHexString(outputBuffer, hashLength);
    delete[] outputBuffer;
    return output;
  }

  // Function to upload file to cloud storage
