#include <openssl/evp.h>
#include <stdio.h>

typedef struct {
  const char* name;
} HashFunctionData;

HashFunctionData* getAvailableHashFunctions() {
    OpenSSL_add_all_digests();
    int numberOfDigests = EVP_get_digestnum();

    // Dynamically allocate memory for the array of pointers to structs 
    HashFunctionData* availableHashes = malloc(numberOfDigests * sizeof(HashFunctionData));

    int count = 0;
    for (int i = 0; i < numberOfDigests; ++i) {
      const EVP_MD *md = EVP_get_digestbynum(i);

      // Check if this digest is available 
      if (!EVP_get_digestbyname(md->name)) continue;

      availableHashes[count].name = md->name;
      ++count;
    }

    return availableHashes;
}
