using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class SecureEncryptionManager
{
    private static readonly ThreadLocal<Aes> aes = new ThreadLocal<Aes>(() => Aes.Create());

    // Simplified key management service integration, replace it with your own implementation
    private static byte[] GetKey()
    {
        return Encoding.UTF8.GetBytes("YourKeyHere");
    }

    public static byte[] DecryptAESCBC(byte[] cipherText, byte[] iv = null)
    {
        if (cipherText == null || cipherText.Length <= 0)
            throw new CryptographicException("Invalid ciphertext.");

        using var aesAlg = Aes.Create();
        aesAlg.Mode = CipherMode.CBC; // Set the mode to CBC

        if (iv == null)
        {
            aesAlg.GenerateIV();
        } 
        else 
        {
            if (iv.Length != aesAlg.BlockSize / 8)
                throw new CryptographicException("Invalid IV length.");

            aesAlg.IV = iv;
        }

        // Use your own implementation of key retrieval and rotation
        var keyBytes = GetKey();
        aesAlg.Key = keyBytes;

        var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
        return TransformFinalBlock(decryptor, cipherText);
    }

    public static byte[] DecryptAESGCM(byte[] cipherText, byte[] iv = null)
    {
        if (cipherText == null || cipherText.Length <= 0)
            throw new CryptographicException("Invalid ciphertext.");

        using var aesAlg = Aes.Create();
        aesAlg.Mode = CipherMode.GCM; // Set the mode to GCM

        if (iv == null)
        {
            aesAlg.GenerateIV();
        } 
        else 
        {
            if (iv.Length != aesAlg.BlockSize / 8)
                throw new CryptographicException("Invalid IV length.");

            aesAlg.IV = iv;
        }

        // Use your own implementation of key retrieval and rotation
        var keyBytes = GetKey();
        aesAlg.Key = keyBytes;

        var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
        return TransformFinalBlock(decryptor, cipherText);
    }

    private static byte[] TransformFinalBlock(ICryptoTransform transform, byte[] inputBuffer)
    {
        var outputBytes = transform.TransformFinalBlock(inputBuffer, 0, inputBuffer.Length);
        return outputBytes;
    }
}
