import java.util.concurrent.*;
import java.util.logging.*;

public class DisjointPairCounter {
    private Connection dbConnection;
    private File loggingFile;
    private int removeThreshold = 0; // Default threshold to not remove duplicates.

    public DisjointPairCounter(String databaseUrl, String username, String password) throws SQLException {
        this.dbConnection = DriverManager.getConnection(databaseUrl, username, password);
    }

    public void setLoggingFilePath(String path) {
        this.loggingFile = new File(path);
    }

    public void setRemoveThreshold(int threshold) {
        this.removeThreshold = threshold;
    }

    public int countDisjointPairs(int[] array, boolean removeDuplicates) throws SQLException {
        if (removeDuplicates && array.length > removeThreshold) {
            Map<Integer, Integer> frequencyMap = new HashMap<>();
            for (int num : array) {
                frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
            }
            List<Integer> uniqueArray = new ArrayList<>();
            for (int num : array) {
                if (frequencyMap.get(num) < removeThreshold) {
                    uniqueArray.add(num);
                }
            }
            return countDisjointPairsFromDBOrCompute(uniqueArray);
        } else {
            return countDisjointPairsFromDBOrCompute(Arrays.stream(array).boxed().toArray(Integer[]::new));
        }
    }

    private synchronized int countDisjointPairsFromDBOrCompute(Object array) throws SQLException {
        String hash = Arrays.deepToString(new Object[]{array}); // Simplified hashing, replace with a strong one in production.
        try (PreparedStatement stmt = dbConnection.prepareStatement("SELECT COUNT FROM PairCounts WHERE HASH=?")) {
            stmt.setString(1, hash);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                return rs.getInt(1); // Already computed and stored in DB.
            } else {
                int count = computeDisjointPairs((int[]) array);
                try (PreparedStatement insertStmt = dbConnection.prepareStatement("INSERT INTO PairCounts VALUES (?, ?)")) {
                    insertStmt.setString(1, hash);
                    insertStmt.setInt(2, count);
                    insertStmt.executeUpdate();
                } catch (SQLException e) {
                    Logger.getAnonymousLogger().log(Level.WARNING, "Could not store in DB", e);
                }
                return count;
            }
        }
    }

    private int computeDisjointPairs(int[] array) {
