using UnityEngine;
using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Linq;

public enum DistributionType
{
    Gaussian,
    Uniform,
}

public class DynamicValueGenerator
{
    private static readonly ConcurrentDictionary<DistributionType, SemaphoreSlim> _semaphores = new ConcurrentDictionary<DistributionType, SemaphoreSlim>();

    private float _min;
    private float _max;
    private DistributionType _distributionType;

    public DynamicValueGenerator(float min, float max, DistributionType distributionType)
    {
        if (min >= max) throw new ArgumentException("Min should be less than Max");

        _min = min;
        _max = max;
        _distributionType = distributionType;

        if (!_semaphores.ContainsKey(distributionType))
            _semaphores[distributionType] = new SemaphoreSlim(1, 1);
    }

    public float GenerateFloat()
    {
        _semaphores[_distributionType].Wait();

        try
        {
            switch (_distributionType)
            {
                case DistributionType.Gaussian:
                    return GaussianRandom(_min, _max);

                case DistributionType.Uniform:
                    return UnityEngine.Random.Range(_min, _max);

                default:
                    throw new ArgumentException("Invalid distribution type");
            }
        }
        finally
        {
            _semaphores[_distributionType].Release();
        }
    }

    private float GaussianRandom(float min, float max) 
    {
        // Implementation of Gaussian random
    }

    public override string ToString()
    {
        return $"Range: [{_min}, {_max}], Distribution Type: {_distributionType}";
    }
}
