```C#
using System;
using System.Text;
using System.Security.Cryptography;
using Microsoft.Extensions.Logging;

public interface IDecryptionService
{
    string Decrypt(string encryptedMessage, string key, byte[] iv, string hmacHash);
}

public class TripleDESDecryptionService : IDecryptionService
{
    private readonly ILogger<TripleDESDecryptionService> _logger;

    public TripleDESDecryptionService(ILogger<TripleDESDecryptionService> logger)
    {
        _logger = logger;
    }

    public string Decrypt(string encryptedMessage, string key, byte[] iv, string hmacHash)
    {
        try
        {
            var cipherTextBytes = Convert.FromBase64String(encryptedMessage);

            using (var tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = Encoding.UTF8.GetBytes(key);
                tripleDes.IV = iv;

                var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);
                using (var memoryStream = new MemoryStream(cipherTextBytes))
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                    {
                        var plainTextBytes = new byte[cipherTextBytes.Length];
                        var decryptedByteCount = cryptoStream.Read(plainTextBytes, 0, plainTextBytes.Length);

                        if (decryptedByteCount < plainTextBytes.Length)
                            Array.Resize(ref plainTextBytes, decryptedByteCount);

                        using (var hmac = new HMACSHA256(tripleDes.Key))
                        {
                            var hashToCheck = Convert.ToBase64String(hmac.ComputeHash(plainTextBytes));

                            if (!string.Equals(hashToCheck, hmacHash, StringComparison.OrdinalIgnoreCase))
                                throw new CryptographicException("Integrity check failed.");
                        }

                        var plaintext = Encoding.UTF8.GetString(plainTextBytes);

                        _logger.LogInformation("Successfully decrypted message.");

                        return plaintext;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed.");

            throw new CryptographicException("Failed to decrypt the message.", ex);
        }
    }
}
