    private byte[] createChecksum(String filename, long startPos, long endPos) throws Exception {
        try (FileInputStream fis = new FileInputStream(filename)) {
            fis.skip(startPos);

            byte[] chunk = new byte[CHUNK_SIZE];
            int bytesRead;

            while ((bytesRead = fis.read(chunk, 0, CHUNK_SIZE)) != -1 && startPos < endPos) {
                sha256.update(chunk, 0, bytesRead);
                startPos += bytesRead;
            }

        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        return sha256.digest();
    }

