using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Security.Cryptography;

public class NetworkDataTransfer
{
    private static readonly HttpClient client = new HttpClient();

    // Dummy methods for compression, encryption and checksum calculation 
    public byte[] Compress(byte[] input) => throw new NotImplementedException();
    public byte[] Encrypt(byte[] input) => throw new NotImplementedException();
    public string CalculateChecksum(byte[] input) => throw new NotImplementedException();

    private async Task TransferAsync(byte[] data, Uri serverUri, int retryCount = 3)
    {
        try
        {
            var compressed = Compress(data);
            var encrypted = Encrypt(compressed);
            var checksum = CalculateChecksum(encrypted);

            // Logging here...

            var content = new ByteArrayContent(encrypted);
            using (var response = await client.PostAsync(serverUri, content))
            {
                if (!response.IsSuccessStatusCode) 
                    throw new Exception("HTTP request failed");

                // Logging here...

                var serverChecksum = await response.Content.ReadAsStringAsync();
                if (checksum != serverChecksum) 
                    throw new Exception("Data integrity check failed");
            }
        }
        catch (Exception ex)
        {
            // Logging here...

            if (retryCount > 0) await TransferAsync(data, serverUri, retryCount - 1);
            else throw;
        }
    }

    public void StartTransfer(byte[] data, Uri serverUri) => Task.Run(() => TransferAsync(data, serverUri));
}
