```c
#include <stdio.h>
#include <netdb.h>  // for gethostbyname
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>

// Limit the number of concurrent requests
#define MAX_CONCURRENT 10

typedef struct {
    char hostname[256];
    u_char ipaddr[4]; // IPv4 address
} ResolutionResult;

static pthread_mutex_t requestLock = PTHREAD_MUTEX_INITIALIZER;
static int activeRequests = 0;

void *resolveHostname(void *arg) {
    char hostname[256];
    strncpy(hostname, (char *) arg, 255);

    ResolutionResult *result = malloc(sizeof(ResolutionResult));
    if (!result) return NULL; // Error handling

    strcpy(result->hostname, hostname);

    struct hostent *he;
    struct in_addr **addr_list;
    int i;

    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname"); // Log error

        free(result);
        return NULL;
    }

    addr_list = (struct in_addr **) he->h_addr_list;

    for (i = 0; addr_list[i] != NULL; i++) {
      // Only taking the first IP address, if you want all the IPs then just print them one by one.
       strncpy((char *)&result->ipaddr, inet_ntoa(*addr_list[i]), 16);
    }

    pthread_mutex_lock(&requestLock);
    activeRequests--; // This request is done
    pthread_mutex_unlock(&requestLock);

    return (void *) result;
}

ResolutionResult *performDNSresolution(char *hostname) {
    if (!hostname) return NULL;

    ResolutionResult *result = NULL;
    pthread_t threadId;
    int status, errsv; // errno save

    pthread_mutex_lock(&requestLock);

    if (activeRequests >= MAX_CONCURRENT) {
        printf("Max concurrent requests reached\n");

        pthread_mutex_unlock(&requestLock);
        return NULL; // Exceeded limit. Can't do any more requests at this moment.
    } 

    activeRequests++;
    pthread_mutex_unlock(&requestLock);

    status = pthread_create(&threadId, NULL, resolveHostname, hostname);
    if (status != 0) { // Error handling
        errsv = errno; // Save errno 
        printf("Error creating thread: %s\n", strerror(errsv));

        pthread_mutex_lock(&requestLock);
        activeRequests--;
        pthread_mutex_unlock(&requestLock);

        return NULL;
    }

    status = pthread_join(threadId, (void **) &result);

    if (status != 0) { // Error handling 
        errsv = errno;
        printf("Error joining thread: %s\n", strerror(errsv));

        free(result);
        return NULL;
    }

    return result;
}
```

Note that this code is incomplete and doesn't handle caching or logging. Also, it uses a single mutex for all threads, which might be problematic if you need to run several DNS requests in parallel with the same hostname but different thread contexts. In that case, consider using a hash map where each key is the hostname, and the value is another structure that includes activeRequests count and an array of pthread_t for each resolution attempt; this would allow more flexibility for handling multiple threads resolving the same hostname. This also applies to caching and logging mechanisms as well.

