use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Config {
    max_retries: u32,
    retry_interval: Vec<u64>,
}

impl Config {
    fn new() -> Self {
        // In real scenario, this should read from a file or environment variable.
        let config = r#"{ "max_retries": 3, "retry_interval": [1, 2, 4] }"#;
        serde_json::from_str(config).unwrap()
    }
}

static CFG: Mutex<Config> = Mutex::new(Config::new());

async fn create_directory(name: &str) {
    let cfg = CFG.lock().unwrap();
    if env::var("MY_DIRECTORY").is_err() {
        for i in 0..cfg.max_retries {
            match create_dir(&PathBuf::from(name)) {
                Ok(_) => {
                    log::info("Directory {} created successfully", name);
                    std::env::set_var("MY_DIRECTORY", &*format![r#"{}"#, &*PathBuf::from(name)]);
                    break;
                }
                Err(e) => {
                    if i + 1 < cfg.max_retries {
                        log::error("Failed to create directory: {}", e);
                        delay_for(Duration::from_secs(cfg.retry_interval[i as usize])).await;
                    } else {
                        log::error("Failed after max retries: {}", e);
                    }
                }
            }
        }
    } else {
        log::info("Directory already exists");
    }
}
```
