} NFAPI_CRC_INDICATION_PDU_T;

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, FILE *logFile) {
    if (maxStructures > 1000 || maxStructures < 1) {
        fprintf(logFile, "Error: Invalid number of structures specified.\n");
        return -1;
    }

    srand((unsigned int) time(NULL));  // initialize random seed
    *crcList = malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crcList == NULL) {
        fprintf(logFile, "Error: Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < maxStructures; ++i) {
        (*crcList)[i].RX_UE_INFORMATION_TAG = rand();  // populate with random value, ensure uniqueness
    }

    *listSize = maxStructures;

    return 0;
}
