```rust
extern crate hyper;
use hyper::client::HttpConnector;
use hyper::header::Headers;
use std::sync::Arc;

pub struct RequestBuilder {
    client: Arc<hyper::Client<HttpConnector>>,
}

impl RequestBuilder {
    pub fn new(disable_certificate_verification: bool) -> Self {
        let https = match disable_certificate_verification {
            true => hyper::https::HttpsConnector::new(4).unwrap(),
            false => hyper::https::HttpsConnector::new(4).map_err(|e| println!).unwrap(),
        };

        let client = hyper::Client::builder()
            .build(https);

        Self {
            client: Arc::new(client),
        }
    }

    pub fn get(&self, url: &str) -> Result<hyper::Body, hyper::Error> {
        let res = self.client.get(url).send()?;
        Ok(res.into_body())
    }
}
```

