```javascript
const winston = require('winston');
const axios = require('axios').default;
const Bottleneck = require("bottleneck");

class Uploader {
    constructor(config) {
        this.config = config || {};
        this.service = null;
        this.limiter = new Bottleneck({
            maxConcurrent: 5,
            minTime: 6000 // Allow at most 10 uploads per minute
        });
    }

    async init() {
        if (this.config && this.config.service) {
            this.service = await import(this.config.service);
            return true;
        } else {
            throw new Error('Service configuration not found');
        }
    }

    async uploadFileFromUrl(url, params={}) {
        let success = false;

        // validate url
        if (!/https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{2,256}\.[a-z]{2,4}\b(\/[-a-zA-Z0-9@:%_\+.~#?&//=]*)?/g.test(url)) {
            throw new Error('Invalid URL');
        }

        // get file size and type before download
        const {data: fileSize, headers} = await axios.head(url);
        if (!headers || !fileSize) {
            throw new Error('Failed to fetch file info');
        }

        if (parseInt(fileSize['content-length']) > 100 * 1024 * 1024) {
            winston.error("File size is larger than the allowed maximum");
            return false;
        }

        const fileType = headers['content-type'];
        if (!this.service.isSupported(fileType)) {
            winston.error("Unsupported file type: " + fileType);
            return false;
        }

        for (let i = 0; i < 5; ++i) { // retry up to 5 times
            try {
                await this.limiter.schedule(() => {
                    const response = axios({
                        method: 'get',
                        url,
                        responseType: 'stream'
                    });

                    return new Promise((resolve, reject) => {
                        response.data.pipe(this.service.uploadStream).on('finish', resolve);

                        // handle any errors during the upload process
                        response.data.on('error', (err) => { 
                            winston.error("Upload error: " + err);
                            reject(err);
                        });
                    });
                });

                success = true;
                break; // exit retry loop on successful upload
            } catch (e) {
                winston.error("Retry failed: " + e);
                await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, i))); // exponential backoff
            }
        }

        if (!success) {
            throw new Error('Failed to upload file after multiple retries');
        }
    }
}
