```javascript
const fs = require('fs');
const path = require('path');
const readFilePromise = require('fs-readfile-promise');
const cloudStorageService = require('cloud-storage-service'); // replace with actual service

function asyncReadDirectory(directoryPath, extension=null, timeout) {
    return new Promise((resolve, reject) => {
        fs.readdir(directoryPath, (err, files) => {
            if (err) {
                reject(err);
            } else {
                let promises = [];

                files.forEach(fileName => {
                    // ignore hidden files and non-matching extension
                    if (fileName[0] === '.' || (extension && !fileName.endsWith(extension))) {
                        return;
                    }

                    const filePath = path.join(directoryPath, fileName);
                    const stat = fs.statSync(filePath);

                    // ignore files larger than 1MB
                    if (stat && stat.size > 1048576) {
                        console.warn('Ignoring ' + filePath + ', file size exceeds limit');
                        return;
                    }

                    promises.push(readFilePromise(filePath, timeout).then((content) => {
                            cloudStorageService.uploadFile(fileName, content);
                            return { filename: fileName, content };
                        })
                        .catch((error) => console.warn('Failed to read ' + filePath + ':', error)));
                });

                Promise.all(promises).then(resolve).catch(reject);
            }
        });
    });
}
```
This function takes in a directory path, an optional extension for filtering files, and a timeout value (in milliseconds) for each file read operation. It asynchronously reads the directory, lists all files and subdirectories within it, filters out hidden files and those that are larger than 1MB or do not match the provided extension if any, and then attempts to read their contents. Each file's content is uploaded to a cloud storage service after processing, and a promise resolving with an object containing the filename and its content is returned for each non-hidden file. If a file cannot be read within the specified timeout period, it triggers a warning message and continues processing other files.

