```c++
#include <iostream>
#include <fstream>
#include <thread>
#include <openssl/sha.h> // Library to calculate SHA-256 hash
#include "external_cloud_storage_api.h" // placeholder for external library or API

class FileUploader {
public:
    explicit FileUploader(std::string bucketName) : bucketName_(bucketName){}

    std::pair<bool, std::string> uploadAndMonitorFile(const std::string& filePath, 
            const std::vector<std::pair<std::string, std::string>>& metadata = {},
            int chunkSize = 1024*1024) {

        // Check if the file exists and is accessible
        std::ifstream file(filePath);
        if (!file.good()) {
          std::cout << "File does not exist or is inaccessible" << std::endl;
          return {false, "Error: File does not exist or is inaccessible."};
        }

        // Calculate file hash
        unsigned char result[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        std::string hexDigest = calculateHashFromFile(file, sha256, result, chunkSize);

        // Initialize cloud storage API and upload file
        externalCloudStorageAPI api;

        if (!api.uploadFileToBucket(bucketName_, filePath, metadata)) {
          std::cout << "Upload failed" << std::endl;
          return {false, "Error: Upload failed."};
        }

        // Monitor upload progress in a separate thread
        auto monitorThread = std::thread([&api, &filePath](){ api.monitorFileUpload(filePath); });
        monitorThread.detach();

        return {true, "Success: File uploaded successfully with hash " + hexDigest};
    }

private:
    std::string bucketName_;

    // Function to calculate SHA-256 hash of a file
    std::string calculateHashFromFile(std::ifstream& file, 
                                      SHA256_CTX& sha256, unsigned char result[], int chunkSize) {
        const auto buffer = new char[chunkSize];

        while (!file.eof()) {
            file.read(buffer, chunkSize);
            std::streamsize bytesRead = file.gcount();

            if (bytesRead > 0)
                SHA256_Update(&sha256, buffer, bytesRead);
        }

        SHA256_Final(result, &sha256);

        std::stringstream hexDigest;
        for(int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            hexDigest << std::hex << std::setw(2) << std::setfill('0') << (unsigned int)result[i];
        }

        delete[] buffer;

        return hexDigest.str();
    }
};
```
In the above code: 
- A class `FileUploader` is created that takes bucket name as a parameter in its constructor and has an upload function.
- It checks if file exists and if it does, then calculates SHA-256 hash of the file.
- An instance of external cloud storage API is initialized to upload file to specified bucket and monitoring is done in a separate thread.

