    int RNTI;
    struct CRC_INDICATION_REL8_TAG{
        int CRCFLAG;
    }CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
void *createAndPopulateList(int n, char* database) {
    pthread_mutex_lock(&lock); // Locking the mutex to ensure thread safety.
    if (n < 0 || n > MAX_SIZE) {
        printf("Invalid number of elements.\n");
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning from the function.
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (list == NULL) {
        printf("Failed to allocate memory for the list.\n");
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning from the function.
        return NULL;
    }
    FILE* file = fopen(database, "r");
    if (file == NULL) {
        printf("Failed to open database.\n");
        free(list);
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning from the function.
        return NULL;
    }
    int i = 0;
    while (i < n) {
        if (fscanf(file, "%d %d", &list[i].RX_UE_INFORMATION_TAG, &list[i].RNTI) != 2) {
            printf("Insufficient data in the database.\n");
            break;
        }
        if (list[i].CRC_INDICATION_REL8_TAG.CRCFLAG < 0 || list[i].CRC_INDICATION_REL8_TAG.CRCFLAG > 1) {
            printf("Invalid CRCFLAG value.\n");
            continue;
        } else {
            list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set the CRCFLAG to either 0 or 1.
        }
        i++;
    }
    fclose(file);
    pthread_mutex_unlock(&lock); // Unlock the mutex before returning from the function.
    return (void*) list;
}
