<?php
class PasswordManager {
    private $distributedStorage;
    private $saltGenerator;
    private $rateLimiter;
    private $hashingAlgorithm;

    public function __construct($distributedStorage, $saltGenerator, $rateLimiter, $hashingAlgorithm) {
        $this->distributedStorage = $distributedStorage;
        $this->saltGenerator = $saltGenerator;
        $this->rateLimiter = $rateLimiter;
        $this->hashingAlgorithm = $hashingAlgorithm;
    }

    public function createPassword($user, $password) {
        if (!$this->rateLimiter->isAllowed()) {
            throw new Exception("Rate limit exceeded");
        }

        $salt = $this->distributedStorage->getOrCreateSalt($user);
        $hashedPassword = password_hash($password . $salt, $this->hashingAlgorithm);
        $this->distributedStorage->saveHashedPassword($user, $hashedPassword);
    }

    public function validatePassword($user, $password) {
        if (!$this->rateLimiter->isAllowed()) {
            throw new Exception("Rate limit exceeded");
        }

        $salt = $this->distributedStorage->getOrCreateSalt($user);
        $hashedPassword = $this->distributedStorage->getHashedPassword($user);

        return password_verify($password . $salt, $hashedPassword);
    }
}
