// Load a module file and execute it
function loadModule(modulePath) {
    try {
        const code = fs.readFileSync(modulePath, 'utf8');
        // Create a context for the module to run in
        var sandbox = {
            console: console,
            require: require,
            module: {},
            exports: {}
        };

        vm.runInNewContext(code, sandbox);

        return sandbox.exports;
    } catch (e) {
