function resolveDependencies() {
  // Fetch package.json file for this project
  const pkg = require(path.join(process.cwd(), 'package.json'));

  // Resolve dependency paths
  const deps = Object.keys(pkg.dependencies || {});

  return deps;
}

// Load and execute modules in a specific order based on their dependencies
function loadAndExecuteModules() {
    try {
        let modulePaths = resolveDependencies();

        for (let path of modulePaths) {
            console.log(`Loading and executing the module at path ${path}...`);

            // Load and execute each module in order
            const exports = loadModule(path);

            console.log('Module loaded successfully', exports);
        }
    } catch (e) {
        console.error('An error occurred while loading modules:', e);
    }
}

// Start the process of loading and executing modules
