public:
    UnionFind(int n) : parent(n) {
        for (int i = 0 ; i < n ; i++) {
            parent[i] = i;
        }
    }

    void UnionSet(int a, int b) {
        a = findSet(a);
        b = findSet(b);
        if (a != b) {
            parent[b] = a;
        }
    }

    int findSet(int a) {
        return parent[a] == a ? a : (parent[a] = findSet(parent[a]));
    }
};
```
In the example above, Union-Find data structure is implemented. The `findSet` function checks if two elements are in same set or not and `UnionSet` merges them into one.

