using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SecurelyDecryptAndUpload
{
    private readonly Aes _aesAlgorithm = new AesManaged();
    private readonly Encoding _encoding = Encoding.UTF8;

    public void DecryptFile(string inputPath, string outputPath)
    {
        using (var reader = new StreamReader(inputPath))
        {
            var encryptedText = reader.ReadToEnd();
            byte[] cipherBytes = Convert.FromBase64String(encryptedText);

            _aesAlgorithm.IV = Encoding.UTF8.GetBytes(_encoding.GetString(cipherBytes, 0, _aesAlgorithm.BlockSize / 8));
            _aesAlgorithm.Key = _encoding.GetBytes("Your-AES-GCM-KEY"); // Please replace with your actual key

            using (var decryptor = _aesAlgorithm.CreateDecryptor(_aesAlgorithm.Key, _aesAlgorithm.IV))
            {
                string decryptedText;

                using (MemoryStream msDecrypt = new MemoryStream(cipherBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            decryptedText = srDecrypt.ReadToEnd();
                        }
                    }
                }

                Console.WriteLine("The decrypted text is: " + decryptedText);
            }
        }
    }

    public void EncryptFile(string inputPath, string outputPath)
    {
        using (var reader = new StreamReader(inputPath))
        {
            var plaintext = reader.ReadToEnd();

            _aesAlgorithm.GenerateIV();

            using (var encryptor = _aesAlgorithm.CreateEncryptor(_aesAlgorithm.Key, _aesAlgorithm.IV))
            {
                using (MemoryStream msEncrypt = new MemoryStream())
                {
                    using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        using (StreamWriter swEncrypt = new StreamWriter(csEncrypt))
                        {
                            swEncrypt.Write(plaintext);
                        }

                        byte[] encryptedBytes = msEncrypt.ToArray();
                        string cipherText = Convert.ToBase64String(encryptedBytes);

                        Console.WriteLine("The encrypted text is: " + cipherText);
                    }
                }
            }
        }
    }
}
```
