Here is an implementation of a C# class named `CustomRandomGenerator` which fulfills all your requirements:

```csharp
using System;
using System.Text;
using System.Threading;
using MathNet.Numerics.Distributions;

public class CustomRandomGenerator {
    private int _seed;
    private double _min, _max;
    private StringBuilder log = new StringBuilder();
    private ReaderWriterLockSlim lock_ = new ReaderWriterLockSlim();
    private ContinuousUniform uniformDistribution;

    public CustomRandomGenerator(double min = 0.0, double max = 1.0, int seed = 0) {
        SetRange(min, max);
        SetSeed(seed);
    }

    public void SetRange(double min, double max) {
        if (max <= min) throw new ArgumentException("Invalid range");
        _min = min; 
        _max = max;
        uniformDistribution = new ContinuousUniform(_min, _max);
    }

    public void SetSeed(int seed) {
        if (seed < 0) throw new ArgumentException("Invalid seed");
        _seed = seed;
        Random rnd = new Random(_seed);
    }

    public int GetSeed() => _seed;

    public double NextValue(){
        lock_.EnterWriteLock();
        try {
            var randomNumber = uniformDistribution.Sample();
            log.AppendLine($"Generated number: {randomNumber}");
            return randomNumber;
        } finally {
            lock_.ExitWriteLock();
        }
    }

    public double[] NextValues(int count) {
        var values = new double[count];
        for (var i = 0; i < count; ++i)
            values[i] = NextValue();
        return values;
    }

    public void Reset() {
        lock_.EnterWriteLock();
        try {
            SetRange(_min, _max);
            log.Clear();
        } finally {
            lock_.ExitWriteLock();
        }
    }

    public override string ToString(){
        return $"Seed: {_seed}, Range: [{_min}, {_max}], Log: {log}";
    }
}
```
This class uses `MathNet.Numerics` library for generating random values based on a normal distribution. It also uses a `ReaderWriterLockSlim` to ensure thread safety. Note that you will need to install this package via NuGet if it's not already in your project:

