Here is an example of how a continuous integration/continuous deployment (CI/CD) pipeline might be implemented using Node.js and Docker Swarm for orchestration with Kubernetes as third-party container orchestration service. Note that this is just a skeleton code and needs to be extended according to the specific use case:

```javascript
const { spawn } = require('child_process');
const express = require('express');
const app = express();
app.use(express.json()); // middleware for parsing application/json

// Configurable options
const environments = ['development', 'staging', 'production'];
let currentEnvironmentIndex = 0;

function executeCommand(command, args) {
  return new Promise((resolve, reject) => {
    const childProcess = spawn(command, args);
    let stdoutData = '';
    let stderrData = '';

    childProcess.stdout.on('data', (data) => { stdoutData += data; });
    childProcess.stderr.on('data', (data) => { stderrData += data; });

    childProcess.on('error', reject);
    childProcess.on('close', () => resolve({ stdout: stdoutData, stderr: stderrData }));
  });
}

app.get('/status', (req, res) => {
  const environment = environments[currentEnvironmentIndex];
  return res.json({ status: 'Running on environment: ' + environment });
});

app.post('/deploy', async (req, res) => {
  try {
    // Handle build, test and deploy here using executeCommand function

    const serviceName = req.body.service;
    const commandArgs = ['stack', 'deploy', '-c', `docker-compose-${serviceName}.yml`, serviceName];

    await executeCommand('docker', commandArgs);
    return res.json({ status: 'Deployment successful' });
  } catch (error) {
    console.log(error);
    return res.status(500).json({ error: 'Error during deployment' });
  }
});

app.listen(3000, () => {
  console.log('Server is running on http://localhost:3000');
});
```

