typedef struct {
    long offset;
    int key;
    double timestamp;
    char* tags;
} Record;

void* fetch_records(void *arg) {
    PGconn *conn = PQconnectdb("user=user password=password dbname=test hostaddr=127.0.0.1 port=5432");

    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        return NULL;
    }

    // Prepare the SQL query
    char sql[256];
    sprintf(sql, "SELECT * FROM table LIMIT 100");

    // Execute the SQL query
    PGresult *res = PQexec(conn, sql);

    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Failed to fetch records: %s", PQerrorMessage(conn));
        PQclear(res);
        return NULL;
    }

    // Allocate memory for the record array
    Record *records = malloc(PQntuples(res) * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records");
        PQclear(res);
        return NULL;
    }

    // Fetch the records from the result set and populate the arrays
    for (int i = 0; i < PQntuples(res); i++) {
        Record record = {
            .offset = atol(PQgetvalue(res, i, 0)),
            .key = atoi(PQgetvalue(res, i, 1)),
            .timestamp = atof(PQgetvalue(res, i, 2))
        };

        // Assuming the fourth column is a string.
        record.tags = strdup(PQgetvalue(res, i, 3));

        records[i] = record;
    }

    PQclear(res);

    PQfinish(conn);

    return records;
}
```

