Here is an example of how you can structure this Python function using libraries such as `requests` for HTTP requests, `jsonschema` for data validation against schemas, `psycopg2` for PostgreSQL operations, `concurrent.futures` for concurrency and multiprocessing, and `logging` for logging:

```python
import json
import psycopg2
import requests
from jsonschema import validate, ValidationError
from concurrent.futures import ThreadPoolExecutor
from contextlib import contextmanager
import time
import logging

# Define the logger
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

class SensorDataManager:
    def __init__(self, db_credentials):
        self.db_credentials = db_credentials

    @contextmanager
    def connect_to_database(self):
        conn = psycopg2.connect(**self.db_credentials)
        try:
            yield conn
        finally:
            conn.close()

    def fetch_sensor_data(self, device_urls, schema=None):
        with ThreadPoolExecutor() as executor:
            future_to_device = {executor.submit(self._fetch_single_sensor_data, url, schema): url for url in device_urls}

            for future in concurrent.futures.as_completed(future_to_device):
                device_url = future_to_device[future]

                try:
                    data = future.result()
                    self.store_sensor_data(data)
                except Exception as exc:
                    logger.error('Device %r generated an exception: %s' % (device_url, exc))

    def _fetch_single_sensor_data(self, url, schema):
        retry_count = 3

        while retry_count > 0:
            try:
                response = requests.get(url)

                if response.status_code != 200:
                    raise Exception('HTTP Error %s' % response.status_code)

                data = response.json()

                if schema is not None:
                    self.validate_data(data, schema)

                return data
            except requests.RequestException as e:
                retry_count -= 1
                logger.warning('Retrying for device %r due to exception: %s' % (url, str(e)))

                # Exponential backoff
                time.sleep((4-retry_count)**2) 

        raise Exception('Failed to fetch data from device %r after 3 attempts' % url)

    def validate_data(self, data, schema):
        try:
            validate(instance=data, schema=schema)
        except ValidationError as ve:
            logger.error("Validation error: ", str(ve))
            raise

    def store_sensor_data(self, data):
        with self.connect_to_database() as conn:
            cur = conn.cursor()

            # Convert dictionary to JSON string for insertion into database
            json_data = json.dumps(data)

            cur.execute("INSERT INTO sensor_data (json_data, binary_data) VALUES (%s, %s)", 
                        (json_data, data))
            conn.commit()
```  

