import org.springframework.boot.SpringApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.web.client.RestTemplate;
import org.springframework.beans.factory.annotation.Value;

@SpringBootApplication
@EnableCaching
public class PokemonService {

    @Value("${corePoolSize:5}")
    private int corePoolSize;

    @Value("${maxPoolSize:10}")
    private int maxPoolSize;

    public static void main(String[] args) {
        SpringApplication.run(PokemonService.class, args);
    }

    // Define a thread pool task executor for asynchronous calls and caching 
    @Bean("threadPoolTaskExecutor")
    public ThreadPoolTaskExecutor getAsyncExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(corePoolSize);
        executor.setMaxPoolSize(maxPoolSize);
        executor.setWaitForTasksToCompleteOnShutdown(true);
        executor.setThreadNamePrefix("Async-");
        return executor;
    }

    // Define a rest template bean for HTTP requests 
    @Bean
    public RestTemplate getRestTemplate() {
        return new RestTemplate();
    }
}
