import asyncio
from aiofiles import open as aopen
import json
import yaml
import xmltodict
from datetime import datetime
import logging

class DataProcessor:
    def __init__(self, worker_pool_size=10):
        self.worker_pool = asyncio.Semaphore(worker_pool_size)
        # this should be your real storage service, not simulated here
        self.remote_storage_service = StorageService() 

    def cleanup(self):
        self.remote_storage_service.close()

    async def process_files(self, file_names):
        tasks = []
        for file_name in file_names:
            async with self.worker_pool:
                tasks.append(self.process_file(file_name))

        await asyncio.gather(*tasks)

    async def process_file(self, file_name):
        try:
            data = await self.remote_storage_service.get_latest_version_of_file(file_name)
            # assuming all files are json for simplicity
            sensor_configs = await self.parse_json(data)
            await self.save_to_database(sensor_configs)
        except Exception as e:
            logging.error('Error processing file %s: %s', file_name, str(e))

    async def parse_file(self, data, format):
        if format == 'json':
            return await self.parse_json(data)
        elif format == 'yaml':
            return await self.parse_yaml(data)
        elif format == 'xml':
            return await self.parse_xml(data)

    async def parse_json(self, data):
        return json.loads(data)

    async def parse_yaml(self, data):
        return yaml.safe_load(data)

    async def parse_xml(self, data):
        return xmltodict.parse(data)

    async def save_to_database(self, sensor_configs):
        # assume we have a database connection and functions for storing sensor configs in DB
        for sensor_config in sensor_configs:
            await self.database_connection.store_sensor_config(sensor_config)
```

