public class InventoryManager {
    private ReentrantLock lock = new ReentrantLock();
    // Connection to Cassandra database
    Cluster cluster = Cluster.builder().addContactPoints("127.0.0.1").build();
    Session session = cluster.connect();

    public void updateStock(String productId, int stockLevel) {
        try {
            lock.lock();
            // Update the stock level in the database
            SimpleStatement statement = new SimpleStatement("UPDATE products SET stock_level=? WHERE product_id=?");
            session.execute(statement.bind(stockLevel, productId));
        } finally {
            lock.unlock();
        }
    }
}
