Java Application for managing user passwords:
```java
public class UserDAO {

    private String passwordStrengthRegex = "^(?=.*[0-9])(?=.*[a-z])(?=.*[A-Z])(?=.*[@#$%^&+=!])(?=\\S+$).{8,}$";
    private Pattern pattern = Pattern.compile(passwordStrengthRegex); 

    public void updatePassword(String username, String password) throws PasswordFormatException {
        Matcher matcher = pattern.matcher(password);
        if (!matcher.find()) throw new PasswordFormatException();

        SimpleStatement statement = new SimpleStatement("UPDATE users SET password=? WHERE username=?");
        session.execute(statement.bind(hashPassword(password), username));
    }

    private String hashPassword(String password) {
        return BCrypt.hashpw(password, BCrypt.gensalt());
    }
}
```
