#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

void handleErrors(void) { /* Error handling function */ }

int encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *key, 
            unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) return -1;

    if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;

    ciphertext_len = len;

    if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) return -1;

    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

int main (void) {
    /* Set up the key and iv. Do not hard code these in a real application*/
    unsigned char *key = "0123456789abcdef";
    unsigned char *iv = "fedcba9876543210";

