// Parser rules are defined as structs with their logic functions
typedef struct {
    char *ruleName;
    int (*parserFunction)(char*);
} Rule;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *outputFile;
Rule rule[10];  // Assume we have 10 rules for simplicity.

int parseLog(char* logPath) {
    char buf[256];
    FILE *logFile = fopen(logPath, "r");
    if (logFile == NULL){
        perror("Error while opening the file.\n");
        return 1;
    }

    pthread_mutex_lock(&lock);

    // Reading line by line and applying rules
    while(fgets(buf, sizeof buf, logFile)) {
        for (int i = 0; i < 10; i++) {  // Assume we have 10 rules.
            rule[i].parserFunction(buf);
        }
    }

    pthread_mutex_unlock(&lock);

    fclose(logFile);
    return 0;
}

void *processLogThread(void* arg) {
    char *path = (char*)arg;
    parseLog(path);
    return NULL;
}

