void loadEnvironmentVariables() {
    char env_file[256];
    FILE * file;
    if (getenv("ENVIRONMENT") && strcmp(getenv("ENVIRONMENT"), "production") == 0) {
        sprintf(env_file, "./.env.production");
    } else {
