               // Commit the transaction
               await transaction.CommitAsync();
               return updated;
            } catch (Exception ex){
               // Rollback on exception
               await transaction.RollbackAsync();
               throw;
            }
         }
   }

   private async Task<bool> UpdateDashBoardAsync(SensorData data, IDbContextTransaction transaction) {
      try{
         // Assuming that you have an entity called "Dashboard" with properties for each sensor
         var dashboard = await _context.Dashboards.FindAsync(data.deviceId);

         if (dashboard == null){
            return false;
         }

         // Update the relevant fields
         dashboard.GetType().GetProperty(data.sensorName).SetValue(dashboard, data.value);

         // Save changes to the database
         await _context.SaveChangesAsync();
      } catch (DbUpdateConcurrencyException ex) {
         return false;
      }
   }
}
