public XmlNode GetSingleElementByName(string name, string xml)
{
    var document = new XmlDocument();
    document.LoadXml(xml);

    var navigator = document.CreateNavigator();
    var iterator = navigator.Select("/descendant::" + name);
    var matches = 0;
    XmlNode result = null;

    while (iterator.MoveNext())
    {
        if(matches > 1) throw new Exception("Multiple elements found with given name");
        result = (XmlNode)iterator.Current.UnderlyingObject;
        matches++;
    }

    if(matches == 0) throw new Exception("No element found with given name");

    return result;
}
