```python
import hashlib
from threading import Thread
import os

def calculate_file_md5(file_path, chunk_size=8192, progress_callback=None, storage_backend=None):
    try:
        file = open(file_path, 'rb')
    except FileNotFoundError:
        print("File not found")
        return None
    except PermissionError:
        print("Permission denied")
        return None

    md5hash = hashlib.md5()

    def read_chunk(start, end):
        file.seek(start)
        data = file.read(min(end - start, chunk_size))

        if not data:
            return

        md5hash.update(data)

        if progress_callback is not None:
            progress = 100 * (start / os.path.getsize(file_path))
            progress_callback(progress)

    threads = []
    for i in range(0, os.path.getsize(file_path), chunk_size):
        t = Thread(target=read_chunk, args=(i, i+chunk_size))
        threads.append(t)
        t.start()

    for thread in threads:
        thread.join()

    file.close()

    hexdigest = md5hash.hexdigest()

    if storage_backend is not None:
        storage_backend.store(hexdigest)

    return hexdigest
```
In the Python function, we use threads to read and hash chunks of data from the file in parallel. We use a callback to report progress if one was provided, and a pluggable backend system for storing the hash value if one was specified. Note that this is a simplified implementation and should be adjusted as per your actual requirements.

