import threading
from collections import deque
import time
from abc import ABC, abstractmethod

class TrendDetector(ABC):
    @abstractmethod
    def calculate_trend(self, data):
        pass

class SimpleMovingAverage(TrendDetector):
    def __init__(self, window):
        self.window = window

    def calculate_trend(self, data):
        return sum(data) / len(data)

class ExponentialMovingAverage(TrendDetector):
    def __init__(self, smoothing_factor):
        self.smoothing_factor = smoothing_factor

    def calculate_trend(self, data):
        return sum(data) / len(data) * self.smoothing_factor

class RelativeStrengthIndex(TrendDetector):
    def calculate_trend(self, data):
        avg_gain = sum((x - data[i-1]) for i, x in enumerate(data) if x > data[i-1]) / (len(data) - 1)
        avg_loss = sum((x - data[i-1]) for i, x in enumerate(data) if x < data[i-1]) / (len(data) - 1)
        return avg_gain / avg_loss

class RealTimeStockTrendAnalyzer:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    def set_trend_strategy(self, strategy):
        self.strategy = strategy

    # Fetch data from the financial API (not included due to complexity)
    def fetch_data(self, symbol):
        return []

    # Get trend with caching and thread-safe management
    def get_trend(self, symbol):
        if symbol in self.cache:
            return self.cache[symbol]

        data = self.fetch_data(symbol)
        with self.lock:
            trend = self.strategy.calculate_trend(data)
            self.cache[symbol] = trend
        return trend
