```java
import org.apache.http.*;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import com.squareup.okhttp.*;
import org.apache.log4j.*;
import java.io.*;
import java.util.*;

public class HttpRequestManager {
    private static final Logger logger = Logger.getLogger(HttpRequestManager.class);
    private CloseableHttpClient httpClient;
    private OkHttpClient rateLimitClient;
    private Map<String, String> cache;

    public HttpRequestManager() {
        this.httpClient = HttpClients.createDefault();
        this.rateLimitClient = new OkHttpClient();
        this.cache = new HashMap<>();
    }

    public String get(String url, Map<String, String> headers) throws Exception {
        if (cache.containsKey(url)) {
            return cache.get(url);
        } else {
            HttpGet request = new HttpGet(url);
            for (Map.Entry<String, String> entry : headers.entrySet()) {
                request.addHeader(entry.getKey(), entry.getValue());
            }

            try (CloseableHttpResponse response = httpClient.execute(request)) {
                HttpEntity entity = response.getEntity();
                if (entity != null) {
                    String result = EntityUtils.toString(entity);
                    cache.put(url, result);
                    return result;
                } else {
                    logger.error("Response was empty for url: " + url);
                    throw new Exception("Empty response");
                }
            } catch (Exception e) {
                logger.error("Request failed for url: " + url, e);
                throw e;
            }
        }
    }

    // Add other request methods like POST, PUT etc here...
}
```

This is a simple demonstration of how you might implement the HTTP request handling in an application. For the rate limiting and caching, the OkHttpClient's interceptor mechanism can be used to automatically handle these tasks for all requests made through this client. 

For logging, Log4j2 provides configurable loggers that are capable of writing to various sources like files, databases etc. 

