import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import org.apache.commons.codec.digest.DigestUtils;
import com.fasterxml.jackson.databind.ObjectMapper;

public class DynamicNestedDeserializer {
    private final Cache<String, Class> classCache;
    private ObjectMapper mapper = new ObjectMapper();

    public DynamicNestedDeserializer(int cacheSize) {
        this.classCache = CacheBuilder.newBuilder()
            .maximumSize(cacheSize)
            .build();
    }

    public synchronized <T> T deserialize(byte[] data, Class<T> targetClass) 
            throws Exception {

        String classHash = DigestUtils.sha256Hex(targetClass.getName());
        Class<?> clazz = classCache.getIfPresent(classHash);

        if (clazz == null) {
            // Get class definition and constructor from the external REST API in JSON format
            // Assume that getClassDefinition returns a String with JSON serialized data
            String jsonData = getClassDefinition(targetClass.getName());

            @SuppressWarnings("unchecked")
            Class<? extends T> tmpClazz = 
                (Class<? extends T>) mapper.readValue(jsonData, targetClass);

            classCache.put(classHash, tmpClazz);
            clazz = tmpClazz;
        }

        // Deserialize byte array to an instance of the class
        return (T) mapper.readerFor(clazz).readValue(data);
    }

    private String getClassDefinition(String className) {
        // Implement this method to fetch class definition from external API
        // The class data should be in JSON format
        throw new UnsupportedOperationException();
    }
}
