```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.HashOperations;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Repository;
import javax.annotation.PostConstruct;

@Repository
public class CacheServiceImpl implements CacheService {
    private static final String KEY = "MyKey";

    private RedisTemplate<String, Object> redisTemplate;
    private HashOperations<String, Integer, User> hashOperations;

    @Autowired
    public CacheServiceImpl(RedisTemplate<String, Object> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    @PostConstruct
    private void init() {
        hashOperations = redisTemplate.opsForHash();
    }

    public void insert(User user) {
        hashOperations.put(KEY, user.getId(), user);
    }

    public void update(User user) {
        hashOperations.put(KEY, user.getId(), user);
    }

    public User findById(Integer id) {
        return (User)hashOperations.get(KEY, id);
    }
}
```
This example is a basic CRUD operation for Redis in Java using Spring Boot and Spring Data Redis. The CacheServiceImpl class uses the HashOperations interface provided by Spring Data Redis to perform insert, update and find operations on User objects stored in the cache. 

