void insertAfterSearchString(std::forward_list<std::string> &fl, const std::string &searchStr, const std::string &insertionStr, int maxInsertions) {
    auto it = fl.begin();

    for (int i = 0; i < maxInsertions && it != fl.end(); ++i, ++it) {
        if (*it == searchStr) {
            // Insert the string after search string and break the loop
            ++it;  // Increment iterator to maintain its position
            fl.insert_after(it, insertionStr);
            return;
        }
