import java.util.*;
import java.io.File;
import org.yaml.snakeyaml.Yaml;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.kubernetes.client.ApiClient;
import io.kubernetes.client.Configuration;
import io.kubernetes.client.apis.CoreV1Api;
import io.kubernetes.client.models.V1ConfigMap;
import io.kasternakas.schema.validator.SchemaValidator;

public class ConfigurationManager {
    private Map<String, Function<Object[], Object>> factoryRegistry = new ConcurrentHashMap<>();
    private Yaml yaml = new Yaml();
    private SchemaValidator validator;
    private CoreV1Api apiInstance;

    public ConfigurationManager(SchemaValidator validator) {
        this.validator = validator;
        ApiClient defaultClient = Configuration.getDefaultApiClient();
        apiInstance = new CoreV1Api(defaultClient);
    }

    // Add a factory function to the registry
    public void addFactoryFunction(String id, Function<Object[], Object> func) {
        factoryRegistry.put(id, func);
    }

    // Remove a factory function from the registry
    public void removeFactoryFunction(String id) {
        factoryRegistry.remove(id);
    }

    // Create an instance of a configuration-related class using its factory function
    public Object createInstance(String id, Object... params) throws Exception {
        Function<Object[], Object> func = Optional.ofNullable(factoryRegistry.get(id))
            .orElseThrow(() -> new RuntimeException("No factory function registered for ID " + id));

        return func.apply(params);
    }

    // Read configuration data in YAML format from a file and validate it against the schema
    public Object readFromFileAndValidate(String filename, Class<?> clazz) throws Exception {
        File yamlFile = new File(filename);
        Object obj = yaml.loadAs(yamlFile, clazz);

        validator.validate(obj);

        return obj;
    }

    // Fetch configuration data from a Kubernetes ConfigMap
    public Map<String, String> fetchConfigFromK8s() throws Exception {
        V1ConfigMap configMap = apiInstance.readNamespacedConfigMap(/* your parameters here */);

        return configMap.getData();
    }
}
