<?php
use PDO;
use Zend\I18n\Translator\Translator;

class UserService {
    private $pdo;
    private $translator;
    private $logger;

    public function __construct(PDO $pdo, Translator $translator) {
        $this->pdo = $pdo;
        $this->translator = $translator;
        $this->logger = new Monolog\Logger('app'); // Use any logger you prefer here
    }

    public function updateUserPassword(string $userId, string $newPassword, array $localeRules): bool {
        try {
            $stmt = $this->pdo->prepare("SELECT password FROM users WHERE id = :id");
            $stmt->bindParam(':id', $userId);
            $stmt->execute();

            if ($stmt->rowCount() === 0) {
                $this->logger->warning("User not found", ['user_id' => $userId]);
                return false;
            }

            $currentPassword = $stmt->fetchColumn();

            // Validate new password against rules for current locale. 
            if (!$this->validatePassword($newPassword, $localeRules[$this->translator->getLocale()])) {
                $this->logger->warning("Invalid password", ['user_id' => $userId]);
                return false;
            }

            $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id AND password = :currentPassword");
            $stmt->bindParam(':password', $newPassword);
            $stmt->bindParam(':id', $userId);
            $stmt->bindParam(':currentPassword', $currentPassword);

            if (!$stmt->execute()) {
                $this->logger->error("Failed to update password", ['user_id' => $userId]);
                return false;
            }
        } catch (PDOException $e) {
            $this->logger->critical($e->getMessage(), ['user_id' => $userId]);
            return false;
        }

        $this->logger->info("Password updated successfully", ['user_id' => $userId]);
        return true;
    }

    private function validatePassword(string $password, array $localeRules): bool {
        // Add your password validation logic here. This is just an example and does not include all required rules.
        $uppercase = preg_match('@[A-Z]@', $password);
        $lowercase = preg_match('@[a-z]@', $password);
        $digit = preg_match('@\d@', $password);
        $specialChar = preg_match('@[^\w]@', $password);

        if (!$uppercase || !$lowercase || !$digit || !$specialChar) {
            return false;
        }

        foreach ($localeRules['forbiddenSubstrings'] as $substring) {
            if (strpos($password, $substring) !== false) {
                return false;
            }
        }

        return true;
    }
}
