```cpp
#include <iostream>
#include <filesystem>
#include <Magick++.h> 

int convertToPdf(const std::string &inputDir, const std::vector<std::string> &images, 
                 const std::string &outputDir, int width = 0) {
    Magick::InitializeMagick(nullptr); // Initialize Magick++

    namespace fs = std::filesystem;

    if (!fs::exists(inputDir)) {
        std::cerr << "Input directory does not exist\n";
        return 0;
    }

    if (!fs::is_directory(outputDir)) {
        std::cerr << "Output directory is not a directory or does not exist\n";
        return 0;
    }

    int successCount = 0;

    for (const auto &file : images) {
        try {
            Magick::Image image((inputDir + "/" + file).c_str());

            if (width > 0 && static_cast<int>(image.columns()) > width) {
                image.resize(Magick::Geometry(width, 0)); // Resize to the specified width
            }

            fs::path outputPath = fs::path(outputDir) / file;
            outputPath.replace_extension("pdf"); // Replace extension with .pdf
            image.write(outputPath.c_str()); // Save as a PDF
            ++successCount;
        } catch (Magick::Exception &error_) { 
            std::cerr << "Caught exception: " << error_.what() << '\n'; 
        } 
    }

    return successCount;
}
```
