Here is an example on how you could implement this using Node.js, Express and Redis for caching:

```javascript
const express = require('express');
const axios = require('axios');
const redis = require('redis');
const lock = require('redis-lock')(redis);
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());
let client = redis.createClient();

app.patch('/user/:id', async (req, res) => {
  let locker = new lock(client);

  try {
    const userId = req.params.id;
    await locker.acquire('lock-'+userId, function(done){
      client.get('user_' + userId, async (err, data) =>{
        if (data !== null){ // If cached
          let updateData = req.body;
          for (let key in updateData) {
            data[key] = updateData[key];
          }
          client.set('user_' + userId, JSON.stringify(data));
          done();
        } else { // If not cached fetch from DB
          let updateData = req.body;
          for (let key in updateData) {
            data[key] = updateData[key];
          }
          client.set('user_' + userId, JSON.stringify(data));
          done();
        }
      });
    });

  } catch (error) {
    res.status(500).send({ error: 'An unexpected error occurred.'});
  }
});

app.post('/sync/:id', async (req, res) => {
  try {
    const userId = req.params.id;

    client.get('user_' + userId, async (err, data) =>{
      let response = await axios.post(`<external-api>`, data);
      res.send({ message: 'Profile updated on social media platform successfully.', metadata: response.data });
    }); 

  } catch (error) {
    if (error.response) { // If the error was caused by a request to external API
      res.status(502).send({ error: 'Failed to update profile on social media platform.'});
    } else {
      res.status(500).send({ error: 'An unexpected error occurred.'});
    }
  }
});
```

