Here's how you can create the mentioned modules in C:

**String Processing Module**
```c
#include <stdlib.h>
#include <string.h>

char *append_slash_if_necessary(const char *str, size_t limit) {
    if (str == NULL || strlen(str) > limit) {
        return NULL;
    }

    size_t len = strlen(str);
    char *result = malloc(sizeof(char)*(len+2)); // +1 for slash, +1 for null terminator
    if (result == NULL) {
        return NULL;  // Failed to allocate memory.
    }

    strncpy(result, str, len); // Copy the string
    result[len] = '/';       // Append slash
    result[len+1] = '\0';    // Add null terminator at end

    return result;
}
```
This function appends a slash to the input string if its length is less than or equal to the limit. It creates a new string with enough space for both the original string and the appended slash. The new string must be freed by the caller when no longer needed to prevent memory leaks. 

**Report Generation and Distribution Module**
```c
#include <pthread.h>
#include <mongoose.h> // MongoDB C driver
#include <mysql/mysql.h> // MySQL C API
#include <libpq-fe.h> // PostgreSQL C API
#include <mongoc.h> // MongoDB C Driver
#include <curl/curl.h> // curl library for email and sms integration
#include <stdarg.h> 
#include <stdio.h>  

// Global error log file 
FILE *error_log;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *format, ...) {
    va_list args;
    va_start (args, format);

    pthread_mutex_lock(&lock); // Lock to prevent simultaneous writing

    vfprintf(error_log, format, args); 

    pthread_mutex_unlock(&lock); // Unlock after write
    va_end (args);             
}
```
