    /** 
     * Hash a given password. Support for password stretching and salting configurable based on chosen hash algorithm
     */
    public function hashPassword(string $password, string $hashAlgo, int $stretchFactor, bool $useSalt): string {
        if ($useSalt) {
            $salt = $this->generateSalt(); // Generate a salt with a unique identifier and secure CSPRNG
            return hash($hashAlgo, $password . $salt);
        } else {
            for ($i = 0; $i < $stretchFactor; $i++) {
                $password = hash($hashAlgo, $password); // Stretching the password hash with a given algorithm
            }
            return $password;
        }
    }

    /** 
     * Generate a unique salt using CSPRNG
     */
    private function generateSalt(): string {
        $uniqueIdentifier = uniqid(); // Use a unique identifier for each password
        if (function_exists('random_bytes')) {
            $salt = bin2hex(random_bytes(16)); // PHP 7+, uses the CSPRNG
        } elseif (function_exists('mcrypt_create_iv')) {
            $salt = bin2hex(mcrypt_create_iv(16, MCRYPT_DEV_URANDOM)); // Use a fallback if mcrypt is available
        } else {
            throw new Exception("Unable to generate salt. No cryptographic secure method available.");
        }
        return $salt . $uniqueIdentifier;
    }

    /** 
