#include <aws/core/Aws.h>
#include <aws/s3/S3Client.h>
#include <aws/s3/model/PutObjectRequest.h>
#include <openssl/sha.h>
#include <curl/curl.h>

#define CHUNK 16384
char file_buffer[CHUNK];
FILE *file;

// Function to calculate the SHA-256 hash of a file, reading it in chunks to optimize memory usage
std::string calc_sha256(const std::string &filename) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    file = fopen(filename.c_str(), "rb");
    while (fgets(file_buffer, CHUNK, file) != NULL){
        SHA256_Update(&sha256, file_buffer, strlen(file_buffer));
    }

    SHA256_Final(hash, &sha256);

    std::string output = "";
    char buffer[3];

    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(buffer, "%.2x", hash[i]);
        output += buffer;
    }

    return output;
}

// Function to upload file to S3 bucket
void uploadToS3() {
    Aws::SDKOptions options;
    Aws::InitAPI(options);

    const Aws::String s3_bucket_name = "my-unique-s3-bucket";
    const Aws::String file_to_upload = "path/to/file.txt";
    const Aws::S3::Model::PutObjectRequest request;

    request.SetBucket(s3_bucket_name);
    request.SetKey(file_to_upload);

    auto outcome = s3Client.PutObject(request);

    if (outcome.IsSuccess()) {
        std::cout << "File uploaded successfully" << std::endl;
    } else {
        std::cout << "Error uploading file: " << outcome.GetError().GetMessage() << std::endl;
    }

    Aws::ShutdownAPI(options);
}

// Function to handle download resume in case of interruptions with libcurl
size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

int main() {
    CURL *curl;
    FILE *fp;
    int result;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    fp = fopen("filename", "wb");

    curl_easy_setopt(curl, CURLOPT_URL, "remote_url");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
    curl_easy_setopt(curl, CURLOPT_RESUME_FROM_LARGE , ftell(fp)); // Resume download from where it left off in the file

    result = curl_easy_perform(curl);

    /* Check for errors */ 
    if(result != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(result));
    }

    /* always cleanup */ 
    curl_easy_cleanup(curl);

    fclose(fp);
    return 0;
}
