public class DynamicDataProcessor {
    private static final int MAX_CACHE_SIZE = 100; // configure as per your requirement

    private Cache<String, Class> classCache = new LRUCache<>(MAX_CACHE_SIZE);

    public <T> T deserialize(byte[] inputData, String className) {
        Class<T> clazz = getClassFromCacheOrFetch(className);

        // perform custom logic based on annotations/configurations if necessary

        try (ByteArrayInputStream bis = new ByteArrayInputStream(inputData)) {
            ObjectInput in = null;
            try {
                in = new ObjectInputStream(bis);
                return clazz.cast(in.readObject()); // cast to desired class
            } finally {
                if (in != null) {
                    in.close();
                }
            }
        } catch (IOException | ClassNotFoundException e) {
            throw new DeserializationException("Failed to deserialize data", e);
        }
    }

    private synchronized <T> Class<T> getClassFromCacheOrFetch(String className) {
        Class<T> clazz = classCache.get(className);

        if (clazz == null) {
            // fetch from remote API, validate version and update cache

            try {
                ResponseEntity<byte[]> response = restTemplate.exchange(
                    "http://example.com/api/{className}", HttpMethod.GET, null, byte[].class, className);

                // validate version from response headers if necessary

                clazz = (Class<T>) ClassLoaderUtil.defineClass(response.getBody());

            } catch (Exception e) {
                throw new FetchClassException("Failed to fetch class definition", e);
            }

            classCache.put(className, clazz);
        }

        return clazz;
    }
}
