const axios = require('axios');
const { Pool } = require('pg');
const pool = new Pool();

class PaymentProcessor {
    constructor(poolSize, maxRetries = 5) {
        this.maxParallelWorkers = poolSize;
        this.activeWorkers = 0;
        this.tasksQueue = [];
        this.taskPromises = [];
        this.providerAPIs = {};  // map from provider to their APIs
    }

    async fetchPaymentDetails(paymentId) {
        const providerAPI = this.getProviderAPI(paymentId);

        try {
            const response = await axios.get(providerAPI + paymentId);

            // check API version mismatches here...

            return response.data;
        } catch (error) {
            // handle network errors, authentication failures, timeouts etc...
        }
    }

    async processPayments(paymentIds) {
        this.tasksQueue = paymentIds;  // initialize queue

        while (this.tasksQueue.length > 0 || this.activeWorkers > 0) {
            if (this.tasksQueue.length > 0 && this.activeWorkers < this.maxParallelWorkers) {
                const paymentId = this.tasksQueue.shift();  // get next task from queue

                this.taskPromises.push(this.fetchPaymentDetails(paymentId));
                this.activeWorkers++;
            }

            await Promise.race(this.taskPromises);
            this.activeWorkers--;
        }
    }

    async run() {
        try {
            console.log("Processing payments...");
            await this.processPayments();
            console.log("Finished processing payments.");
        } catch (error) {
            console.error(`An error occurred: ${error}`);
        } finally {
            pool.end();  // close database connections after we're done with them
        }
    }

    addProviderAPI(provider, api) {
        this.providerAPIs[provider] = api;
    }

    getProviderAPI(paymentId) {
        const provider = PaymentProcessor.getPaymentProvider(paymentId);  // replace with actual logic to fetch provider from payment ID

        if (this.providerAPIs[provider]) {
            return this.providerAPIs[provider];
        } else {
            throw new Error(`API for ${provider} not found`);
        }
    }

    static getPaymentProvider(paymentId) { /* Implement this based on how you identify payment providers */ }
}
