```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <mutex>
#include <atomic>

std::mutex mtx;
std::atomic<bool> dbConnected(true);  // For simulating database connection

void insert_after_search(std::forward_list<std::string>& flist, const std::string& search, const std::string& insertion, int maxInserts) {
    mtx.lock();
    auto it = flist.begin();
    for (int i = 0; i < maxInserts && it != flist.end(); ++i, ++it) {
        if (*it == search) {
            it = flist.insert_after(it, insertion);
            break;
        }
    }

    // If not found within maximum insertions allowed or list is empty
    if (flist.empty() || *(--flist.end()) != search) {
        flist.push_front(insertion);
    }

    for(auto& str : flist){
        if(str.length() > 100)
            str = str.substr(0, 99);  // Truncate string to 100 characters
    }

    mtx.unlock();

    // simulate db operations
    if (dbConnected){
        //... perform database insert operation
    } else {
        std::cout << "Error: Database connection lost.\n";
        return;
    }
}
```
