from abc import ABC, abstractmethod

class StorageServiceClient(ABC):
    @abstractmethod
    def get_file(self, file_path: str):
        pass

class FileMetadataExtractor:
    def __init__(self, storage_service: StorageServiceClient):
        self.storage_service = storage_service

    async def extract_metadata(self, file_path: str, metadata_class: type):
        if not issubclass(metadata_class, Metadata):
            raise RuntimeError("Invalid metadata class")

        data = await self.storage_service.get_file(file_path)
        return metadata_class.from_data(data)
