using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Collections.Concurrent;

public class SecureMessageProcessor : IDisposable
{
    private static readonly ConcurrentDictionary<string, (SymmetricAlgorithm Cipher, string IV)> Ciphers = new ConcurrentDictionary<string, (SymmetricAlgorithm, string)>();

    // Assuming an external logging system that supports multiple log levels and configurable destinations
    private static readonly ILogger logger;

    public void DecryptMessage(string encryptedBase64String, byte[] key, byte[] IV)
    {
        if (key == null || key.Length <= 0) throw new ArgumentNullException("Key must be provided");
        if (IV == null || IV.Length <= 0) throw new ArgumentNullException("Initialization vector must be provided");

        try
        {
            using var aes = new TripleDESCryptoServiceProvider();

            // Implement key and IV validation here...
            if(!Ciphers.ContainsKey(Convert.ToBase64String(key)))
                Ciphers[Convert.ToBase64String(key)] = (aes, Convert.ToBase64String(IV));

            var cipher = Ciphers[Convert.ToBase64String(key)];

            // Assuming a rate-limiter here...
            if(!RateLimiter.TryAcquire()) throw new Exception("Rate limit exceeded");

            using (var decryptor = cipher.Cipher.CreateDecryptor(key, cipher.IV))
            {
                var encryptedBytes = Convert.FromBase64String(encryptedBase64String);

                using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            // Return the decrypted message...
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception e)
        {
            logger.Error(e);
        }
    }

    public void Dispose()
    {
        foreach (var cipher in Ciphers.Values)
        {
            cipher.Cipher?.Dispose();
        }
    }
}
