import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import java.util.*;
import javax.crypto.*;

public class CryptographicConfigurationManager {

    private ObjectMapper yamlReader = new ObjectMapper(new YAMLFactory());
    private ObjectMapper jsonReader = new ObjectMapper();
    private Map<String, Cipher> ciphersMap = new HashMap<>();
    private boolean isYamlFormat;

    public void loadConfigurationFromFile(String filePath) {
        try {
            if (filePath.endsWith(".yaml") || filePath.endsWith(".yml")) {
                Map<String, Object> config = yamlReader.readValue(new File(filePath), Map.class);
                isYamlFormat = true;
                loadConfigurationFromMap(config);
            } else if (filePath.endsWith(".json")) {
                Map<String, Object> config = jsonReader.readValue(new File(filePath), Map.class);
                isYamlFormat = false;
                loadConfigurationFromMap(config);
            } else {
                throw new IllegalArgumentException("Unsupported file format: " + filePath);
            }
        } catch (IOException e) {
            // handle exception
        }
    }

    private void loadConfigurationFromMap(Map<String, Object> config) {
        if (!config.containsKey("ciphers")) {
            throw new IllegalArgumentException("Invalid configuration: missing ciphers key");
        }

        Map<String, String> ciphersConfig = (Map<String, String>) config.get("ciphers");
        for (Map.Entry<String, String> entry : ciphersConfig.entrySet()) {
            try {
                Cipher cipher;
                switch(entry.getValue()) {
                    case "DES": 
                        cipher = Cipher.getInstance("DES/ECB/PKCS5Padding");
                        break;

                    // Add other ciphers here...

                    default: 
                        throw new IllegalArgumentException("Unsupported cipher: " + entry.getValue());
                }

                ciphersMap.put(entry.getKey(), cipher);
            } catch (NoSuchAlgorithmException | NoSuchPaddingException e) {
                // handle exception
            }
        }
    }

    public Cipher getCipher(String id) {
        return ciphersMap.get(id);
    }
}
```
