public class LoggingExample {
    private static final String LOG_FILE = "logs/mylogfile.txt";

    public enum SeverityLevel { INFO, ERROR };

    private static final Map<SeverityLevel, Logger> loggers = new EnumMap<>(SeverityLevel.class);

    static {
        System.setProperty("logFile", LOG_FILE);

        for (SeverityLevel level : SeverityLevel.values()) {
            String loggerName = LoggingExample.class.getName() + "." + level.name();
            loggers.put(level, LoggerFactory.getLogger(loggerName));
        }
    }

    public void logMessage(SeverityLevel severity, String message) {
