    constructor(financialApiService, workerPoolSize) {
        this.apiService = financialApiService;
        this.pool = new utils.WorkerPool(workerPoolSize);
    }

    async startProcessing() {
        const encryptionConfig = await utils.getEncryptionConfig();  // This would get the necessary config from a secure location.

        let total = 0;
