        this.webSocketClient.onmessage = async ({ data }) => {
            const message = JSON.parse(data);

            if (this.isRelevantMessage(message)) {
                total += await this.pool.runTask(() => this.processTransaction(message, encryptionConfig));
                console.log('Current Total: ', total);
            }
        };
