Here is a basic implementation of such a function in C using POSIX semaphores and pthreads, with logging via a hypothetical `log_message` function. 

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <errno.h>

// This is just for demonstration purpose, it should be replaced with a real logging system in production code.
void log_message(const char* message) {
    printf("%s\n", message);
}

typedef struct SemaphoreConfig {
    int value;
    // Add more config properties as needed.
} SemaphoreConfig;

// Function to create a semaphore with the specified configuration.
sem_t* createSemaphore(SemaphoreConfig* config) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // This mutex protects concurrent access to creation and deletion of semaphores.
    if (pthread_mutex_lock(&lock) != 0) {
        log_message("Failed to acquire the semaphore lock.");
        return NULL;
    }

    // Allocate memory for a new semaphore.
    sem_t* sem = malloc(sizeof(sem_t));
    if (sem == NULL) {
        log_message("Failed to allocate memory for the semaphore.");
        pthread_mutex_unlock(&lock); // Make sure we always unlock our mutex.
        return NULL;
    }

    // Initialize the semaphore with the specified initial value.
    if (sem_init(sem, 0, config->value) != 0) {
        log_message("Failed to initialize the semaphore.");
        free(sem); // Make sure we always deallocate our memory even on failure.
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pthread_mutex_unlock(&lock);
    log_message("Created a semaphore successfully.");
    return sem;
}

// Function to delete the specified semaphore.
void deleteSemaphore(sem_t* sem) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // This mutex protects concurrent access to creation and deletion of semaphores.
    if (pthread_mutex_lock(&lock) != 0) {
        log_message("Failed to acquire the semaphore lock.");
        return;
    }

    // Destroy the semaphore.
    if (sem_destroy(sem) != 0) {
        log_message("Failed to destroy the semaphore.");
    } else {
        log_message("Destroyed a semaphore successfully.");
    }

    free(sem); // Deallocate the memory.
    pthread_mutex_unlock(&lock);
}
```
This code only provides a basic implementation and does not include testing, unit tests or logging to an external system. However, this could be expanded with additional functionality as needed according to requirements. It is also important to note that real-world applications should implement error handling at a higher level rather than returning NULL on failure (like in the `createSemaphore` function).

