    next_id = id + 1; // Assume each record in the config file has a unique ID. 
    fclose(file);
}

int get_next_unique_id() {
    return atomic_fetch_add(&next_id, 1);
}

void set_value(_Atomic int id, int value) {
    pthread_mutex_lock(&lock); // Ensure thread safety when setting values.

    db_api.set(id, value);

    pthread_mutex_unlock(&lock); 
}

int get_value(_Atomic int id) {
    return db_api.get(id);
}
```
