char* constructFilePath(const char* filepath, int max_buffer_size, bool isAbsolute, char* errorMsg) {
    size_t len = strlen(filepath);

    if (len > max_buffer_size) {
        sprintf(errorMsg, "File path exceeds the maximum buffer size.");
        return NULL;
    }

    // Simplified check for absolute path. In a production scenario this would be more complex and platform specific.
    if (!isAbsolute && filepath[0] != '/') {
        sprintf(errorMsg, "Non-absolute paths must start with '/'.");
        return NULL;
    }

    // Simplified check for environment variable '~'. In a production scenario this would be more complex.
    if (strchr(filepath, '~') != NULL) {
        char* cwd = getcwd(NULL, 0);
        size_t newLen = len + strlen(cwd);

        if (newLen > max_buffer_size) {
            sprintf(errorMsg, "File path exceeds the maximum buffer size after resolving environment variable.");
            free(cwd);
            return NULL;
        }

        char* newPath = malloc((newLen + 1) * sizeof(char)); // +1 for null-terminator
        strcpy(newPath, cwd);
        strcat(newPath, filepath+1); // Skip '~' character

        free(cwd);
        return newPath;
    }

    char* result = malloc((len + 1) * sizeof(char)); // +1 for null-terminator
    strcpy(result, filepath);

    return result;
}
