    private static byte[] iv = Encoding.UTF8.GetBytes("encryptioniv67890"); //replace with your initialization vector

    public UserProfileService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<byte[]> DecryptAndUpdateUserProfileAsync(string ciphertext, string userId)
    {
        // Validate the user ID and directory paths...

        // Decrypt the ciphertext using AES-CBC...
        byte[] encrypted = Convert.FromBase64String(ciphertext);
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encrypted))
            {
