```c
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Logging levels
typedef enum {
    DEBUG, INFO, WARNING, ERROR
} log_level;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
log_level currentLevel = INFO; // Default logging level is INFO

void setLoggingLevel(log_level newLevel) {
    pthread_mutex_lock(&lock);
    currentLevel = newLevel;
    pthread_mutex_unlock(&lock);
}

// Function to log a conditionally formatted message if the given condition is true
void logCondition(int cond, log_level level, const char *format, ...) {
    va_list args;

    // Return if the condition isn't met or the logging level is less than required
    if (!cond || level < currentLevel) return;

    pthread_mutex_lock(&lock);
    va_start(args, format);

    // Calculate message length to avoid buffer overflow
    int len = vsnprintf(NULL, 0, format, args);
    if (len < 0 || len >= 1024) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Allocate memory for the message and log it if the length is correct
    char *buffer = malloc(len + 1);
    vsnprintf(buffer, len + 1, format, args);
    va_end(args);

    switch (level) {
        case DEBUG:   printf("DEBUG: %s\n", buffer); break;
        case INFO:    printf("INFO: %s\n", buffer); break;
        case WARNING: printf("WARNING: %s\n", buffer); break;
        case ERROR:   printf("ERROR: %s\n", buffer); break;
    }

    free(buffer); // Free the allocated memory after logging
    pthread_mutex_unlock(&lock);
}
```
This code snippet provides a function to log messages conditionally and with variable arguments. It also uses mutex locks to prevent concurrent access issues. It introduces a configuration option to specify the minimum level of logs that should be logged (e.g., only warnings or errors). Please note, you would need to link against `-lpthread` to compile this code.

