const express = require('express');
const router = express.Router();
const UserService = require('./userService'); // assume we have a userService module
const cache = require('./cacheService');  //assume we have a cache service

// Update user profile route
router.patch('/users/:id', async (req, res) => {
    const userId = req.params.id;
    const updates = req.body;

    try{
        // Check if the user's data is cached and serve from cache 
        let userFromCache = await cache.get(userId);

        if (userFromCache) {
            return res.json({ message: 'Data retrieved from cache', data: userFromCache });
        }

        const updatedUser = await UserService.updateProfile(userId, updates);
        // Update the cache for future requests
        cache.set(userId, updatedUser);

        res.json({ message: 'User profile updated successfully', data: updatedUser });
    } catch (err) {
      if (err instanceof UserService.NotFoundError){
          res.status(404).json({ error: err.message });
      } else if (err instanceof UserService.InvalidUpdateError){
          res.status(422).json({ error: err.message });
      }else {
        console.error(err);
        res.status(500).json({ error: 'An unexpected error occurred' });
      }
    }
});
module.exports = router;
