```cpp
#include <unordered_map>
#include <string>
#include <variant>
#include <fstream>
#include <typeindex>
#include "json.hpp"

using json = nlohmann::json;

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> readConfig(const std::string& filePath, const std::unordered_map<std::string, std::type_index>& schema) {
    std::ifstream configFile(filePath);
    if (!configFile.is_open()) {
        throw std::runtime_error("Could not open configuration file: " + filePath);
    }

    json j;
    try {
        configFile >> j;
    } catch (const nlohmann::json::parse_error& e) {
        throw std::invalid_argument("Failed to parse JSON from configuration file, reason: " + std::string(e.what()));
    }

    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> config;

    for (const auto& entry : schema) {
        const std::string& key = entry.first;
        const std::type_index expectedType = entry.second;

        // Check if the key exists in the JSON object
        if (!j.contains(key)) {
            throw std::invalid_argument("Missing required configuration setting: " + key);
        }

        // Validate and assign data types
        json value = j[key];
        if (expectedType == typeid(int) && value.is_number_integer()) {
            config[key] = value.get<int>();
        } else if (expectedType == typeid(double) && value.is_number_float()) {
            config[key] = value.get<double>();
        } else if (expectedType == typeid(std::string) && value.is_string()) {
            config[key] = value.get<std::string>();
        } else if (expectedType == typeid(bool) && value.is_boolean()) {
            config[key] = value.get<bool>();
        } else {
            throw std::invalid_argument("Data type mismatch for setting: " + key);
        }
    }

    return config;
}
```
