cache = LRUCache(maxsize=100)  # You can set this according to your needs.

class ConfigManager:
    def __init__(self):
        self.session = None

    @cached(cache)  # cachetools' decorator for caching results
    async def get_config(self, url):
        if not self.session:
            self.session = aiohttp.ClientSession()

        try:
            response = await self.session.get(url, timeout=10)  # Set appropriate timeout based on requirements
            response.raise_for_status()

            data = await response.text()
            extension = url.split('.')[-1]

            if extension == 'json':
                return json.loads(data)
            elif extension in ['yaml', 'yml']:
                return yaml.safe_load(data)
            else:
                # Handle other formats as needed. Note, xml is a bit more complex to parse.
                raise ValueError('Unsupported file format')

        except (aiohttp.ClientResponseError, aiohttp.ClientConnectorError) as e:
            print(f"Network error: {e}")

        finally:
            await self.session.close()
