#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define a data structure to hold the encryption context
typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[32];
} EncryptionContext;

// Function to initialize an AES-256-GCM cipher with a given password and salt value
int initEncryption(const char *password, const unsigned char *salt, size_t saltlen, EncryptionContext* encCtx) {
    if (password == NULL || salt == NULL || strlen(password) == 0 || saltlen == 0) {
        printf("Invalid password or salt\n");
        return -1;
    }

    // Derive the encryption key from the password and salt
    if (!EVP_PKEY_derive(encCtx->ctx, encCtx->key, &outlen) || outlen != 32) {
        printf("Failed to derive encryption key\n");
        return -1;
    }

    // Set the IV length to 96 bits (as required by GCM) and use the PBKDF2 algorithm with SHA-256
    if (!EVP_CIPHER_CTX_ctrl(encCtx->ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL)) {
        printf("Failed to set IV length\n");
        return -1;
    }

    // Enable key stretching for stronger security
    if (!EVP_CIPHER_CTX_set_key_length(encCtx->ctx, 32) ||
        !EVP_DigestInit(encCtx->ctx, EVP_sha256())) {
        printf("Failed to enable key stretching\n");
        return -1;
    }

    return 0;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanupEncryption(EncryptionContext* encCtx) {
    if (encCtx->ctx != NULL) {
        EVP_CIPHER_CTX_free(encCtx->ctx);
        encCtx->ctx = NULL;
    }
}
```
