import java.util.*;
import javax.cache.CacheManager;
import javax.naming.InitialContext;
import javax.naming.NamingException;

public class SessionCachingService {
    private Cache<String, Object> cache; // external session caching mechanism
    private ExternalSessionService service; // external session management service

    public SessionCachingService() throws NamingException {
        InitialContext ctx = new InitialContext();
        this.cache = (Cache<String, Object>) ctx.lookup("java:comp/env/session-cache");
        this.service = (ExternalSessionService) ctx.lookup("java:comp/env/external-session-service");
    }

    public void createSession(String sessionId, Object data) {
        cache.put(sessionId, data);
        service.createSession(sessionId, data);
    }

    public Object getSessionData(String sessionId) throws SessionNotFoundException {
        Object data = cache.getIfPresent(sessionId);

        if (data == null) { // not found in cache or expired
            data = service.fetchSessionData(sessionId);

            if (data != null) { // session exists on the external service
                cache.put(sessionId, data); // store in cache for future use
            } else { 
                throw new SessionNotFoundException("No active session with ID " + sessionId);
            }
        }

        return data;
    }

    public void updateSessionData(String sessionId, Object data) throws SessionNotFoundException {
        if (!cache.asMap().containsKey(sessionId)) { // not found in cache or expired
            throw new SessionNotFoundException("No active session with ID " + sessionId);
        }

        cache.put(sessionId, data); 
        service.updateSessionData(sessionId, data);
    }

    public void deleteSession(String sessionId) {
        cache.invalidate(sessionId); // remove from cache
        service.deleteSession(sessionId); // remove from external service
    }
}
``` 

