Here is a simple example of how you could solve this problem using JavaScript and NodeJS. This solution assumes that an external API has been set up for fetching metadata about each file.

```javascript
const fs = require('fs');
const path = require('path');
const fetch = require('node-fetch'); // Assuming we're using node-fetch for API requests

// Recursive function to read files in a directory
async function processDirectory(dirPath) {
    if (!fs.existsSync(dirPath)) throw new Error("Directory does not exist");

    let dirContent = fs.readdirSync(dirPath); // Synchronous read for simplicity
    let results = [];

    for (let i = 0; i < dirContent.length; i++) {
        const fullPath = path.join(dirPath, dirContent[i]);

        if (fs.statSync(fullPath).isDirectory()) {
            // Recursively process subdirectories
            results = results.concat(await processDirectory(fullPath));
        } else if ([".txt", ".md", ".json"].includes(path.extname(dirContent[i]))) {
            const fileStream = fs.createReadStream(fullPath);
            let fileContents = '';

            // Stream-based processing of large files
            fileStream.on('data', chunk => fileContents += chunk);
            fileStream.on('error', error => console.log("Error reading file: ", error));

            await new Promise((resolve, reject) => {
                fileStream.on('end', async () => {
                    try {
                        // Fetch metadata about each file from external API
                        let response = await fetch(`http://example.com/api/metadata?file=${fullPath}`);
                        if (!response.ok) throw new Error("Failed to fetch metadata");

                        let metadata = await response.json();
                        results.push({
                            path: fullPath, 
                            contents: fileContents, 
                            metadata: metadata,
                        });
                    } catch(error) {
                        console.log("Error fetching metadata: ", error);
                    } finally {
                        resolve();
                    }
                });
            });
        } else {
            console.log("Skipping file with invalid extension: ", fullPath);
        }
    }

    return results;
}
```

