public class FinancialReportGenerator {
    private static final Logger LOGGER = Logger.getLogger(FinancialReportGenerator.class.getName());
    private HashMap<String, String> cache;
    private ScheduledExecutorService scheduler;

    public FinancialReportGenerator() {
        this.cache = new HashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(() -> generateAndSendReports(), 0, 24, TimeUnit.HOURS);
    }

    public void generateReport(String stockSymbol) {
        try {
            String report = fetchFinancialDataFromAPI(stockSymbol);
            if (report != null) {
                saveToPDF(stockSymbol, report);
                cache.put(stockSymbol, report);
            }
        } catch (IOException ex) {
            LOGGER.log(Level.SEVERE, "Error fetching or saving data", ex);
        }
    }

    private void generateAndSendReports() {
        // Generate reports and send via email/sms 
    }

    private String fetchFinancialDataFromAPI(String stockSymbol) throws IOException {
        if (cache.containsKey(stockSymbol)) return cache.get(stockSymbol);

        URL url = new URL("https://api.example.com/data/" + stockSymbol);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        try {
            if (conn.getResponseCode() != 200) {
                LOGGER.log(Level.SEVERE, "Failed to fetch data from API");
                return null;
            }

            InputStream is = conn.getInputStream();
            BufferedReader br = new BufferedReader(new InputStreamReader(is));
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line);
            }
            return sb.toString();
        } finally {
            conn.disconnect();
        }
    }

    private void saveToPDF(String stockSymbol, String reportData) throws IOException {
        PDDocument doc = new PDDocument();
        PDPage page = new PDPage();
        doc.addPage(page);

        PDFont font = PDType1Font.HELVETICA_BOLD;
        PDPageContentStream contentStream = new PDPageContentStream(doc, page);
        contentStream.beginText();
        contentStream.setFont(font, 12);
        contentStream.newLineAtOffset(50, 700);
        contentStream.showText("Stock: " + stockSymbol);
        contentStream.newLine();
        contentStream.showText(reportData);
        contentStream.endText();
        contentStream.close();

        doc.save("/path/to/pdf/" + stockSymbol + ".pdf");
        doc.close();
    }
}
