```C
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <yaml.h> // library to parse YAML, will need to be installed separately
#include <jansson.h> // library to work with JSON in C, install via package manager (libjansson-dev on Ubuntu)

// Defining the structure of your transaction and factory functions would go here
typedef struct Transaction {
    char* id;
    void (*factory)(struct Transaction *);
} Transaction;

pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;
// Implementing the hashmap that will store your factory functions would go here. 
// You could use an array of linked lists or a balanced binary search tree (like Red-Black Tree) for this purpose.

void* filterTransactions(void* arg) {
    // This function is thread safe because it uses pthreads rwlock to handle concurrent reads and writes.
    Transaction* txn = (Transaction*)arg;

    pthread_rwlock_rdlock(&lock);
    // Retrieve factory function from hashmap using transaction id here

    pthread_rwlock_unlock(&lock);

    // Call the retrieved factory function on transaction
    txn->factory(txn);
}
```

