use std::fs;
use std::path::PathBuf;
use tokio::sync::Mutex;
use std::time::Duration;
use serde_json::Value as JsonValue;
use anyhow::Result;
use std::env;
use std::thread;
use tokio::time::{sleep, delay_for};
use log::info;
use serde_json::from_str;
use lazy_static::lazy_static;
use regex::Regex;

#[derive(Deserialize)]
struct Config {
    max_retries: usize,
    backoff_intervals: Vec<u64>,
    cleanup_timeout: u64,
}

lazy_static start{
    static ref CONFIG: Mutex<Config> = Mutex::new(read_config().unwrap());
}

async fn create_dir(name: &str) -> Result<PathBuf> {
    let dir = PathBuf::from(&env::var("MY_VAR")?);
    if dir.exists() && dir.is_dir() {
        return Ok(dir);
    }

    for i in 0..CONFIG.lock().await.max_retries {
        let res = create_dir_inner(&dir, &name).await;

        match res {
            Err(_) => {
                info![&format!"Directory creation failed (attempt #{i+1}): {:?}", res];

                if i < CONFIG.lock().await.max_retries - 1 {
                    delay_for(Duration::from_secs(CONFIG.lock().await.backoff_intervals[i])).await;
                } else {
                    return Err(res);
                }
            },
            Ok(_) => return res,
        }
    }

    unreachable();
}

async fn create_dir_inner(path: &PathBuf, name: &str) -> Result<PathBuf> {
    if validate(&name)? {
        let dir = path.join(name);
        fs::create_dir_all(&dir)?;

        thread::spawn(move || cleanup(path, CONFIG.lock().await.cleanup_timeout));

        return Ok(dir);
    } else {
        Err(anyhow::Error::msg("Invalid directory name"))
    }
}

async fn validate(name: &str) -> Result<()> {
    let config = read_config().await?;

    if !Regex::new(&config.illegal_chars).unwrap().is_match(name) {
        return Err(anyhow::Error::msg("Directory name contains illegal characters"));
    } else if name.len() > config.max_dir_length {
        return Err(anyhow::Error::msg("Directory name exceeds maximum length"));
    }

    Ok(())
}

fn cleanup(path: PathBuf, timeout: u64) {
    sleep(Duration::from_secs(timeout)).await;
    fs::remove_dir_all(&path).unwrap();
}

async fn read_config() -> Result<Config> {
    let config = std::fs::read_to_string("config.json")?;
    Ok(from_str(&config)?)
}
```
Note that this code does not handle race conditions in a thread-safe manner, but it's beyond the scope of this example. Also, there are many things which can be improved here. For instance, the error handling and logging could be made more robust. The code also lacks proper cleanup after directory creation failures and cleanups.

