import java.util.*;
import javax.crypto.*;
import javax.net.ssl.*;
import java.io.*;
import java.nio.charset.*;
import org.apache.commons.codec.binary.*;

public class SecureChatApplication {

  private SSLSocket socket;
  private PrintWriter out;
  private BufferedReader in;

  public void connect(String hostname, int port) throws Exception {
    SSLContext context = SSLContext.getInstance("TLS");
    context.init(null, null, null);

    socket = (SSLSocket) context.getSocketFactory().createSocket(hostname, port);
    out = new PrintWriter(socket.getOutputStream(), true);
    in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
  }

  public void sendMessage(String msg) throws Exception {
    byte[] cipherText = encryptUsingAES(msg, "secretkey");
    String base64EncodedCipher = Base64.encodeBase64String(cipherText);
    out.println(base64EncodedCipher);
  }

  public String receiveMessage() throws Exception {
    String base64EncodedCipher = in.readLine();
    byte[] cipherText = Base64.decodeBase64(base64EncodedCipher);
    return decryptUsingAES(cipherText, "secretkey");
  }

  private static byte[] encryptUsingAES(String data, String keyStr) throws Exception {
    SecretKeySpec secretKey = new SecretKeySpec(keyStr.getBytes(), "AES");

    Cipher cipher = Cipher.getInstance("AES");
    cipher.init(Cipher.ENCRYPT_MODE, secretKey);

    return cipher.doFinal(data.getBytes());
  }

  private static String decryptUsingAES(byte[] cipherText, String keyStr) throws Exception {
    SecretKeySpec secretKey = new SecretKeySpec(keyStr.getBytes(), "AES");

    Cipher cipher = Cipher.getInstance("AES");
    cipher.init(Cipher.DECRYPT_MODE, secretKey);

    byte[] original = cipher.doFinal(cipherText);
    return new String(original);
  }

}
```
