<?php
class UserProfile {
    private $cache;
    private $db;

    public function __construct($cache, $db) {
        $this->cache = $cache;
        $this->db = $db;
    }

    // Fetches user profile from the cache or database.
    public function getProfile($userId) {
        if ($profile = $this->cache->get("user:$userId")) {
            return $profile;
        } else {
            $profile = $this->db->fetch('SELECT * FROM users WHERE id = ?', [$userId]);
            $this->cache->set("user:$userId", $profile); // Caching the profile for future use.
            return $profile;
        }
    }

    // Updates user profile and sync with external social media platforms.
    public function updateProfile($userId, $updates) {
        $this->db->update('UPDATE users SET ? WHERE id = ?', [$updates, $userId]);
        $profile = $this->getProfile($userId); // Fetch the updated profile.

        // Sync with external social media platforms.
