```java
import java.util.HashMap;

public class BitmapCache {
    private final HashMap<String, Bitmap> cache = new HashMap<>();
    private final Object lock = new Object();

    public Bitmap getBitmap(final String url) {
        synchronized (lock) {
            if (!cache.containsKey(url)) {
                return null;
            }

            // Move the accessed bitmap to the end of list, indicating it was recently used
            final Bitmap value = cache.get(url);
            putBitmap(url, value);
            return value;
        }
    }

    public void putBitmap(final String url, final Bitmap bitmap) {
        synchronized (lock) {
            // If the cache is full, remove the oldest item
            if (cache.size() >= capacity) {
                Iterator<Entry<String, Bitmap>> iter = cache.entrySet().iterator();
                if (iter.hasNext()) {
                    Entry<String, Bitmap> entry = iter.next();
                    iter.remove();
                    // Handle the evicted bitmap here if needed
                }
            }

            cache.put(url, bitmap);
        }
    }
}
```
