import java.util.*;
import java.util.concurrent.*;

public class NetworkLatencySimulator {
    private static final int DEFAULT_RANGE = 100;

    // Cache map for latency values with thread safety and high concurrency 
    private ConcurrentHashMap<Integer, Double> cache = new ConcurrentHashMap<>();
    private Random randomGenerator = new Random();
    private String distributionType = "normal";
    private int range = DEFAULT_RANGE;

    public NetworkLatencySimulator() {
        // Initialization code can go here
    }

    public void setDistribution(String type, int param) {
        this.distributionType = type;
        this.range = param;
    }

    public double getRandomLatencyInMilliseconds() {
        if (cache.isEmpty()) {
            cache.put(0, generateNormalDistribution());  // Replace with other distribution types
        } else {
            int randomKey = randomGenerator.nextInt(range);
            if (!cache.containsKey(randomKey)) {
                double latencyValue = cache.getOrDefault(randomKey - 1, (double) range) + generateNormalDistribution();
                cache.put(randomKey, latencyValue);
            }
        }

        return cache.get(randomGenerator.nextInt(range));
    }

    private double generateNormalDistribution() {
        // This is a place holder for actual implementation based on your requirements
        if (this.distributionType == "normal"){
            return randomGenerator.nextGaussian();
        }
        throw new IllegalArgumentException("Unsupported distribution type: " + this.distributionType);
    }

    @Override
    public String toString() {
        return "NetworkLatencySimulator{" +
                "range=" + range +
                ", distributionType='" + distributionType + '\'' +
                '}';
    }
}
