```C++
#include <iostream>
#include "opencv2/highgui.hpp"
#include "jsoncpp/json/json.h"

int convertToPDF(std::string input_dir, std::string config_file, std::string output_dir) {
    // load JSON configuration file
    Json::Value root;
    std::ifstream config_doc(config_file, std::ifstream::binary);
    config_doc >> root;

    int successes = 0;
    for (auto &p : fs::directory_iterator(input_dir)) {
        try {
            // load image and apply rules from JSON file
            cv::Mat img = cv::imread(p.path().string(), 1);

            // resize if needed
            int targetWidth = root["width"].asInt();
            if (img.cols != targetWidth) {
                double scaleFactor = static_cast<double>(targetWidth) / img.cols;
                cv::resize(img, img, cv::Size(), scaleFactor, scaleFactor, cv::INTER_LINEAR);
            }

            // convert to PDF format and save to output directory
            std::vector<int> compressionParams;
            compressionParams.push_back(cv::IMWRITE_PDF_PICTURE_INCREASE_SIZE_BY);
            cv::imwrite(output_dir + p.path().stem() + ".pdf", img, compressionParams);

            successes++;
        } catch (std::exception &e) {
            std::cerr << "Error converting image: " << e.what() << std::endl;
        }
    }

    return successes;
}
