```csharp
using System;
using System.Xml.XPath;
using System.Xml;
public static XmlNode GetElement(string name, string xml) {
    var navigator = new XPathDocument(new XmlTextReader(xml)).CreateNavigator();
    var iterator = navigator.SelectDescendants("*", "", false);
    int count = 0;
    XmlNode node = null;
    while (iterator.MoveNext()) {
        if (iterator.Current.LocalName == name) {
            if(count > 1){
                throw new Exception("Multiple elements found");
            } 
            if(node != null){
                return node;
            } else{
                count++;
                node = iterator.Current as XmlNode;
            }
        }
    }

    if (count == 0) {
        throw new Exception("No elements found");
    } 

    return node;
}
```
