import os
from abc import ABCMeta, abstractmethod
from threading import Lock

class BaseStorageBackend(metaclass=ABCMeta):
    @abstractmethod
    def read_file(self, filepath):
        pass

class NFSBackend(BaseStorageBackend):
    def read_file(self, filepath):
        try:
            with open(filepath) as f:
                return f.read()
        except Exception as e:
            raise RuntimeError("Failed to load config from NFS") from e

class HDFSBackend(BaseStorageBackend):
    def read_file(self, filepath):
        try:
            # Assuming you are using hdfs3 library. This is a placeholder for real-world implementation.
            client = HDFileSystem("default")
            return client.open(filepath).read()
        except Exception as e:
            raise RuntimeError("Failed to load config from HDFS") from e

class ConfigurationManager:
    def __init__(self, backend):
        self._backend = backend
        self._cache = {}
        self._lock = Lock()

    def get_config(self, filepath):
        with self._lock:
            if filepath in self._cache:
                return self._cache[filepath]

            try:
                config = self._backend.read_file(filepath)
                self._cache[filepath] = config
            except Exception as e:
                raise RuntimeError("Failed to load configuration file") from e

        return config

    def set_storage_backend(self, backend):
        with self._lock:
            self._backend = backend
