    let results: Vec<Value> = stream::iter(endpoints)
        .map(|e| async move { api.get_data(&e).await })
        .buffer_unordered(100)  // Up to 100 concurrent requests
        .collect()
        .await;

    let mut cache = RwLock::new(BTreeMap::new());

    for result in results {
        match result {
            Ok(data) => {
                let data_clone = data.clone();

                // Cache response for future requests with the same endpoint
                if let Some(cached_value) = cache.read().await.get(&endpoint) {
                    printlnfelt", "Cached value: {}", cached_value);
                } else {
                    cache.write().await.insert(endpoint, data_clone);
                    printlnfelt", "Data from API: {}", data);
                }
            },
            Err(e) => eprintlnfelt", "Error fetching data: {}", e),
        }
    }
}
```
