    @Autowired 
    private AccountRepository accountRepo;
    @Autowired 
    private EmailNotificationService emailNotifyService;
    @Autowired 
    private FraudDetectionService fraudDetectService;

    // Retry logic for network failures with a backoff strategy.
    @Retryable(maxAttempts = 3, backoff = @Backoff(delay = 100))
    public Transaction processTransaction(String transactionId, String customerId, 
                                          double amount, String type, LocalDateTime timestamp) {
        // Validate the inputs and get the customer details.
        Customer customer = accountRepo.findCustomerById(customerId);
        if (customer == null) {
            throw new IllegalArgumentException("Invalid customer ID");
        }

        // Check fraud risk for this transaction. 
        FraudRiskLevel riskLevel = fraudDetectService.evaluateTransaction(amount, type);
        if (riskLevel != FraudRiskLevel.NORMAL) {
            throw new TransactionRejectedException("Fraud detected");
        }

        // Perform the transaction and update the account balance atomically.
        Account account = accountRepo.findAccountByCustomerId(customerId);
        synchronized (account) {
           // Update balance and add the new transaction to the history. 
           // Assume the logic for this step is implemented in a method 'performTransaction'.
           Transaction transaction = performTransaction(amount, type, timestamp, account);

           // Send confirmation emails to customer.
           emailNotifyService.sendEmailConfirmation(customer, transaction);

           return transaction; 
        }
    }

    private Transaction performTransaction(double amount, String type, LocalDateTime timestamp, Account account) {
        // Your logic for updating the balance and adding new transactions to history.
    }
}
