        g_printerr("Failed to create output directory: %s\n", output_dir);
        return 1;
    }

    // Create a new thread pool with the desired number of worker threads.
    GThreadPool *pool = g_thread_pool_new(g_thread_pool_get_max_threads(), FALSE, NULL);

    // Enumerate all image files in input directory and convert them to PDF in parallel using GAsync.
    GDir *dir = g_dir_open(input_dir, 0, &error);
    if (!dir) {
        g_printerr("Failed to open directory: %s\n", error->message);
        return 1;
    }

    const gchar *name;
    GAsyncQueue *queue = g_async_queue_new();
    while ((name = g_dir_read_name(dir)) != NULL) {
        // Only process image files.
        if (g_str_has_suffix(name, ".jpg") || g_str_has_suffix(name, ".png") || g_str_has_suffix(name, ".gif")) {
            gchar *input = g_build_filename(input_dir, name, NULL);
            gchar *output = g_build_filename(output_dir, name, ".pdf", NULL);

            // Enqueue file for conversion in the thread pool.
            g_async_queue_push(queue, input);
            g_thread_pool_push(pool, image_convert, output, error);
        }
    }

    while (!g_async_queue_is_empty(queue)) {
        // Show progress indicator.
        printf("Progress: %lu/%d\n", queue->length, g_strv_length((char **) g_dir_read_name(dir)));
        // Allow other threads to run before next iteration.
        g_usleep(1000);
    }

    g_thread_pool_free(pool, FALSE, TRUE);
    return 0;
}
