```c
#include <stdio.h>
#include <pthread.h>
#include <errno.h>
#include "zlib.h"

// Define the struct to hold resource bundle info
typedef struct ResourceBundle {
    char* name;  // Name of the bundle
    void* data;  // Pointer to the data in memory
    size_t size; // Size of the data
} ResourceBundle;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ResourceBundle* loadBundle(char* bundleName) {
    pthread_mutex_lock(&lock);  // Lock to prevent concurrent access

    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        printf("Failed to allocate memory for bundle: %s\n", strerror(errno));
        pthread_mutex_unlock(&lock);  // Unlock before returning
        return NULL;
    }

    FILE* file = fopen(bundleName, "rb");
    if (file == NULL) {
        printf("Failed to open bundle: %s\n", strerror(errno));
        free(bundle);  // Free memory before returning on error
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    fseek(file, 0L, SEEK_END);
    bundle->size = ftell(file);
    rewind(file);

    bundle->data = malloc(bundle->size * sizeof(char));
    if (bundle->data == NULL) {
        printf("Failed to allocate memory for data: %s\n", strerror(errno));
        free(bundle);  // Free memory before returning on error
        fclose(file);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    if (fread(bundle->data, sizeof(char), bundle->size, file) != bundle->size) {
        printf("Failed to read data from bundle: %s\n", strerror(errno));
        free(bundle);  // Free memory before returning on error
        fclose(file);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
    return bundle;
}
```
