```php
class AuthenticationService {
    private $apiUrl;
    private $hashingAlgorithm = PASSWORD_DEFAULT; // default hashing algorithm
    private $saltLength = 16; // Default salt length
    private $errorMsg = '';

    public function __construct($userManagementApi) {
        $this->apiUrl = $userManagementApi;
        session_start();
    }

    /** 
     * Generate a secure random string of specified length for user salts.
     */
    private function generateSalt($length = 16) {
        $bytes = openssl_random_pseudo_bytes($length / 2); // divide by two as hexadecimal representation uses twice the characters
        return bin2hex($bytes);
    }

    /**
     * Register a new user
     */
    public function registerUser($username, $password, $salt = null) {
        $data = [
            'username' => $username,
            'hashed_password' => password_hash($this->generateSalt($this->saltLength).$password.$salt ?: '', $this->hashingAlgorithm),
        ];

        $options = [
            CURLOPT_URL => $this->apiUrl . "/register",
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_POST => true,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
            CURLOPT_POSTFIELDS => json_encode($data),
        ];

        $ch = curl_init();
        curl_setopt_array($ch, $options);
        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            $this->errorMsg = 'Error: ' . curl_error($ch);
            return false;
        }
        curl_close($ch);

        $decodedResponse = json_decode($response, true);
        if (!isset($decodedResponse['success']) || !$decodedResponse['success']) {
            $this->errorMsg = $decodedResponse['message'];
            return false;
        }

        return true;
    }

    /** 
     * Login a user.
     */
    public function loginUser($username, $password, $salt = null) {
        $data = [
            'username' => $username,
        ];

        $options = [
            CURLOPT_URL => $this->apiUrl . "/login",
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_POST => true,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
            CURLOPT_POSTFIELDS => json_encode($data),
        ];

        $ch = curl_init();
        curl_setopt_array($ch, $options);
        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            $this->errorMsg = 'Error: ' . curl_error($ch);
            return false;
        }
        curl_close($ch);

        $decodedResponse = json_decode($response, true);
        if (!isset($decodedResponse['success']) || !$decodedResponse['success']) {
            $this->errorMsg = $decodedResponse['message'];
            return false;
        }

        // Compare hashed passwords.
        $hashedPasswordFromDB = $decodedResponse['hashed_password'];
        $providedHashedPassword = password_hash($this->generateSalt($this->saltLength).$password.$salt ?: '', $this->hashingAlgorithm);

        if (password_verify($hashedPasswordFromDB, $providedHashedPassword)) {
            $_SESSION['username'] = $username;
            return true;
        } else {
            $this->errorMsg = 'Incorrect username or password.';
            return false;
        }
    }

    /** 
     * Get the last error message.
     */
    public function getLastError() {
        return $this->errorMsg;
    }
}
```
