#include <stdio.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10
#define MAX_PAGES 20
#define MAX_RESOLUTION 300

int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf, int numThreads) {
    DIR *dir;
    struct dirent *ent;
    char inputFile[512], outputFile[512];
    FILE *pipein_fd, *pipeout_fd;
    pthread_t threadid[MAX_THREADS];

    if((dir = opendir(inputDir)) == NULL) {
        printf("Could not open input directory.\n");
        return 1;
    }

    while((ent = readdir(dir)) != NULL) {
        // Ignore hidden files
        if (ent->d_name[0] == '.') continue;

        sprintf(inputFile, "%s/%s", inputDir, ent->d_name);

        struct stat st;
        stat(inputFile, &st);
        // Check if regular file or symbolic link to a regular file
        if(!S_ISREG(st.st_mode) && !S_ISLNK(st.st_mode)) {
            printf("%s is not a regular file.\n", ent->d_name);
            continue;
        }

        // Validate file type (JPEG or PNG)
        char *ext = strrchr(inputFile, '.');
        if (strcmp(ext, ".jpg") != 0 && strcmp(ext, ".jpeg") != 0 && strcmp(ext, ".png") != 0) {
            printf("%s is not a valid image file.\n", ent->d_name);
            continue;
        }

        // Prepare output file path
        sprintf(outputFile, "%s/%s.pdf", outputDir, ent->d_name);

        // System call to execute third-party tool
        char command[1024];
        sprintf(command, "third-party-tool %s %s --pages %lu --resolution %d", inputFile, outputFile, maxPagesPerPdf, MAX_RESOLUTION);

        pipein_fd = popen(command, "r");  // read from command's stdout
        if (pipein_fd == NULL) {
            printf("Failed to execute command.\n");
            return 2;
        }

        int c;
        while ((c = fgetc(pipein_fd)) != EOF) {
            // Read and process output from third-party tool
        }

        pclose(pipein_fd);
    }

    closedir(dir);
    return 0;
