int DES_ECB_encrypt (const unsigned char *plaintext, const int plaintext_len, 
                     const DES_cblock key, unsigned char **ciphertext) {
    DES_key_schedule schedule;
    DES_set_key_unchecked(&key, &schedule);

    *ciphertext = malloc(plaintext_len);
    if (*ciphertext == NULL) {
        printf("Failed to allocate memory for ciphertext\n");
        return 0;
    }

    DES_ecb_encrypt((unsigned char *)plaintext, *ciphertext, &schedule, 1);
    OPENSSL_cleanse(&key, sizeof(key)); /* Clear sensitive data */

    return 1;
}

int DES_ECB_decrypt (const unsigned char *ciphertext, const int ciphertext_len, 
                     const DES_cblock key, unsigned char **plaintext) {
    DES_key_schedule schedule;
    DES_set_key_unchecked(&key, &schedule);

    *plaintext = malloc(ciphertext_len);
    if (*plaintext == NULL) {
        printf("Failed to allocate memory for plaintext\n");
        return 0;
    }

    DES_ecb_encrypt((unsigned char *)ciphertext, *plaintext, &schedule, 1);
    OPENSSL_cleanse(&key, sizeof(key)); /* Clear sensitive data */

    return 1;
}
