Here's an example of how you might implement this in C# using `ConcurrentDictionary`, `Parallel.ForEach` for parallel processing, `SHA256Managed` for calculating file hashes and a custom exception to handle potential I/O exceptions from the operations. Note that this is a basic implementation and may need additional improvements based on your specific needs.

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileComparator 
{
    // List of file extensions to exclude from comparison
    private static readonly string[] ExcludedExtensions = { ".txt" };

    public ConcurrentDictionary<string, string> CompareDirectories(string path1, string path2) 
    {
        var dict1 = GetFilesWithChecksums(path1);
        var dict2 = GetFilesWithChecksums(path2);

        // Determine files that are only in the first directory.
        foreach (var filePathInDict1 in dict1.Keys.Except(dict2.Keys)) 
        {
            Console.WriteLine("Only in first directory: " + filePathInDict1);
        }

        // Determine files that are only in the second directory.
        foreach (var filePathInDict2 in dict2.Keys.Except(dict1.Keys)) 
        {
            Console.WriteLine("Only in second directory: " + filePathInDict2);
        }

        // Determine files that are in both directories, but with different checksums.
        foreach (var kvp in dict1) 
        {
            if (!dict2.TryGetValue(kvp.Key, out var checksum2) || checksum2 != kvp.Value) 
            {
                Console.WriteLine("Different content: " + kvp.Key);
            }
        }

        return dict1; // return the first directory's files with checksums
    }

    private ConcurrentDictionary<string, string> GetFilesWithChecksums(string path) 
    {
        var files = Directory.EnumerateFiles(path, "*", SearchOption.AllDirectories)
                             .Where(file => !ExcludedExtensions.Contains(Path.GetExtension(file)));

        var dict = new ConcurrentDictionary<string, string>();

        Parallel.ForEach(files, file => 
        {
            try 
            {
                var checksum = CalculateFileChecksum(file);
                dict.TryAdd(file, checksum);
            } 
            catch (IOException ex) 
            {
                Console.WriteLine("I/O exception: " + ex.Message);
            }
        });

        return dict;
    }

    public string CalculateFileChecksum(string filename) 
    {
        using (var sha256 = SHA256.Create())
        {
            using (var stream = File.OpenRead(filename))
                return BitConverter.ToString(sha256.ComputeHash(stream)).Replace("-", "").ToLower();
        }
    }
}
```
To use this class and compare two directories, you could do something like:

```csharp
