```C
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>
#include <jansson.h>
#include <openssl/ssl.h>

struct string {
  char *ptr;
  size_t len;
};

void init_string(struct string *s) {
  s->len = 0;
  s->ptr = malloc(s->len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

int verifyToken(char *token) {
  CURL *curl;
  CURLcode res;

  curl = curl_easy_init();
  if(curl) {
    struct string s;
    init_string(&s);

    char url[256];
    sprintf(url, "https://your-token-verification-service/?token=%s", token);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

    res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
      // Assuming the verification service returns JSON response in format {"valid": true/false}
      json_t *root = json_loads(s.ptr, 0, NULL);

      if(!json_is_object(root)) {
        fprintf(stderr, "error: on line %d: %s\n", __LINE__, json_typeof_string(root));
        return -1;
      }

      json_t *valid = json_object_get(root, "valid");
      if(!json_is_boolean(valid)) {
        fprintf(stderr, "error: on line %d: not a boolean\n", __LINE__);
        return -1;
      }

      int isValid = json_boolean_value(valid);

      if (isValid == 0) 
        printf("Token is invalid.\n");
      else
        printf("Token is valid.\n");
    }

    free(s.ptr);

    curl_easy_cleanup(curl);
  }

  return 0;
