```java
import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.model.ObjectMetadata;
import com.microsoft.azure.storage.blob.*;
import com.google.cloud.storage.*;
import org.apache.commons.io.FileUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class CloudStorageServiceManager {
    private static final Logger logger = LogManager.getLogger(CloudStorageServiceManager.class);

    // Use LRU Cache to store recently used metadata and hashes
    private Map<String, ObjectMetadata> cache;
    int cacheSize = 1024; 

    public CloudStorageServiceManager() {
        this.cache = new LinkedHashMap<String, ObjectMetadata>(cacheSize, .75F, true) {
            protected boolean removeEldestEntry(Map.Entry eldest) {
                return size() > cacheSize;
            }
        };
    }

    public void cloudStorageServiceManager(String filePath, String bucketName, 
                         String directoryPath, String targetCloudStorageService) throws Exception {

        File file = new File(filePath);
        if (!file.exists()) throw new FileNotFoundException("File not found");

        MessageDigest md = MessageDigest.getInstance("SHA-256");
        InputStream fis = new FileInputStream(file);

        String hash = checksum(fis, md);

        if (cache.containsKey(hash)) {
            logger.info("File already present in specified location.");
            return;
        }

        ObjectMetadata metadata = new ObjectMetadata();
        // Populate the metadata with your details

        cache.put(hash, metadata);

        switch (targetCloudStorageService) {
            case "S3":
                AmazonS3 s3Client = AmazonS3ClientBuilder.defaultClient(); 
                PutObjectRequest request = new PutObjectRequest(bucketName, directoryPath, file);

                // Add more validation rules here...

                s3Client.putObject(request);
                break;
            case "Azure Blob Storage":
                CloudBlobContainer container = 
                    blobClient.getContainerReference(bucketName);
                CloudBlockBlob blob = container.getBlockBlobReference(directoryPath);

                // Add more validation rules here...

                blob.upload(fis, file.length());
                break;
            case "Google Cloud Storage":
                Storage storage = StorageOptions.newBuilder().setProjectId("{project-id}").build().getService();
                BlobId blobId = BlobId.of(bucketName, directoryPath);
                BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build();

                // Add more validation rules here...

                storage.create(blobInfo, Files.readAllBytes(file.toPath()));
                break;
            default: 
                throw new IllegalArgumentException("Unsupported cloud storage service");
        }

    }

    private String checksum(InputStream fis, MessageDigest md) throws IOException {
        byte[] dataBytes = new byte[1024];
        int nread = 0; 
        while ((nread = fis.read(dataBytes)) != -1) {
            md.update(dataBytes, 0, nread);
        };

        byte[] mdbytes = md.digest();
        return new String(mdbytes);
    }

}
```
