    public async Task<bool> ValidateUserAsync(string username, string password)
    {
        User user = null;

        if (!_cache.TryGetValue("ValidationRules", out user))
        {
            var response = await _httpClient.GetStringAsync("https://api.example.com/validation-rules");
            user = JsonConvert.DeserializeObject<User>(response);

            // Set cache options. 
            var cacheEntryOptions = new MemoryCacheEntryOptions()
                .SetSlidingExpiration(TimeSpan.FromSeconds(60));

            _cache.Set("ValidationRules", user, cacheEntryOptions);
        }

        // Validate the user based on retrieved validation rules
        return user != null && 
               string.Equals(username, user.UserName, StringComparison.OrdinalIgnoreCase) && 
               password == user.Password;
    }
}
