    public async Task InvokeAsync(HttpContext context, RequestDelegate next) {
        var cmsProvider = _cmsProviderFactory.Create();

        try {
            await cmsProvider.UpdateContentAsync(context);

            // Compress and transfer the data to remote database server
            var contentBytes = GetBytesFromContext(context);
            using (var memoryStream = new MemoryStream()) {
                await _compressor.Compress(contentBytes, memoryStream);

                // Transfer compressed data...
            }
        } catch (Exception ex) when (!(ex is OperationCanceledException)) {
            _logger.LogError(ex, "An error occurred while updating the content.");

            // Handle and return error to client...
        }

        await next(context);
    }

    private byte[] GetBytesFromContext(HttpContext context) { /* Convert HTTP Context data to byte array */ }
}
