use std::fs;
use std::time::Instant;
use std::process::Command;
use serde_json::Value;

pub fn compile(source_files: Vec<String>) -> Value {
    let mut results = vec![];

    for file in source_files {
        let before = get_memory();
        let start_time = Instant::now();

        // Run the compilation command and capture the output.
        let output = Command::new("rustc")
            .arg(file)
            .output()
            .expect("Failed to execute rustc");

        let end_time = start_time.elapsed();
        let after = get_memory();

        // Parse the warnings and errors from the output.
        let mut diagnostics: Vec<(&'static str, String)> = vec![];
        for line in std::str::from_utf8(&output.stderr).unwrap().lines() {
            if line.contains("warning") {
                diagnostics.push(("WARNING", line.to_string()));
            } else if line.contains("error") {
                diagnostics.push(("ERROR", line.to_string()));
            }
        }

        let result = json![{
            "source file": file,
            "before memory usage": before,
            "after memory usage": after,
            "compilation time": end_time.as_millis(),
            "diagnostics": diagnostics,
        }];

        results.push(result);
    }

    json![{
        "results": results,
    }]
}

fn get_memory() -> u64 {
    let memory = fs::read_to_string("/proc/self/status")
        .unwrap()
        .lines()
        .filter(|s| s.contains("VmRSS"))
        .next()
        .unwrap();

    // The VmRSS line is of format "VmRSS:<memory> kB"
    let memory = memory.split(' ').collect::<Vec<&str>>()[1];
    memory.parse().unwrap()
}
```
