// Spatial hash grid that divides space into buckets and handles concurrent point insertions.
class HashGrid {
public:
    void insert(const Point3D& p) {
        std::size_t bucketIndex = hashFunction(p);

        // Use mutex to prevent concurrent modification of the grid structure
        std::lock_guard<std::mutex> lock(mMutex);

        if (bucketIndex >= mBuckets.size())  {
            resizeAndRehash();
        }

        while (!mBuckets[bucketIndex]->insert(p)) { // retry until successful insertion or resizing needed
            resizeAndRehash();
            bucketIndex = hashFunction(p);
        }
    }

private:
    void resizeAndRehash() {
        std::lock_guard<std::mutex> lock(mMutex); // ensure only one thread at a time resizes the grid

        int oldSize = mBuckets.size();
        int newSize = 2 * oldSize; // for simplicity, double size each time
        std::vector<std::unique_ptr<Bucket>> newBuckets(newSize);

        for (int i = 0; i < newSize; ++i) {
            newBuckets[i] = std::make_unique<Bucket>();
        }

        // Rehash points from old buckets to the new ones based on their hashes
        for (const auto& bucket : mBuckets) {
            for (const Point3D& p : bucket->getPoints()) {
                std::size_t newIndex = hashFunction(p) % newSize;
                newBuckets[newIndex]->insert(p);
            }
        }

        mBuckets = std::move(newBuckets); // Replace old buckets with the resized and rehashed ones.
    }

    std::size_t hashFunction(const Point3D& p) { /* Implement your preferred hashing algorithm */ };

private:
    std::vector<std::unique_ptr<Bucket>> mBuckets; // Vector of buckets, can be resized dynamically.
    std::mutex mMutex; 
};
