```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

char *modifyFileName(const char *filename) {
    if (!filename || strlen(filename) == 0) {
        printf("Error: filename cannot be empty\n");
        return NULL;
    }

    int digitCount = 0, dotCount = 0, i = -1;
    while (filename[++i]) {
        if (!isalnum(filename[i])) {
            if (filename[i] == '.') {
                dotCount++;
            } else {
                printf("Error: Invalid character in filename\n");
                return NULL;
            }
        }
        if (isdigit(filename[i])) digitCount++;
    }

    char *baseName = malloc(strlen(filename) + 1); // extra byte for null termination
    strcpy(baseName, filename);

    if (dotCount > 0) {
        baseName[strrchr(baseName, '.') - baseName] = '\0'; // cut the extension part of filename
    }

    char *extension;
    int newExtensionLength;
    switch (digitCount) {
        case 3:
            extension = "jpg";
            newExtensionLength = 3;
            break;
        case 4:
            extension = "png";
            newExtensionLength = 3;
            break;
        default:
            if (digitCount > 4) {
                baseName[5] = '\0'; // truncate filename
                extension = "bmp";
                newExtensionLength = 3;
            } else {
                extension = "txt";
                newExtensionLength = 3;
            }
    }

    char *newFilename = malloc(strlen(baseName) + newExtensionLength + 2); // extra 1 for dot, and another 1 for null termination
    sprintf(newFilename, "%s.%s", baseName, extension);

    free(baseName);

    return newFilename;
}
```
This function works by first checking if the filename is valid (not empty and contains only alphanumeric characters or a dot for file extensions). Then it counts the number of digits in the filename. Depending on these counts, it determines the extension to be added to the filename. The original filename without its extension is stored in `baseName`. After determining the new extension length and content, a memory block is allocated for the new filename, which includes space for the dot separator between the base name and the extension. Finally, sprintf is used to concatenate these two strings into the final result, and this dynamically allocated string is returned. 

The caller of this function is responsible for freeing the memory when it's no longer needed using `free`. This code does not include unit tests or performance optimizations as they are quite large tasks in themselves and would make this answer too long. However, they should be easy to implement based on this starting point.

