To run multiple threads concurrently:
```c
int main() {
    int numFiles = 2; // Number of files to read
    char* filenames[numFiles];

    // Initialize mutex
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("Mutex init has failed\n");
        return 1;
    }

    pthread_t threads[numFiles];
    int i;
    for(i = 0; i < numFiles; i++){
       // Fill filenames array here
       pthread_create(&threads[i], NULL, readFile, (void*)filenames[i]);
    }

    for(i = 0; i < numFiles; i++) {
        pthread_join(threads[i], NULL);
    }

    // Destroy mutex after usage
    pthread_mutex_destroy(&lock);
}
