```rust
extern crate chrono;
use std::process::{Command, exit};
use std::fs::File;
use std::io::prelude::*;
use chrono::Timelike;
use log::{info, error};
use std::env;
use std_hooks::SyncLazy;

const MAX_RSS: u64 = 1024 * 1024 * 512; // 512MB

fn measure_compile(filepath: &str) -> Result<i32, String> {
    let process = if let Ok(process) = Command::new("rustc").arg(filepath).spawn() {
        process
    } else {
        return Err("Failed to spawn compiler".to_string());
    };

    let before_rss = get_resident_set_size();
    if before_rss > MAX_RSS {
        error.log(&format![
            "Resident set size {} exceeds maximum allowed value {}", 
            before_rss, MAX_RSS
        ]);
        process.kill().unwrap();
        return Err("Process killed".to_string());
    }

    info.log(filepath);

    let now = chrono::Local::now();
    let status = match rustc_driver::catch_with_exit_code(|| process.wait(), |e| {
        error.log(&format![
            "Compilation failed for file {} with error: {}", 
            filepath, e
        ]);
        1
    }) {
        Ok(_) => "Success",
        Err(exit_code) => return Err(format![
            "Failed to compile file {} with exit code {}", 
            filepath, exit_code
        ])
    };

    let duration = now.num_seconds_from_midnight();
    info.log(&format![
        "Compilation of file {} completed in {} seconds with status: {}", 
        filepath, duration, status
    ]);

    let after_rss = get_resident_set_size();
    info.log(&format![
        "Resident set size before and after compilation is {} and {} respectively", 
        before_rss, after_rss
    ]);

    Ok(process.exit_code().unwrap())
}
```
This function spawns a sub-process to run the Rust compiler with a given filepath, and measures the time taken for compilation using `chrono::Local::now()`. It uses `rustc_driver::catch_with_exit_code` to catch any errors during compilation and report it. The function also checks if the resident set size (RSS) exceeds the maximum threshold before starting the compilation process. If so, it terminates the sub-process with `process.kill()` and returns an error message.

