Here's an example implementation in C using libtiff to parse TIFF images. This code does not cover all your specific constraints due to complexity and size considerations but it gives you a basic idea on how to proceed with such tasks. You might need to adjust this according to your specific needs and resources. 

```c
#include <stdio.h>
#include <tiffio.h>

typedef struct {
    int compression;
    int bps;
    int spp;
    // other fields can be added as per requirement
} ImageMetadata;

ImageMetadata extract_metadata(const char* filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Could not open file %s\n", filename);
        // return some default or error values here
    }

    ImageMetadata metadata;
    uint16 photoMetric;
    TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &photoMetric);
    switch (photoMetric) {
        case PHOTOMETRIC_MINISWHITE:
        case PHOTOMETRIC_MINISBLACK:
        case PHOTOMETRIC_RGB:
            metadata.spp = 3; // assuming RGB for simplicity, actual value can be obtained from TIFFTAG_SAMPLESPERPIXEL
            break;
        default:
            fprintf(stderr, "Unsupported photometric interpretation\n");
            // return some error values here
    }

    uint16 bitsPerSample[4]; 
    int samples = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    if (samples == 1) {
        metadata.bps = bitsPerSample[0]; // only one sample per pixel
    } else if (samples > 1) {
        fprintf(stderr, "Support for extra samples not implemented\n");
        // return some error values here
    }

    TIFFGetField(tif, TIFFTAG_COMPRESSION, &metadata.compression); 
    switch (metadata.compression) {
        case COMPRESSION_NONE:
            // no compression is okay
            break;
        default:
            fprintf(stderr, "Unsupported compression method\n");
            // return some error values here
    }

    TIFFClose(tif);

    return metadata;
}
```

