Here's a very basic example of how to get an IP address from hostname using C:

```c
#include <stdio.h>
#include <netdb.h> 
#include <arpa/inet.h> 

u_char* resolveHostname(const char *hostname) {
    struct hostent *he = gethostbyname(hostname);
    if (he == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    // Assuming IPv4 for simplicity 
    struct in_addr **addr_list = (struct in_addr **) he->h_addr_list;
    u_char* ipv4 = malloc(sizeof(u_char)*INET6_ADDRSTRLEN);
    inet_ntop(AF_INET, addr_list[0], ipv4, INET_ADDRSTRLEN); 

    return ipv4;
}
```

