async function runModuleTests(moduleName, testCases, setUpFunction = null, tearDownFunction = null) {
    try {
        const module = await import(moduleName);

        if (setUpFunction) {
            await setUpFunction();
        }

        for (let i = 0; i < testCases.length; i++) {
            try {
                console.log(`Testing module '${moduleName}' with case '${testCases[i].name}'`);
                await testCases[i]();
            } catch (error) {
                console.error(`Error in '${testCases[i].name}': ${error.message}`);
            } finally {
                if (blueslip.resetMockData){
                    blueslip.resetMockData();
                }

                if (tearDownFunction) {
                    await tearDownFunction();
                }
            }
        }
    } catch(error) {
        console.error(`Failed to load module '${moduleName}': ${error.message}`);
    }
