pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
DES_cblock key;
DES_key_schedule schedule;
CURL *curl;

int DES_encrypt(const char* in, const char* out) {
    FILE *fin, *fout;
    fin = fopen(in, "rb");
    if (fin == NULL) return 1;
    fout = fopen(out, "wb");
    if (fout == NULL) return 2;

    DES_set_key(&key, &schedule);

    char buffer[8];
    size_t nread;
    while ((nread = fread(buffer, 1, sizeof buffer, fin)) > 0) {
        DES_ecb_encrypt((unsigned char*)buffer, (unsigned char*)buffer, &schedule, DES_ENCRYPT);
        if (fwrite(buffer, 1, nread, fout) < nread) return 3;
    }

    fclose(fin);
    fclose(fout);
    return 0;
}

void* downloadFile(void* url) {
    pthread_mutex_lock(&lock);
    CURLcode res;
    FILE *fp;
    curl = curl_easy_init();
    if (curl) {
        fp = fopen((char*)url, "wb");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        fclose(fp);
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}
