from collections import Counter

def process_logs(filename):
    df = pd.read_csv(filename)

    # Assuming that the errors and bottlenecks are included in a 'message' column
    error_messages = df[df['message'].str.contains('ERROR')]
    common_errors = Counter(error_messages['message']).most_common()

    slow_requests = df[df['execution_time'] > 100] # adjust the threshold as needed
    bottlenecks = Counter(slow_requests['endpoint']).most_common()

    print('Common errors:')
    for msg, count in common_errors:
        print(f'{msg} : {count}')

    print('Bottlenecks:')
    for endpoint, count in bottlenecks:
        print(f'{endpoint} : {count}')
