public class ListManipulator
{
    public void InsertAfterFirstOccurrence(List<string> list, string target, string newString)
    {
        for (var i = 0; i < list.Count; ++i)
        {
            if (!list[i].Equals(target)) continue;

            list.Insert(i + 1, newString);
            return;
        }

        // If target string is not found in the list, append it to the end
        list.Add(newString);
    }
}
