```cpp
#include <mutex>
#include <forward_list>

std::mutex mtx;

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
    std::lock_guard<std::mutex> lock(mtx);  // Ensure thread safety.

    auto prev = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it, ++prev){
        if (*it == target) {  
            list.insert_after(it, value);  // Insert after the first occurrence of 'target'.
            return;
        }
    }

    list.insert_after(prev, value);  // If 'target' not found, append 'value'.
}
```
This implementation uses a `std::mutex` to ensure thread safety and avoid race conditions during concurrent modifications. It iterates through the forward list looking for the first occurrence of `target`. Upon finding it, it inserts `value` after `target` using `insert_after()` and then returns early. If no occurrences of `target` are found, `value` is appended to the end of the list.

