{
    public static List<Pokemon> LoadDataFromBinaryFile(string filePath)
    {
        if (!File.Exists(filePath)) 
            throw new FileNotFoundException("The specified file could not be found.", filePath);

        using (var fileStream = new FileStream(filePath, FileMode.Open))
        {
            var formatter = new BinaryFormatter();
            try
            {
                return ValidateAndReturnPokemonData((List<Pokemon>)formatter.Deserialize(fileStream));
            }
            catch (Exception ex) when (ex is ArgumentException || ex is InvalidCastException) 
            {
                Console.WriteLine("An error occurred while deserializing the data.");
                throw;
            }
        }
    }

    private static List<Pokemon> ValidateAndReturnPokemonData(List<Pokemon> pokemons)
    {
        foreach (var pokemon in pokemons)
        {
            if (string.IsNullOrEmpty(pokemon.Type)) 
                throw new ArgumentException("The type of the Pokemon cannot be null or empty.");

            // Add more validations as per your requirement
        }

        return pokemons;
    }
}
