        MT19937Generator(long _seed) : generator(_seed), seedValue(_seed){
            if(!openDB()) throw std::runtime_error("Unable to connect to the DB.");
            char* errorMessage = nullptr;
            // Create the table for storing seeds (for simplicity, a single-column table is assumed)
            std::string sqlStatement = "CREATE TABLE IF NOT EXISTS " + table_name + "(seed INTEGER);";
            int res = sqlite3_exec(db, sqlStatement.c_str(), nullptr, 0, &errorMessage);

            if (res != SQLITE_OK){
                std::string errorMsg("Error creating table: ");
                errorMsg += errorMessage;
                sqlite3_free(errorMessage);
                throw std::runtime_error(errorMsg);
            }
        }
        ~MT19937Generator(){ 
            // Close DB connection and free cache memory
            if(db){
                sqlite3_close(db);
            }
