        }
        int nextInt(int min, int max){
            if (min > max) throw std::invalid_argument("Invalid range.");
            // Check cache before generating a new number 
            if(cacheEnabled && cache.count(currentStream) != 0){
                return cache[currentStream];
            }

            int generatedNumber = generator() % (max - min + 1) + min;
            // Store generated number in cache for future use
            if(cacheEnabled){
                cache[currentStream] = generatedNumber;
            }
            return generatedNumber;
        } 

        void enableCache(){
            cacheEnabled = true;
        }
        void disableCache(){
            cacheEnabled = false;
        }
