            // Open DB connection using the SQLite API and handle any potential errors.
            int rc = sqlite3_open("randomGeneratorDB.db", &db);  // Database file name is "randomGeneratorDB.db" for simplicity
            if(rc){
                return false;
            }else{
                return true;
            }
        }
    };
}
