Here is a pseudo-code representation of `dnsAsyncResolve` in C using pthread for concurrent execution and error handling mechanism:
```c
#include <pthread.h>
#include <netdb.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

// Error handling mechanism
enum {
    SUCCESS,
    EMPTY_HOSTNAME,
    NON_NUMERIC_INPUT,
    RESOLVE_FAILURE
};

typedef struct dnsResolutionData {
    char hostname[256];
    u_char (*callback)(struct in_addr *);
} dnsResolutionData;

void* resolveDNS(void* data) {
    dnsResolutionData* d = (dnsResolutionData*)data;

    struct hostent *host = gethostbyname(d->hostname);
    if (!host) {
        // Handle error here, for simplicity returning failure code.
        return (void*)RESOLVE_FAILURE; 
    }

    int i = 0;
    while (host->h_addr_list[i] != NULL) {
        struct in_addr addr;
        memcpy(&addr.s_addr, host->h_addr_list[i], sizeof(addr.s_addr));

        // Call callback for each resolved IP address
        d->callback(&addr);
        i++;
    }

    return (void*)SUCCESS;
}

int dnsAsyncResolve(char* hostname, u_char (*callback)(struct in_addr *)) {
    if (!strcmp(hostname, "")) {
        return EMPTY_HOSTNAME;  // Handle empty hostname case.
    }

    for (int i = 0; hostname[i] != '\0'; i++) {
        if (!isdigit(hostname[i]) && hostname[i] != '.') {
            return NON_NUMERIC_INPUT;  // Handle non-numeric input case.
        }
    }

    pthread_t threadID;

    dnsResolutionData* data = malloc(sizeof(*data));
    strcpy(data->hostname, hostname);
    data->callback = callback;

    if (pthread_create(&threadID, NULL, &resolveDNS, (void*)data) != 0) {
        return RESOLVE_FAILURE;  // Handle thread creation failure.
    }

    pthread_detach(threadID);
    return SUCCESS;
}
```
