```cpp
#include <string>
#include <vector>
#include <openssl/sha.h>
#include <aws/core/Aws.h>
#include <aws/s3/S3Client.h>
#include <aws/s3/model/PutObjectRequest.h>

class CloudStorageClient {
public:
    CloudStorageClient() : s3_client(Aws::S3::S3Client()) {}
    ~CloudStorageClient() { Aws::ShutdownAPI(options); }

    void UploadFile(const std::string& bucketName, const std::string& filePath) {
        Aws::S3::Model::PutObjectRequest request;
        request.WithBucket(bucketName).WithKey(filePath);

        auto outcome = s3_client.PutObject(request);
        if (!outcome.IsSuccess()) {
            std::cerr << "Error: PutObject: " << outcome.GetError().GetMessage() << std::endl;
            exit(1);
        } else {
            std::cout << "Uploaded file successfully." << std::endl;
        }
    }

    void MonitorFileUploadProgress() {} // Implementation depends on the cloud storage service's API.

    void DownloadFile() {}  // Similar to UploadFile, but for downloading files.

    void CalculateSHA256(const std::string& filePath) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);

        // Read the file in chunks and update the SHA256 hash.
        unsigned char buffer[4096];
        std::ifstream infile(filePath, std::ios::binary);
        while (infile) {
            infile.read((char*)buffer, sizeof(buffer));
            std::streamsize bytesRead = infile.gcount();
            if (bytesRead > 0) {
                SHA256_Update(&sha256, buffer, bytesRead);
            }
        }

        // Compute the final hash and print it in hexadecimal format.
        unsigned int mdLength = SHA256_DIGEST_LENGTH;
        char* mdValue = new char[2 * mdLength + 1];
        SHA256_Final((unsigned char*)buffer, &sha256);

        for (int i = 0; i < mdLength; ++i) {
            sprintf(&mdValue[2*i], "%02x", buffer[i]);
        }
    }
private:
    Aws::SDKOptions options;
    Aws::S3::S3Client s3_client;
};
```
