using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;
using log4net; // for logging

public class XmlParser
{
    private static readonly ILog logger = LogManager.GetLogger(typeof(XmlParser));
    private static readonly HttpClient client = new HttpClient();

    public async Task<string> GetFirstElementAsync(string url, string elementName)
    {
        try
        {
            var contentStream = await client.GetStreamAsync(url); // for HTTP request

            using (var reader = XmlReader.Create(contentStream))
            {
                while (await reader.ReadAsync())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == elementName)
                    {
                        await reader.ReadAsync(); // move to the text content
                        return reader.Value;
                    }
                }
            }
        }
        catch(HttpRequestException e) 
        {
            logger.Error("HTTP request failed.", e);
            throw;
        }
        catch (XmlException e) 
        {
            logger.Error("Invalid XML structure.", e);
            throw;
        }

        return null; // not found or multiple elements
    }
}
```
